window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[23]={"id":"023","numero":23,"titre":"Grossesse normale","objectifs":[{"id":"23-1","rang":"A","rubrique":"Physiopathologie","titre":"Connaître les modifications physiologiques au cours de la grossesse","contenu":"<div class=\"notion-course\"><p>La <span>grossesse</span> entraîne des modifications anatomiques et physiologiques chez la mère, induites par les <strong>sécrétions hormonales</strong>. Tous les systèmes sont atteints mais les modifications les plus importantes sont <span>métaboliques, respiratoires et cardiovasculaires</span>.</p>\n\n      <h4>Modifications respiratoires</h4>\n\n      <table>\n        <thead><tr><th>Système</th><th>Modifications</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Anatomie pulmonaire</strong><br>(croissance utérine)</td>\n            <td>\n              <ul>\n                <li>Élargissement de la <span class=\"nc-blue_bg\">cage thoracique</span></li>\n                <li><strong><span class=\"nc-pink nc-bold\">Élévation</span> du <span class=\"nc-pink nc-bold\">diaphragme</span></strong></li>\n                <li>Augmentation du <span><span class=\"nc-blue_bg\">diamètre</span></span><span class=\"nc-blue_bg\"> transversal des poumons</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Volumes respiratoires</strong></td>\n            <td>\n              <ul>\n                <li>↑ <span class=\"nc-yellow_bg\">ventilation</span> (effet <em>progestérone</em>)</li>\n                <li>↑ consommation en O<sub>2</sub></li>\n                <li>↑ <span>capacité vitale</span> (<span>CV</span>) et volume courant (Vt)</li>\n                <li>↓ réserve expiratoire</li>\n                <li>→ ↑ capacité inspiratoire + ↓ volume résiduel (Vr)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Gaz du sang</span></strong></td>\n            <td>\n              <ul>\n                <li><strong><span><span class=\"nc-green_bg\">pH</span></span><span class=\"nc-green_bg\"> peu modifié</span></strong> (baisse équivalente de PaCO<sub>2</sub> et HCO<sub>3</sub><sup>−</sup>)</li>\n                <li>↓ PaCO<sub>2</sub> (<span>dyspnée</span> / etouffement, ↓ <span>bicarbonates</span>)</li>\n                <li>↑ PaO<sub>2</sub></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Modifications cardio-circulatoires</h4>\n\n      <p>Modifications hormonales : <strong>Œstrogènes</strong> (↑ FC et débits), <strong>Progestérone</strong> (<span class=\"nc-green_bg\">relâchement veineux</span>, <span class=\"nc-green_bg\">rétention hydrique</span>), <strong>SRAA</strong> (↑ <span class=\"nc-pink nc-bold\">rénine</span> rein + <span class=\"nc-yellow_bg\">placenta</span>, <span class=\"nc-pink nc-bold\">prorénine</span> fœtale, <span class=\"nc-pink nc-bold\">aldostérone plasmatique</span>).</p>\n\n      <table>\n        <thead><tr><th>Paramètre</th><th><span>Évolution</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Débit cardiaque<br>+ débit rénal</strong></td>\n            <td>↑ débit sanguin rénal (<span>+ 40 %</span>), ↑ filtration glomérulaire et ↑ débit cardiaque (en particulier à l’<em><span class=\"nc-yellow_bg\">accouchement</span></em>).</td>\n          </tr>\n          <tr>\n            <td><strong>Pressions artérielles</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"nc-red nc-bold\">Chute</span></strong> au 1<sup>er</sup> trimestre (−<span> 5–10 mmHg</span>)</li>\n                <li><strong><span class=\"nc-red nc-bold\">Stable</span></strong> au 2<sup>nd</sup> trimestre</li>\n                <li><strong><span class=\"nc-green nc-bold\">Normalisation</span></strong> au 3<sup>e</sup> trimestre</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Pressions veineuses</strong><br>(<span class=\"nc-yellow_bg\">effet Poseiro</span>)</td>\n            <td>\n              <ul>\n                <li>Pressions oreillette droite <strong>non modifiées</strong></li>\n                <li>Compression utérine de la VCI (décubitus dorsal) gène le retour veineux → ↑ pressions veineuses <strong><span class=\"nc-red nc-bold\">membres inférieurs</span></strong></li>\n                <li>→ <span>ralentissement du rythme cardiaque fœtal</span> + <span><span class=\"nc-red nc-bold\">malaise maternel</span></span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Volémie</strong></td>\n            <td><strong><span class=\"nc-yellow_bg\">Hypervolémie</span></strong> physiologique pour <em><span class=\"nc-green nc-bold\">limiter les conséquences de l’hémorragie lors de l’accouchement</span></em>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewbox=\"0 0 560 372\" role=\"img\" aria-label=\"Schéma de l&#x27;effet Poseiro : au 3e trimestre, l&#x27;utérus gravide en décubitus dorsal comprime la veine cave inférieure, ce qui réduit le retour veineux au cœur droit et le débit cardiaque, entraînant une bradycardie fœtale et un malaise maternel par hypotension. La conduite à tenir est le décubitus latéral gauche.\" style=\"height:auto;display:block;border-radius:8px\">\n          <rect class=\"fb-grey\" x=\"130\" y=\"12\" width=\"300\" height=\"48\" rx=\"6\"></rect>\n          <text class=\"tx-grey\" x=\"280\" y=\"33\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\">Utérus gravide (3ᵉ trimestre)</text>\n          <text class=\"tx-grey\" x=\"280\" y=\"50\" text-anchor=\"middle\" font-size=\"12\">+ décubitus dorsal</text>\n          <line class=\"ln\" x1=\"280\" y1=\"60\" x2=\"280\" y2=\"78\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"280,84 275,76 285,76\"></polygon>\n          <rect class=\"fb-red\" x=\"118\" y=\"86\" width=\"324\" height=\"46\" rx=\"6\"></rect>\n          <text class=\"tx-red\" x=\"280\" y=\"105\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\">Compression de la veine cave inférieure</text>\n          <text class=\"tx-red\" x=\"280\" y=\"122\" text-anchor=\"middle\" font-size=\"11.5\">(VCI, gêne le retour veineux au cœur droit)</text>\n          <line class=\"ln\" x1=\"280\" y1=\"132\" x2=\"280\" y2=\"150\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"280,156 275,148 285,148\"></polygon>\n          <rect class=\"fb-amber\" x=\"130\" y=\"158\" width=\"300\" height=\"48\" rx=\"6\"></rect>\n          <text class=\"tx-amber\" x=\"280\" y=\"179\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\">↓ Retour veineux au cœur droit</text>\n          <text class=\"tx-amber\" x=\"280\" y=\"196\" text-anchor=\"middle\" font-size=\"12\">→ ↓ débit cardiaque</text>\n          <line class=\"ln\" x1=\"280\" y1=\"206\" x2=\"280\" y2=\"222\" stroke-width=\"2\"></line>\n          <line class=\"ln\" x1=\"140\" y1=\"222\" x2=\"420\" y2=\"222\" stroke-width=\"2\"></line>\n          <line class=\"ln\" x1=\"140\" y1=\"222\" x2=\"140\" y2=\"240\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"140,246 135,238 145,238\"></polygon>\n          <line class=\"ln\" x1=\"420\" y1=\"222\" x2=\"420\" y2=\"240\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"420,246 415,238 425,238\"></polygon>\n          <rect class=\"fb-red\" x=\"20\" y=\"248\" width=\"240\" height=\"46\" rx=\"6\"></rect>\n          <text class=\"tx-red\" x=\"140\" y=\"267\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"600\"><span>Bradycardie</span> fœtale</text>\n          <text class=\"tx-red\" x=\"140\" y=\"284\" text-anchor=\"middle\" font-size=\"11\">(souffrance fœtale)</text>\n          <rect class=\"fb-red\" x=\"300\" y=\"248\" width=\"240\" height=\"46\" rx=\"6\"></rect>\n          <text class=\"tx-red\" x=\"420\" y=\"267\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"600\"><span>Malaise</span> maternel</text>\n          <text class=\"tx-red\" x=\"420\" y=\"284\" text-anchor=\"middle\" font-size=\"11\">(<span>hypotension</span>)</text>\n          <line class=\"ln\" x1=\"140\" y1=\"294\" x2=\"140\" y2=\"312\" stroke-width=\"2\"></line>\n          <line class=\"ln\" x1=\"420\" y1=\"294\" x2=\"420\" y2=\"312\" stroke-width=\"2\"></line>\n          <line class=\"ln\" x1=\"140\" y1=\"312\" x2=\"420\" y2=\"312\" stroke-width=\"2\"></line>\n          <line class=\"ln\" x1=\"280\" y1=\"312\" x2=\"280\" y2=\"326\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"280,332 275,324 285,324\"></polygon>\n          <rect class=\"fb-ok\" x=\"118\" y=\"334\" width=\"324\" height=\"34\" rx=\"6\"></rect>\n          <text class=\"tx-ok\" x=\"280\" y=\"356\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\">CAT — décubitus latéral GAUCHE</text>\n        </svg>\n        <figcaption>Effet Poseiro : au T3, éviter le décubitus dorsal prolongé — le décubitus latéral gauche lève la compression de la VCI (auscultation des BDC, repos, accouchement).</figcaption>\n      </figure>\n\n      <h4>Hémostase et <span>NFS</span> — la <span>grossesse</span> est <span class=\"nc-red nc-bold\">procoagulante</span></h4>\n\n      <table>\n        <thead><tr><th><span>NFS</span></th><th>Hémostase (procoagulante)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <ul>\n                <li>GR : <span>3,8–4 M/mL</span></li>\n                <li><span>Leucocytes</span> normaux : <span>&lt; 15 000/mL</span></li>\n                <li>PNN très augmentés (<span class=\"nc-brown nc-bold\">myélocytes</span> et <span class=\"nc-brown nc-bold\">métamyélocytes</span> à <span>3 %</span>)</li>\n                <li><span class=\"nc-yellow_bg\">Hb : </span><span><span class=\"nc-yellow_bg\">11–12 g/dL</span></span>, <span>VGM</span> et <span>CCMH</span> inchangés</li>\n                <li><span>Plaquettes</span> quasi constantes, ↓ en fin de <span>grossesse</span></li>\n                <li><span>VS</span> ↑ (<em>aucun intérêt pendant la <span>grossesse</span></em>)</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span>Fibrinogène</span> ↑ (<span>5–6 g/L</span>)</li>\n                <li>Facteurs <span class=\"nc-blue_bg\">VII</span> et <span class=\"nc-blue_bg\">VIII</span> très ↑ (<span class=\"nc-blue_bg\">VII</span> =<span> 200 %</span>)</li>\n                <li>Facteurs IX, X, XII ↑ (X =<span> 150 %</span>)</li>\n                <li>Facteur II ↑ (<span>128 %</span>)</li>\n                <li>Facteur V inchangé ou légèrement ↑</li>\n                <li>Facteurs <strong>XI et XIII</strong> ↓ (<span>50–60 %</span>)</li>\n                <li><strong>ATIII</strong> ↓ (<span>10 %</span>) et <strong>protéine S</strong> ↓</li>\n                <li>Activité fibrinolytique ↓</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Endocrinien et métabolisme</h4>\n\n      <table>\n        <thead><tr><th>Système</th><th>Modifications</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Hypophyse +++</strong></td><td><span class=\"nc-green_bg\">Hypervascularisation</span> + <span class=\"nc-green_bg\">hyperplasie</span> · <strong><span class=\"nc-pink nc-bold\">Ocytocine</span></strong></td></tr>\n          <tr><td><strong>Corticotrope</strong></td><td><span class=\"nc-orange_bg\">Hypercorticisme</span> physiologique et adaptatif</td></tr>\n          <tr><td><strong>Thyroïde</strong></td><td>↑ fonctionnement : <em><span class=\"nc-green_bg\">hypertrophie</span> <span class=\"nc-green_bg\">/ goitre</span></em> (↓ iode organique plasmatique) · <span>TSH</span> légèrement ↓ (surtout 1<sup>er</sup> trim) · T3-T4 normales</td></tr>\n          <tr><td><strong>Parathyroïdes</strong></td><td>Globalement : ↓ <span>calcémie</span></td></tr>\n          <tr><td><strong>Métabolisme basal</strong></td><td>↑ <span><span class=\"nc-pink nc-bold\">+15 à 30 %</span></span> · accumulation de <span class=\"nc-green nc-bold\">réserves</span> au T1/T2, mobilisation au profit du <span class=\"nc-green nc-bold\">fœtus</span> au T3</td></tr>\n          <tr>\n            <td><strong>Métabolisme glucidique</strong></td>\n            <td>\n              <ul>\n                <li>1<sup>er</sup> trim : ↑ sensibilité à l’<span>insuline</span> (<span>glycémie</span> plutôt basse)</li>\n                <li>2<sup>nd</sup> trim : <strong><span class=\"nc-orange_bg\">insulinorésistance</span></strong> (effet <span class=\"nc-pink nc-bold\">hormone lactogène placentaire</span> +++ et <span class=\"nc-pink nc-bold\">prolactine</span>), compensée par hyperinsulinisme — sinon <em><span>diabète gestationnel</span></em></li>\n              </ul>\n            </td>\n          </tr>\n          <tr><td><strong>Température</strong></td><td>Plateau thermique <span>≥ 37 °C</span> au 1<sup>er</sup> trim (progestérone) · tendance à l’<span>hypothermie</span> en fin de <span>grossesse</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Prise de poids gestationnelle</h4>\n\n      <ul>\n        <li><strong>Causes</strong> : accumulation de <span class=\"nc-green nc-bold\">liquide interstitiel</span> + <span class=\"nc-green nc-bold\">eau extracellulaire</span> + <span class=\"nc-green nc-bold\">réserves</span> <span class=\"nc-green nc-bold\">graisseuses</span> + <span class=\"nc-green nc-bold\">fœtus</span> / <span class=\"nc-green nc-bold\">placenta</span> / <span class=\"nc-green nc-bold\">liquide amniotique</span>.</li>\n        <li><strong>Moyenne</strong> : <span>≈ 13 kg</span>.</li>\n        <li><strong>Cinétique</strong> : faible au T1, plus marquée au T2/T3 (≈ <span>+1 kg/mois</span> T1-T2, <span>+500 g/mois</span> T3).</li>\n        <li><strong>Risques</strong> :\n          <ul>\n            <li>Excessive → <span><span class=\"nc-red nc-bold\">HTA</span></span><span class=\"nc-red nc-bold\"> gravidique</span>, <span class=\"nc-red nc-bold\">macrosomie</span>, <span class=\"nc-red nc-bold\">césarienne</span></li>\n            <li>Insuffisante → <span class=\"nc-red nc-bold\">faible poids de naissance</span>, <span class=\"nc-red nc-bold\">accouchement prématuré</span></li>\n          </ul>\n        </li>\n      </ul>\n\n      <table>\n        <thead>\n          <tr><th>IMC préconceptionnel (kg/m²)</th><th>Gain total recommandé</th><th>Taux moyen T2-T3 (kg/sem)</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>&lt; 18,5</strong> (insuffisance pondérale)</td><td><span>12,5 – 18 kg</span></td><td><span>0,5</span></td></tr>\n          <tr><td><strong>18,5 ≤ IMC <span>≤ 24,9</span></strong> (poids normal)</td><td><span>11,5 – 16 kg</span></td><td><span>0,4</span></td></tr>\n          <tr><td><strong>25,0 ≤ IMC <span>≤ 29,9</span></strong> (<span>surpoids</span>)</td><td><span>7 – 11,5 kg</span></td><td><span>0,3</span></td></tr>\n          <tr><td><strong><span>≥ 30</span></strong> (<span>obésité</span>)</td><td><span>5 – 9 kg</span></td><td><span>0,2</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Autres systèmes (synthèse)</h4>\n\n      <table>\n        <thead><tr><th>Système</th><th>Modifications</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Œsophage</strong></td><td>↓ tonus sphincter œsophagien inférieur → <em>pyrosis</em></td></tr>\n          <tr><td><strong>Estomac</strong></td><td>↓ tonicité et péristaltisme, ↑ pression gastrique, ouverture de l’angle de His, sécrétion de gastrine placentaire</td></tr>\n          <tr><td><strong>Foie</strong></td><td>↑ synthèse protéique (<span>albumine</span> +++) · TG (3 N) et <span><span class=\"nc-orange_bg\">cholestérol</span></span> (2 N) ↑ · <strong><span>PAL</span> ↑</strong> (origine placentaire)</td></tr>\n          <tr><td><strong><span>Vésicule</span> biliaire</strong></td><td>Atone, <span class=\"nc-red nc-bold\">vidange ralentie</span></td></tr>\n          <tr><td><strong>Grêle / Côlon</strong></td><td>↓ mobilité grêle · ↑ réabsorption eau + Na côlon</td></tr>\n          <tr><td><strong>Vasculaire</strong></td><td><span>Œdèmes</span> visage / extrémités, <span class=\"nc-blue_bg\">angiomes stellaires</span>, <span class=\"nc-brown_bg\">érythrose palmaire</span>, varices (hyperpression Poseiro)</td></tr>\n          <tr><td><strong>SNC</strong></td><td>↑ <span class=\"nc-pink nc-bold\">endorphines</span> / <span class=\"nc-pink nc-bold\">enképhalines</span> · ↓ <span class=\"nc-orange_bg\">attention</span>, <span class=\"nc-orange_bg\">insomnie</span>, post-partum blues</td></tr>\n          <tr><td><strong>Musculo-squelettique</strong></td><td>↑ mobilité articulations du bassin, <span class=\"nc-orange\">lordose</span></td></tr>\n          <tr>\n            <td><strong>Urinaire / rénal</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-blue_bg\">Dilatation urétérale</span> possible dès <span><span class=\"nc-pink nc-bold\">6 SA</span></span>, <strong><span class=\"nc-red nc-bold\">prédominante à</span> <span class=\"nc-red nc-bold\">droite</span></strong>, physiologique</li>\n                <li>↑ flux plasmatique et filtration glomérulaire (+<span> 40 %</span>) → ↑ taille/poids des reins, ↓ <span>urée</span> et <span>créatinine</span></li>\n                <li><span class=\"nc-yellow_bg\">Glycosurie</span> + acidurie aminée, ↑ modérée de <span>protéinurie</span> (<span>&lt; 300 mg/24 h</span>)</li>\n                <li><span class=\"nc-blue_bg\">Bilan sodé positif</span> (<span>+ 500-900 mmoles</span>), <span class=\"nc-blue_bg\">bilan hydrique positif</span> (<span>+ 6–8 L</span>) en fin de <span>grossesse</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr><td><strong>Peau</strong></td><td><span class=\"nc-blue_bg\">Vergetures</span>, <span class=\"nc-blue_bg\">ligne brune</span>, <span class=\"nc-blue_bg\">masque de </span><span><span class=\"nc-blue_bg\">grossesse</span></span> (<em>mélasma</em> — éviter le soleil), <span class=\"nc-brown_bg\">hyperpigmentation</span></td></tr>\n          <tr><td><strong>Seins</strong></td><td>↑ volume, modification aréoles / mamelons</td></tr>\n          <tr><td><strong>Yeux</strong></td><td>↑ pression intra-oculaire, <span>œdème</span> cornéen</td></tr>\n          <tr><td><strong>Génital</strong></td><td>Congestion vulvaire, ↑ épaisseur muqueuse vaginale, ↑ leucorrhées, ↓ <span>pH</span> vaginal</td></tr>\n        </tbody>\n      </table></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_2899354/fr/le-depistage-de-la-trisomie-21\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage de la trisomie 21</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li></ul></details>","frequence":0},{"id":"23-2","rang":"A","rubrique":"Diagnostic positif","titre":"Diagnostic de grossesse","contenu":"<div class=\"notion-course\"><p>📌 Le <span>diagnostic de grossesse <span class=\"nc-red nc-bold\">repose sur la clinique</span></span>, et si besoin, sur les examens complémentaires (test urinaire ou plasmatique hCG, <span><span class=\"nc-blue nc-bold\">échographie</span></span> pelvienne).</p>\n\n      <h4>Examen clinique</h4>\n\n      <table>\n        <thead><tr><th>Domaine</th><th>Signes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Signes fonctionnels</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-yellow_bg\">Retard de règles</span></li>\n                <li>Signes « sympathiques » : <span><span class=\"nc-blue nc-bold\">tension mammaire</span></span>, <span><span class=\"nc-blue nc-bold\">somnolence</span></span>, <span><span class=\"nc-blue nc-bold\">fatigue</span></span>, <span><span class=\"nc-blue nc-bold\">pollakiurie</span></span>, <span>nausées / <span class=\"nc-blue nc-bold\">vomissements</span></span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Spéculum</strong> <em>(non systématique)</em></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-blue_bg\">Col violacé</span></li>\n                <li><span class=\"nc-blue_bg\">Glaire cervicale coagulée voire absente</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Toucher vaginal</strong> <em>(non systématique)</em></td>\n            <td>\n              <ul>\n                <li>Ramollissement utérin commence à la <span>8<sup>e</sup> SA</span></li>\n                <li><span class=\"nc-green_bg\">Augmentation du volume</span> utérin : épaississement avant/arrière, <span class=\"nc-blue_bg\">forme sphérique</span></li>\n                <li><strong><span class=\"nc-yellow_bg\">Signe de Noble</span></strong> (doigt dans les <span class=\"nc-purple nc-bold\">culs-de-sac latéraux</span> bute contre le contour évasé de l’utérus)</li>\n                <li>Comparaisons : <strong><span class=\"nc-pink nc-bold\">Mandarine</span></strong> (7<sup>e</sup> SA), <strong><span class=\"nc-pink nc-bold\">Orange</span></strong> (10-12<sup>e</sup> SA), <strong><span class=\"nc-pink nc-bold\">Pamplemousse</span></strong> (14<sup>e</sup> SA)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Doppler</span> fœtal</strong></td>\n            <td>\n              <ul>\n                <li>BDC perçus à la fin du 3<sup>e</sup> mois, parfois dès <span><span class=\"nc-pink nc-bold\">9 SA</span></span></li>\n                <li>Valeurs : <span><span class=\"nc-pink_bg\">190–200 bpm</span></span> à <span>9 SA</span>, <span><span class=\"nc-pink_bg\">130–150 bpm</span></span> à <span>14 SA</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Anthropométrie</strong></td>\n            <td>Prise du poids, PA, taille → calcul de l’IMC</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Tests de <span>grossesse</span> (en cas de doute diagnostique)</h4>\n\n      <p>Tous basés sur la détection de <strong>l’hCG</strong>. Tests urinaires <span class=\"nc-red nc-bold\">vendus en pharmacie </span><em><span class=\"nc-red nc-bold\">sans ordonnance</span> et <span class=\"nc-red nc-bold\">non remboursés</span></em>. Test de référence : <strong>dosage plasmatique de l’hCG</strong>.</p>\n\n      <table>\n        <thead><tr><th>Test</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Test urinaire</strong></td>\n            <td>\n              <ul>\n                <li>Colorimétrique qualitatif, anticorps monoclonaux — très fiable mais non Se / Sp à<span> 100 %</span></li>\n                <li><strong>FP</strong> : <span>protéinurie</span>, <span>hématurie</span>, certains médicaments (BZD, neuroleptiques), &lt; 15 j après injection d’hCG (AMP)</li>\n                <li><strong>FN</strong> : forte densité urinaire (↑ <span>pH</span>, urates, restriction hydrique)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>β-hCG plasmatique</strong></td>\n            <td>\n              <ul>\n                <li>Test immunologique très fiable pour le <strong>diagnostic</strong> ✅</li>\n                <li><strong>Pas pour la datation</strong> ❌</li>\n                <li>Qualitatif (positif/négatif) ou quantitatif (UI/L)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Échographie</span> pelvienne</strong></td>\n            <td>\n              <ul>\n                <li>Sac gestationnel visible <strong><span class=\"nc-pink nc-bold\">dès 5 SA</span></strong> (voie vaginale, hCG &gt; 1 <span>500 UI/L</span>)</li>\n                <li>Activité cardiaque visible <strong><span class=\"nc-pink nc-bold\">dès 5 SA</span> + ½</strong> (<span>échographie</span> vaginale)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Rappel — physiologie de l’hCG</h4>\n\n      <ul>\n        <li>Sécrétée par les cellules trophoblastiques puis par le placenta.</li>\n        <li>Détectable dès le <span>9<sup>e</sup> jour</span> post-fécondation (= 2 j post-implantation).</li>\n        <li><strong><span class=\"nc-pink nc-bold\">Double toutes les </span><span><span class=\"nc-pink nc-bold\">48 h</span></span></strong> au 1<sup>er</sup> trimestre.</li>\n        <li><span class=\"nc-red nc-bold\">Chute</span> au 2<sup>e</sup> trimestre, plateau à ~5 <span>000 UI</span> jusqu’à fin de <span>grossesse</span>.</li>\n        <li>Disparaît dans les 5 j post-accouchement.</li>\n        <li><strong>Rôle</strong> : stimuler le corps jaune (maintien de la <span>grossesse</span> au T1, jusqu’au relais placentaire au T2).</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — <span>Grossesse</span> extra-utérine</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_2899354/fr/le-depistage-de-la-trisomie-21\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage de la trisomie 21</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li></ul></details>","frequence":0},{"id":"23-3","rang":"A","rubrique":"Prise en charge","titre":"Détermination du terme","contenu":"<div class=\"notion-course\"><p>Il faut fixer une <strong>date de début de <span>grossesse</span></strong> pour la déclaration et calculer le terme. Avoir un âge gestationnel exact est primordial sur le plan <span>légal</span> (déclaration, congé <span class=\"nc-yellow_bg\">prénatal</span>) et <span>médical</span> (prématurité, <span class=\"nc-red nc-bold\">RCIU</span>, <span class=\"nc-red nc-bold\">macrosomie</span>, dépassement de terme).</p>\n\n      <h4>Définitions et durée</h4>\n\n      <table>\n        <thead><tr><th>Notion</th><th>Définition / valeur</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>SA</strong></td>\n            <td>Semaines depuis le <strong>1<sup>er</sup> jour des dernières règles</strong>. Le début de <span>grossesse</span> correspond au jour de l’ovulation = <strong>J14 du cycle</strong> (sachant que <span>J1</span> du cycle = 1<sup>er</sup> jour des règles).</td>\n          </tr>\n          <tr>\n            <td><strong>Durée moyenne</strong></td>\n            <td><span>285 jours</span> = <span><span class=\"nc-pink nc-bold\">40,5 SA</span></span> (varie 280-290 j, soit 40 à 41 SA + 3 j).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Calcul du terme</h4>\n\n      <ul>\n        <li>Date début de <span>grossesse</span> + <strong><span>9 mois</span></strong></li>\n        <li>Date du 1<sup>er</sup> jour des dernières règles + <strong><span>14 jours</span> +<span> 9 mois</span></strong></li>\n        <li>En cas de <strong>FIV</strong> : date de début de <span>grossesse</span> = date de <span>ponction</span> (= jour de fécondation)</li>\n      </ul>\n\n      <h4>Méthodes de datation</h4>\n\n      <table>\n        <thead><tr><th>Méthode</th><th>Performance</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Datation selon dernières règles</strong></td>\n            <td><em>Imprécis</em> dans <span>10–30 %</span> des cas (mauvais reflet de l’âge gestationnel).</td>\n          </tr>\n          <tr>\n            <td><strong>Datation échographique</strong> ✅</td>\n            <td>\n              <ul>\n                <li>Mesure : <strong>longueur cranio-caudale (<span class=\"nc-blue_bg\">LCC</span>)</strong></li>\n                <li>Quand : entre <strong>11 SA et 13 SA + 6 j</strong></li>\n                <li><strong>Précision :<span> 4 jours</span></strong> (moyen le plus fiable)</li>\n                <li>Valeurs indicatives : <span>45 mm</span> (11 SA), <span>56 mm</span> (12 SA), <span>72 mm</span> (13 SA), <span>85 mm</span> (14 SA)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Repère trimestriel</h4>\n\n      <table>\n        <thead>\n          <tr><th></th><th>1<sup>er</sup> trimestre</th><th>2<sup>e</sup> trimestre</th><th>3<sup>e</sup> trimestre</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Semaines de <span>grossesse</span></strong></td><td>&lt; 14</td><td>14 – 26</td><td>&gt; 26</td></tr>\n          <tr><td><strong>Semaines d’aménorrhée (SA)</strong></td><td>&lt; <strong>16</strong></td><td>16 – <strong>28</strong></td><td>&gt; 28</td></tr>\n        </tbody>\n      </table></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_2899354/fr/le-depistage-de-la-trisomie-21\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage de la trisomie 21</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li></ul></details>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/crown-rump-length","label":"Radiopaedia : Crown-rump length (LCC)"}]},{"id":"23-4","rang":"B","rubrique":"Epidémiologie","titre":"Évaluation des facteurs de risque (médicaux et psycho-sociaux dont professionnels)","contenu":"<div class=\"notion-course\"><p>L’évaluation des FdR est <span>indispensable lors de la consultation du 1<sup>er</sup> trimestre</span> car la <strong>découverte d’un FdR modifie le type de <span>suivi</span> obstétrical (A, A1, A2, B)</strong>.</p>\n\n      <h4>Répartition épidémiologique de la gravité</h4>\n\n      <ul>\n        <li>Grossesses normales : <span>60 %</span></li>\n        <li>Grossesses difficiles : <span>40 %</span></li>\n        <li>Grossesses à risque : <span>10 %</span></li>\n      </ul>\n\n      <h4>Complications pouvant être prévenues par un bon <span>suivi</span></h4>\n\n      <ul>\n        <li>Anémie · <span>HTA</span> · Immunisation Rh</li>\n        <li><span>Infection urinaire</span> · Maladie sexuellement transmissible</li>\n        <li><span class=\"nc-red nc-bold\">Macrosomie</span> et prise en charge du <span>diabète</span></li>\n        <li>Siège</li>\n        <li>Travail prématuré · RCIU</li>\n        <li>Hypoxie et mort in utero en cas de terme dépassé</li>\n      </ul>\n\n      <h4><span>Facteurs de risque</span> à rechercher à l’interrogatoire</h4>\n\n      <table>\n        <thead><tr><th>Catégorie</th><th>Éléments</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Âge</strong></td><td><span>&lt; 15 ans</span> et <span>&gt; 35 ans</span></td></tr>\n          <tr>\n            <td><strong>ATCD familiaux</strong></td>\n            <td>\n              <ul>\n                <li>Maladie <span>héréditaire</span> (mucoviscidose, retard mental, myopathie, anomalie chromosomique, hémophilie)</li>\n                <li><span>HTA</span>, <span>diabète</span>, maladie thrombo-<span>embolique</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>ATCD personnels — médicaux</strong></td>\n            <td>\n              <ul>\n                <li><strong>IMC &gt;<span> 25 kg/m²</span></strong></li>\n                <li><span>Tabac</span>, <span><span class=\"nc-orange_bg\">alcool</span></span>, toxicomanie</li>\n                <li>Affection nécessitant médicaments potentiellement tératogènes</li>\n                <li><strong><span class=\"nc-pink nc-bold\">Perturbateurs endocriniens</span></strong></li>\n                <li><span>HTA</span>, infections urinaires, comitialité</li>\n                <li><span>VIH</span>, <span>hépatite</span> B ou C, <span>allergie</span>, immunisation rhésus</li>\n                <li>Maladie endocrinienne, thrombophilie, néphropathie, <span>diabète</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>ATCD personnels — chirurgicaux</strong></td>\n            <td><span class=\"nc-orange_bg\">Fracture du bassin</span>, <strong><span><span class=\"nc-pink nc-bold\">chirurgie</span></span><span class=\"nc-pink nc-bold\"> utérine</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong>ATCD gynécologiques</strong></td>\n            <td><span class=\"nc-orange_bg\">Fibrome</span>, <span class=\"nc-orange_bg\">herpès génital</span>, malformation utérine</td>\n          </tr>\n          <tr>\n            <td><strong>ATCD obstétricaux<br>(pathologie pouvant récidiver)</strong></td>\n            <td>\n              <ul>\n                <li>GEU, FCS</li>\n                <li><span>HTA</span>, pré-éclampsie</li>\n                <li>Malformation fœtale, <span class=\"nc-red nc-bold\">accouchement prématuré</span></li>\n                <li>Cholestase gravidique, <span>diabète gestationnel</span></li>\n                <li><span class=\"nc-red nc-bold\">Césarienne</span>, poids des précédents enfants, devenir néonatal</li>\n                <li>HRP, incompatibilité fœto-maternelle, cancer du sein</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>ATCD <span>infectieux</span></strong></td>\n            <td><span class=\"nc-purple_bg\">Toxoplasmose</span>, rubéole, herpès buccal, syphilis · séjour en zone d’endémie <em>Zika</em></td>\n          </tr>\n          <tr>\n            <td><strong>Socio-économiques</strong></td>\n            <td><span class=\"nc-green_bg\">Précarité</span>, <span class=\"nc-green_bg\">chômage</span>, mère <span class=\"nc-green_bg\">célibataire</span>, <span class=\"nc-green_bg\">migrante</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Mode de <span>surveillance</span> obstétricale en fonction du risque</h4>\n\n      <table>\n        <thead><tr><th><span>Suivi</span></th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><strong>A</strong></td><td>Pas de situation à risque ou faible niveau de risque → <span>suivi</span> par <span class=\"nc-green_bg\">sage-femme</span> ou <span class=\"nc-green_bg\">médecin</span> (généraliste, gynéco médical, gynéco-<span class=\"nc-green_bg\">obstétricien</span> au choix de la femme).</td></tr>\n          <tr><td><strong>A1</strong></td><td>Avis d’un gynécologue obstétricien et/ou d’un autre spécialiste <strong><span class=\"nc-orange_bg\">conseillé</span></strong>.</td></tr>\n          <tr><td><strong>A2</strong></td><td>Avis d’un gynécologue obstétricien <strong><span class=\"nc-yellow_bg nc-bold\">nécessaire</span></strong> (± avis d’un autre spécialiste).</td></tr>\n          <tr><td><strong>B</strong></td><td>Niveau de risque élevé → <span>suivi</span> régulier <strong>par un gynécologue obstétricien</strong>.</td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 29 — Risques professionnels et maternité</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_2899354/fr/le-depistage-de-la-trisomie-21\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage de la trisomie 21</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li></ul></details>","frequence":0},{"id":"23-5","rang":"B","rubrique":"Prise en charge","titre":"Savoir adapter le choix de la maternité","contenu":"<div class=\"notion-course\"><p>Les futurs parents s’orientent vers les maternités <strong><span class=\"nc-green_bg\">selon leurs désirs</span></strong> (préférences, lieu d’habitation) et <strong><span class=\"nc-orange_bg\">selon le niveau de risque de la </span><span><span class=\"nc-orange_bg\">grossesse</span></span></strong> mis en évidence par le <span>suivi</span>.</p>\n\n      <p>👉 Le <span>lieu d’accouchement est constamment réévalué</span> lors des consultations de <span>suivi</span> prénatal.</p>\n\n      <h4><span>Classification</span> des maternités selon le plateau technique pédiatrique</h4>\n\n      <table>\n        <thead><tr><th>Type</th><th>%</th><th>Plateau technique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Type 1</strong></td>\n            <td><span>50 %</span></td>\n            <td>Très grande majorité — prise en charge des <strong><span class=\"nc-green_bg\">grossesses à bas risque</span></strong>, <em>pas d’<span class=\"nc-yellow_bg\">unité de néonatalogie</span></em>.</td>\n          </tr>\n          <tr>\n            <td><strong>Type 2a</strong></td>\n            <td><span>23 %</span></td>\n            <td><span class=\"nc-yellow_bg\">Unité de </span><strong><span class=\"nc-yellow_bg\">néonatalogie</span></strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Type 2b</strong></td>\n            <td><span>16 %</span></td>\n            <td><span class=\"nc-orange_bg\">Unité de </span><strong><span><span class=\"nc-orange_bg\">soins intensifs</span></span><span class=\"nc-orange_bg\"> de néonatalogie</span></strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Type 3</strong></td>\n            <td><span>12 %</span></td>\n            <td><span class=\"nc-red_bg\">Unité de </span><strong><span><span class=\"nc-red_bg\">réanimation</span></span><span class=\"nc-red_bg\"> néonatale</span></strong>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Autres lieux d’accouchement (faible pourcentage, faible niveau de risque)</h4>\n\n      <ul>\n        <li><strong>Espaces dits « physiologiques »</strong> (internes à une maternité)</li>\n        <li><strong>Maisons de naissance</strong> : lieu d’accueil sous la responsabilité exclusive des <span class=\"nc-green_bg\">sages-femmes</span>, pour des grossesses se présentant a priori comme normales</li>\n      </ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_2899354/fr/le-depistage-de-la-trisomie-21\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage de la trisomie 21</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li></ul></details>","frequence":0},{"id":"23-6","rang":"A","rubrique":"Prise en charge","titre":"Déclaration de la grossesse","contenu":"<div class=\"notion-course\"><p>La <span>déclaration de grossesse</span> est une formalité administrative obligatoire qui permet la <span>prise en charge à 100 % par l’assurance maladie</span>.</p>\n\n      <h4>Modalités</h4>\n\n      <table>\n        <thead><tr><th>Item</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Support</strong></td>\n            <td><span class=\"nc-yellow_bg\">Formulaire réglementaire</span> (aujourd’hui <strong><span class=\"nc-red nc-bold\">possible en ligne</span></strong>).</td>\n          </tr>\n          <tr>\n            <td><strong>Quand ?</strong></td>\n            <td>Théoriquement avant <span>14 semaines de grossesse</span> · selon HAS : <span><span class=\"nc-pink nc-bold\">16 SA</span></span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-green_bg\">Médecin</span></strong></td>\n            <td>Indique la date de consultation, la <span>date de début de grossesse</span> ⭐, et certifie qu’il a prescrit les examens obligatoires.</td>\n          </tr>\n          <tr>\n            <td><strong>Gestante</strong></td>\n            <td>\n              Complète le formulaire et adresse :\n              <ul>\n                <li><span><span class=\"nc-green_bg\">2 exemplaires</span> à la <span class=\"nc-green nc-bold\">caisse d’allocations familiales</span></span></li>\n                <li><span>1 exemplaire à sa <span class=\"nc-green nc-bold\">caisse d’assurance maladie</span></span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Utilité</strong></td>\n            <td>Prise en charge des <strong>8 consultations prénatales</strong> à<span> 100 %</span> (examens obligatoires <span class=\"nc-pink nc-bold\">jusqu’au </span><span><span class=\"nc-pink nc-bold\">6</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\"> mois</span></span>) puis <span class=\"nc-green_bg\">couverture médicale à</span><span><span class=\"nc-green_bg\"> 100 %</span></span><span class=\"nc-green_bg\"> à partir de </span><span><span class=\"nc-green_bg\">24 SA</span></span>.</td>\n          </tr>\n        </tbody>\n      </table></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_2899354/fr/le-depistage-de-la-trisomie-21\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage de la trisomie 21</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li></ul></details>","frequence":0},{"id":"23-7","rang":"A","rubrique":"Prise en charge","titre":"Examens biologiques","contenu":"<div class=\"notion-course\"><p>⭐⭐⭐⭐⭐ Item le plus interrogé en QCM EDN du <span>suivi</span> de <span>grossesse</span>. Connaître <strong>par cœur</strong> la cinétique des examens obligatoires <span>vs</span> proposés systématiquement <span>vs</span> proposés sur <span>facteur de risque</span>.</p>\n\n      <h4>Calendrier de <span>suivi</span> — vue d'ensemble</h4>\n\n      <div class=\"gn-cal\">\n        <div class=\"gn-cal-legend\">\n          <span class=\"gn-lg oblig\">Obligatoire</span>\n          <span class=\"gn-lg syst\">Proposé systématiquement</span>\n          <span class=\"gn-lg fdr\">Sur <span>facteur de risque</span></span>\n          <span class=\"gn-lg key\">★ item-clé QCM</span>\n        </div>\n        <ol class=\"gn-cal-track\">\n          <li class=\"gn-stop is-key\">\n            <span class=\"gn-sa\">&lt; 15 SA</span>\n            <div class=\"gn-stop-title\">1ᵉʳ examen prénatal</div>\n            <div class=\"gn-cats\">\n              <div class=\"gn-cat oblig\"><b>Obligatoire</b><ul><li>Groupe ABO + Rh complet + Kell</li><li><span class=\"nc-blue nc-bold\">RAI</span> · Syphilis (TPHA)</li><li>Rubéole · <span class=\"nc-purple_bg\">Toxoplasmose</span> · Ag HBs</li><li>Albuminurie (<span>BU</span>)</li></ul></div>\n              <div class=\"gn-cat syst\"><b>Proposé syst.</b><ul><li><span>VIH</span></li><li><span>Dépistage</span> cancer du col</li><li><span>Dépistage</span> combiné T21 (écho + <span class=\"nc-pink nc-bold\">β-hCG</span> + <span class=\"nc-pink nc-bold\">PAPP-A</span>)</li></ul></div>\n              <div class=\"gn-cat fdr\"><b>Sur FdR</b><ul><li><span>VHC</span> · GAJ · <span>NFS</span> · <span>TSH</span> · EPS Hb</li><li><span>ECBU</span> · PV si <span class=\"nc-red nc-bold\">pertes</span></li><li>Génotype Rh fœtal dès 11 SA (si mère Rh−)</li></ul></div>\n            </div>\n          </li>\n          <li class=\"gn-stop\">\n            <span class=\"gn-sa\">16–20 SA</span>\n            <div class=\"gn-stop-title\">4ᵉ mois</div>\n            <div class=\"gn-cats\">\n              <div class=\"gn-cat oblig\"><b>Obligatoire</b><ul><li><span class=\"nc-purple_bg\">Rubéole</span> (si négatif, <span class=\"nc-pink nc-bold\">jusqu'à 18 SA</span>)</li><li><span class=\"nc-purple_bg\">Toxoplasmose</span> (si négatif)</li><li>Albuminurie (<span>BU</span>)</li></ul></div>\n              <div class=\"gn-cat syst\"><b>Proposé syst.</b><ul><li>Marqueurs <span class=\"nc-yellow_bg nc-bold\">T21</span> (14–17 SA) si non fait au T1</li><li>Bilan bucco-dentaire</li><li>Prescription écho du 5ᵉ mois</li></ul></div>\n              <div class=\"gn-cat fdr\"><b>Sur FdR</b><ul><li><span>ECBU</span> (si ATCD uro ou <span>BU</span>+)</li></ul></div>\n            </div>\n          </li>\n          <li class=\"gn-stop\">\n            <span class=\"gn-sa\">20–24 SA</span>\n            <div class=\"gn-stop-title\">5ᵉ mois</div>\n            <div class=\"gn-cats\">\n              <div class=\"gn-cat oblig\"><b>Obligatoire</b><ul><li>Rubéole · <span class=\"nc-purple_bg\">Toxoplasmose</span> (si négatif)</li><li>Albuminurie (<span>BU</span>)</li></ul></div>\n              <div class=\"gn-cat syst\"><b>Proposé syst.</b><ul><li><span>Échographie</span> morphologique de 22 SA</li></ul></div>\n              <div class=\"gn-cat fdr\"><b>Sur FdR</b><ul><li><span>ECBU</span> (si ATCD uro ou <span>BU</span>+)</li></ul></div>\n            </div>\n          </li>\n          <li class=\"gn-stop is-key\">\n            <span class=\"gn-sa\">24–28 SA</span>\n            <div class=\"gn-stop-title\">6ᵉ mois</div>\n            <div class=\"gn-cats\">\n              <div class=\"gn-cat oblig\"><b>Obligatoire</b><ul><li><strong><span><span class=\"nc-blue_bg\">NFS</span></span> ★</strong> (<span>dépistage</span> <span class=\"nc-red nc-bold\">anémie</span>)</li><li>Toxoplasmose · Albuminurie (<span>BU</span>)</li><li>RAI si Rh− ou Rh+ à ATCD transfu/obstétr.</li></ul></div>\n              <div class=\"gn-cat none\"><b>Proposé syst.</b><ul><li>—</li></ul></div>\n              <div class=\"gn-cat fdr\"><b>Sur FdR</b><ul><li><strong>HGPO <span>75 g</span> ★</strong> si FdR (GAJ T1 <span class=\"nc-pink nc-bold\">&lt;</span><span><span class=\"nc-pink nc-bold\"> 0,92 g/L</span></span> ou non faite)</li><li><span>ECBU</span></li></ul></div>\n            </div>\n          </li>\n          <li class=\"gn-stop\">\n            <span class=\"gn-sa\">28–32 SA</span>\n            <div class=\"gn-stop-title\">7ᵉ mois</div>\n            <div class=\"gn-cats\">\n              <div class=\"gn-cat oblig\"><b>Obligatoire</b><ul><li>Toxoplasmose · Albuminurie (<span>BU</span>)</li></ul></div>\n              <div class=\"gn-cat syst\"><b>Proposé syst.</b><ul><li>RAI (si Rh− / Rh+ à ATCD)</li><li>Vitamine D 100 <span>000 UI</span> dose unique</li></ul></div>\n              <div class=\"gn-cat fdr\"><b>Sur FdR</b><ul><li><span>ECBU</span> (si ATCD uro ou <span>BU</span>+)</li></ul></div>\n            </div>\n          </li>\n          <li class=\"gn-stop is-key\">\n            <span class=\"gn-sa\">32–37 SA</span>\n            <div class=\"gn-stop-title\">8ᵉ mois</div>\n            <div class=\"gn-cats\">\n              <div class=\"gn-cat oblig\"><b>Obligatoire</b><ul><li>Toxoplasmose · Albuminurie (<span>BU</span>)</li><li><span class=\"nc-blue_bg\">RAI</span> (sauf si Rhophylac® déjà injecté)</li></ul></div>\n              <div class=\"gn-cat syst\"><b>Proposé syst.</b><ul><li><strong>PV ★</strong> — <span>dépistage</span> SGB (<span class=\"nc-pink nc-bold\">34–38 SA</span>)</li><li><span>Échographie</span> de croissance de 32 SA</li><li>Discuter du <span class=\"nc-green_bg\">congé maternité</span></li></ul></div>\n              <div class=\"gn-cat fdr\"><b>Sur FdR</b><ul><li><span>ECBU</span> (si ATCD uro ou <span>BU</span>+)</li></ul></div>\n            </div>\n          </li>\n          <li class=\"gn-stop\">\n            <span class=\"gn-sa\">37–42 SA</span>\n            <div class=\"gn-stop-title\">9ᵉ mois</div>\n            <div class=\"gn-cats\">\n              <div class=\"gn-cat oblig\"><b>Obligatoire</b><ul><li>Toxoplasmose · Albuminurie (<span>BU</span>)</li><li><span class=\"nc-blue_bg\">RAI</span> (sauf si Rhophylac®)</li></ul></div>\n              <div class=\"gn-cat syst\"><b>Proposé syst.</b><ul><li><span>BU</span> · <span class=\"nc-pink_bg\">Bilan pré-anesthésie</span></li></ul></div>\n              <div class=\"gn-cat fdr\"><b>Sur FdR</b><ul><li><span>ECBU</span> (si ATCD uro ou <span>BU</span>+)</li></ul></div>\n            </div>\n          </li>\n        </ol>\n      </div>\n\n      <h4>Synthèse de la <span>surveillance</span> <span>biologique</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Examen</th><th>Obligatoire</th><th>Proposé systématiquement</th><th>Proposé sur FR</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1<sup>er</sup> examen<br>(<span>&lt; 15 SA</span>)</strong></td>\n            <td>\n              <ul>\n                <li><span>Groupe ABO + phénotype Rh complet + Kell</span></li>\n                <li><span>RAI</span></li>\n                <li><span>Syphilis (TPHA en 1<sup>er</sup>)</span>, <span>Rubéole</span>, <span>Ag HBs</span>, <span><span class=\"nc-purple_bg\">Toxoplasmose</span></span></li>\n                <li><span><span class=\"nc-green_bg\">Albumine urinaire (BU)</span></span></li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span>VIH</span></li>\n                <li><span>Dépistage</span> <strong>cancer du col</strong></li>\n                <li><span>Dépistage</span> combiné T21 (écho + <span><span class=\"nc-pink nc-bold\">β-hCG</span></span> + <span><span class=\"nc-pink nc-bold\">PAPP-A</span></span>)</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span>VHC</span>, <span>GAJ</span>, <span>NFS</span>, <span>TSH</span>, Électrophorèse Hb</li>\n                <li><span>ECBU</span>, <span>PV</span> si <span class=\"nc-red nc-bold\">pertes</span></li>\n                <li><strong>Génotype Rh fœtal</strong> dès <span><span class=\"nc-pink nc-bold\">11 SA</span></span> (si mère Rh−) → si <span>fœtus Rh−, pas d’Ig anti-D à 28 SA</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>4<sup>e</sup> mois<br>(<span>16-<span class=\"nc-pink\">20 SA</span></span>)</strong></td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-purple_bg\">Rubéole</span></span> (si négatif, <strong><span class=\"nc-pink nc-bold\">jusqu’à 18 SA</span></strong>)</li>\n                <li><span><span class=\"nc-purple_bg\">Toxoplasmose</span></span> (si négatif)</li>\n                <li><span><span class=\"nc-green_bg\">Albumine urinaire (BU)</span></span></li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span class=\"nc-yellow_bg\">Marqueurs sériques</span> <strong><span class=\"nc-yellow_bg nc-bold\">T21</span></strong> (<span>14-17 SA</span>) si non fait au T1 (<span>α-FP</span>, <span><span class=\"nc-pink nc-bold\">β-hCG</span></span> ou <span class=\"nc-pink nc-bold\">hCG totales</span>, ± <span>Œstradiol non conjugué</span>)</li>\n                <li>Bilan bucco-dentaire (remboursé CPAM)</li>\n                <li>Prescription de l’écho du 5<sup>e</sup> mois</li>\n              </ul>\n            </td>\n            <td><span><span class=\"nc-blue_bg\">ECBU</span></span> (si ATCD uro ou <span>BU</span>+)</td>\n          </tr>\n          <tr>\n            <td><strong>5<sup>e</sup> mois<br>(20-24 SA)</strong></td>\n            <td>\n              <ul>\n                <li>Rubéole (si négatif)</li>\n                <li><span class=\"nc-purple_bg\">Toxoplasmose</span> (si négatif)</li>\n                <li><span><span class=\"nc-green_bg\">Albumine</span></span><span class=\"nc-green_bg\"> urinaire (</span><span><span class=\"nc-green_bg\">BU</span></span><span class=\"nc-green_bg\">)</span></li>\n              </ul>\n            </td>\n            <td><span>Échographie</span> morphologique de 22 SA</td>\n            <td><span><span class=\"nc-blue_bg\">ECBU</span></span> (si ATCD uro ou <span>BU</span>+)</td>\n          </tr>\n          <tr>\n            <td><strong>6<sup>e</sup> mois<br>(<span>24-28 SA</span>)</strong></td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-blue_bg\">NFS</span></span> ⭐ (<span>dépistage</span> <span class=\"nc-red nc-bold\">anémie</span>)</li>\n                <li><span><span class=\"nc-purple_bg\">Toxoplasmose</span></span> (si négatif)</li>\n                <li><span><span class=\"nc-green_bg\">Albumine urinaire (BU)</span></span></li>\n                <li><span>RAI</span> obligatoire dans 2 situations :\n                  <ul>\n                    <li><strong><span><span class=\"nc-red nc-bold\">RhD</span></span><span class=\"nc-red nc-bold\">−</span></strong> (sauf si génotypage Rh fait et fœtus négatif)</li>\n                    <li><strong><span><span class=\"nc-red nc-bold\">RhD</span></span><span class=\"nc-red nc-bold\">+ avec ATCD transfusionnels et/ou obstétricaux</span></strong></li>\n                  </ul>\n                </li>\n              </ul>\n            </td>\n            <td>—</td>\n            <td>\n              <ul>\n                <li><span>ECBU</span> si ATCD uro ou <span>BU</span>+</li>\n                <li><span><span class=\"nc-blue_bg\">HGPO 75 g</span></span> ⭐ si FdR et <span>GAJ <span class=\"nc-pink nc-bold\">&lt; 0,92 g/L</span></span> (<span>5,1 mmol/L</span>) au T1 (ou GAJ non réalisée)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>7<sup>e</sup> mois<br>(<span>28-32 SA</span>)</strong></td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-purple_bg\">Toxoplasmose</span></span> (si négatif)</li>\n                <li><span><span class=\"nc-green_bg\">Albumine urinaire (BU)</span></span></li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span>RAI</span> si Rh− ou Rh+ avec ATCD transfu / obstétricaux</li>\n                <li><span class=\"nc-pink_bg\">Supplémentation </span><span><span class=\"nc-pink_bg\">Vitamine D</span> 100 000 UI</span> dose unique (ou 8<sup>e</sup> mois)</li>\n              </ul>\n            </td>\n            <td><span><span class=\"nc-blue_bg\">ECBU</span></span> (si ATCD uro ou <span>BU</span>+)</td>\n          </tr>\n          <tr>\n            <td><strong>8<sup>e</sup> mois<br>(<span>32-37 SA</span>)</strong></td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-purple_bg\">Toxoplasmose</span></span> (si négatif)</li>\n                <li><span><span class=\"nc-blue_bg\">RAI</span></span> (sauf si injection de <span>Rhophylac®</span>)</li>\n                <li><span><span class=\"nc-green_bg\">Albumine urinaire (BU)</span></span></li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span>BU</span></li>\n                <li><span>PV</span> ⭐ (<span>dépistage</span> SGB à <span><span class=\"nc-pink nc-bold\">34-38 SA</span></span>) → si <strong>SGB+</strong> : <span>antibioprophylaxie amoxicilline IV</span> dès le début du travail</li>\n                <li><span>Échographie</span> de croissance de 32 SA</li>\n                <li>Discuter du <span class=\"nc-green_bg\">congé maternité</span></li>\n              </ul>\n            </td>\n            <td><span><span class=\"nc-blue_bg\">ECBU</span></span> (si ATCD uro ou <span>BU</span>+)</td>\n          </tr>\n          <tr>\n            <td><strong>9<sup>e</sup> mois<br>(<span>37-42 SA</span>)</strong></td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-purple_bg\">Toxoplasmose</span></span> (si négatif)</li>\n                <li><span><span class=\"nc-blue_bg\">RAI</span></span> (sauf si <span>Rhophylac®</span>)</li>\n                <li><span><span class=\"nc-green_bg\">Albumine urinaire (BU)</span></span></li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span>BU</span></li>\n                <li><span class=\"nc-pink_bg\">Bilan pré-anesthésie</span></li>\n              </ul>\n            </td>\n            <td><span><span class=\"nc-blue_bg\">ECBU</span></span> (si ATCD uro ou <span>BU</span>+)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>❌ Examens NON recommandés en systématique</h4>\n\n      <ul>\n        <li><span>Sérologie</span> <span>CMV</span></li>\n        <li><span>Bilan lipidique</span></li>\n        <li><span>VS</span></li>\n        <li><span>Phosphatases alcalines</span></li>\n        <li>Protéine S</li>\n      </ul>\n\n      <h4>Focus — détails des examens obligatoires du 1<sup>er</sup> trimestre</h4>\n\n      <table>\n        <thead><tr><th>Examen</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span>Groupe sanguin</span></td>\n            <td>Obligatoire en cas de 1<sup>ère</sup> <span>grossesse</span> : <span>ABO + phénotype Rh complet + Kell</span>, si pas de carte complète (2 déterminations).</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-blue_bg\">RAI</span></span></td>\n            <td>Hors AC dirigés contre A et B. Si positive → <strong>identification et titrage des AC obligatoires</strong>.</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-purple_bg\">Syphilis</span></span></td>\n            <td><span>TPHA</span> (ELISA/EIA/CMIA) → si positif, confirmé par <span>VDRL</span> quantitatif.</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-purple_bg\">Rubéole</span></span></td>\n            <td>Répétée <span><span class=\"nc-pink nc-bold\">jusqu’à 18 SA</span></span> si négative.</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-purple_bg\">Toxoplasmose</span></span></td>\n            <td>Répétée <strong>1×/mois</strong> dès le 2<sup>e</sup> examen prénatal si immunité non <span>acquise</span>.</td>\n          </tr>\n          <tr>\n            <td><span>Ag HBs</span></td>\n            <td>Obligatoire dès le 1<sup>er</sup> trimestre.</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-green_bg\">Albumine urinaire (BU)</span></span></td>\n            <td><strong>1×/mois</strong> pendant toute la <span>grossesse</span>. (<span class=\"nc-green_bg\">Glycosurie</span> encore obligatoire mais sans intérêt.)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span>NFS</span> du 6<sup>e</sup> mois — limites + recommandations HAS</h4>\n\n      <ul>\n        <li><span>NFS</span> donne seulement <span>Hb</span> et <span>Ht</span> ; <strong>ne précise pas les réserves</strong> (pas de <span>ferritine</span>).</li>\n        <li><span>Dépistage</span> tardif : risque périnatal existe déjà pour des carences plus précoces.</li>\n        <li>👉 <strong>HAS recommande</strong> : doser <span>ferritine + Hb à la déclaration</span> et conseils alimentaires à l’entretien T1.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 28 — <span>Infection urinaire</span> lors de la <span>grossesse</span> · 162 — IST · 169 — <span>VIH</span> · 255 — <span>Diabète gestationnel</span></em></p><div class=\"callout callout-info\"><b>Actualisation et précisions</b><ul><li><b>Actualisation HAS 2025–2026 :</b> le dépistage du CMV au premier trimestre est désormais recommandé ; il ne faut plus apprendre « aucun dépistage systématique ». Proposition après information, sérologie précoce puis, si négative, contrôle toutes les quatre semaines jusqu’à une dernière sérologie entre 13+0 et 14+0 SA. Voir l’objectif 27-12.</li></ul></div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_2899354/fr/le-depistage-de-la-trisomie-21\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage de la trisomie 21</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li></ul></details>","frequence":5},{"id":"23-8","rang":"A","rubrique":"Prise en charge","titre":"Dépistage de la T21","contenu":"<div class=\"notion-course\"><p>Le <span>dépistage</span> de la trisomie 21 est <strong>proposé systématiquement</strong> à toutes les femmes enceintes (non obligatoire). Le but est d’estimer un risque combiné — clinique + échographique + <span>biologique</span>.</p>\n\n      <h4><span>Dépistage</span> combiné du 1<sup>er</sup> trimestre (de référence)</h4>\n\n      <table>\n        <thead><tr><th>Composant</th><th>Caractéristique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span><span class=\"nc-blue nc-bold\">Échographie</span></span> de datation</strong></td>\n            <td>\n              <ul>\n                <li>Réalisée entre <span>11 SA et 13 SA + 6 j</span></li>\n                <li>Mesure de la <strong><span class=\"nc-red_bg\">clarté nucale</span></strong> prise en compte dans l’estimation du risque T21</li>\n                <li><span>Normale &lt; 3 mm</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-yellow_bg\">Marqueurs sériques</span> T1</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"nc-pink nc-bold\">PAPP-A</span></strong></li>\n                <li><strong>β-hCG libre</strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span>Dépistage</span> du 2<sup>e</sup> trimestre (en rattrapage)</h4>\n\n      <p>Si le <span>dépistage</span> combiné T1 n’a pas été réalisé, on propose les <strong><span class=\"nc-yellow_bg\">marqueurs sériques</span> entre 14 et 17 SA</strong> :</p>\n\n      <ul>\n        <li><strong><span class=\"nc-pink nc-bold\">α-fœtoprotéine</span></strong></li>\n        <li><strong>β-hCG</strong> ou hCG totales</li>\n        <li>± <strong>Œstradiol non conjugué</strong></li>\n      </ul>\n\n      <h4>Seuil de risque et conduite</h4>\n\n      <table>\n        <thead><tr><th>Résultat du <span>dépistage</span> combiné</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Risque faible</strong> : seuil <span>&lt; 1/1 000</span></td>\n            <td><span>Surveillance</span> simple, pas de geste complémentaire.</td>\n          </tr>\n          <tr>\n            <td><strong>Risque intermédiaire</strong> : <span>1/51</span> à <span>1/1 000</span></td>\n            <td>Proposition d’un <strong>DPNI</strong> (<span>dépistage</span> prénatal non invasif sur ADN fœtal libre — remboursé depuis 2018).</td>\n          </tr>\n          <tr>\n            <td><span>Risque élevé</span> : seuil <span>≥ 1/50</span> (ou seuil concours <span>≥ 1/250</span>)</td>\n            <td>Proposition d’un <strong>caryotype fœtal</strong> par geste invasif (<span>biopsie</span> de trophoblaste ou amniocentèse) — décision partagée (cf obj-8).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewbox=\"0 0 560 236\" role=\"img\" aria-label=\"Arbre décisionnel du dépistage de la trisomie 21 : le dépistage combiné du 1er trimestre (clarté nucale, PAPP-A et béta-hCG libre) estime un risque. Si le risque est faible, inférieur à 1 sur 1000, surveillance simple. Si le risque est intermédiaire, entre 1 sur 1000 et 1 sur 51, on propose un DPNI sur ADN fœtal libre. Si le risque est élevé, supérieur ou égal à 1 sur 50, on propose un caryotype fœtal par geste invasif (biopsie de trophoblaste ou amniocentèse) avec orientation vers le CPDPN.\" style=\"height:auto;display:block;border-radius:8px\">\n          <rect class=\"fb-blue\" x=\"90\" y=\"10\" width=\"380\" height=\"50\" rx=\"6\"></rect>\n          <text class=\"tx-blue\" x=\"280\" y=\"31\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"600\"><span>Dépistage</span> combiné — 1ᵉʳ trimestre</text>\n          <text class=\"tx-blue\" x=\"280\" y=\"48\" text-anchor=\"middle\" font-size=\"11\">clarté nucale + PAPP-A + β-hCG libre (11–13 SA+6)</text>\n          <line class=\"ln\" x1=\"280\" y1=\"60\" x2=\"280\" y2=\"76\" stroke-width=\"2\"></line>\n          <line class=\"ln\" x1=\"95\" y1=\"76\" x2=\"465\" y2=\"76\" stroke-width=\"2\"></line>\n          <line class=\"ln\" x1=\"95\" y1=\"76\" x2=\"95\" y2=\"90\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"95,96 90,88 100,88\"></polygon>\n          <line class=\"ln\" x1=\"280\" y1=\"76\" x2=\"280\" y2=\"90\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"280,96 275,88 285,88\"></polygon>\n          <line class=\"ln\" x1=\"465\" y1=\"76\" x2=\"465\" y2=\"90\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"465,96 460,88 470,88\"></polygon>\n          <rect class=\"fb-ok\" x=\"15\" y=\"98\" width=\"160\" height=\"40\" rx=\"6\"></rect>\n          <text class=\"tx-ok\" x=\"95\" y=\"115\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"600\">Risque faible</text>\n          <text class=\"tx-ok\" x=\"95\" y=\"130\" text-anchor=\"middle\" font-size=\"11\">&lt; 1/1 000</text>\n          <rect class=\"fb-amber\" x=\"200\" y=\"98\" width=\"160\" height=\"40\" rx=\"6\"></rect>\n          <text class=\"tx-amber\" x=\"280\" y=\"115\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"600\">Risque intermédiaire</text>\n          <text class=\"tx-amber\" x=\"280\" y=\"130\" text-anchor=\"middle\" font-size=\"11\">1/51 – 1/1 000</text>\n          <rect class=\"fb-red\" x=\"385\" y=\"98\" width=\"160\" height=\"40\" rx=\"6\"></rect>\n          <text class=\"tx-red\" x=\"465\" y=\"115\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"600\">Risque élevé</text>\n          <text class=\"tx-red\" x=\"465\" y=\"130\" text-anchor=\"middle\" font-size=\"11\"><span>≥ 1</span>/50</text>\n          <line class=\"ln\" x1=\"95\" y1=\"138\" x2=\"95\" y2=\"152\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"95,158 90,150 100,150\"></polygon>\n          <line class=\"ln\" x1=\"280\" y1=\"138\" x2=\"280\" y2=\"152\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"280,158 275,150 285,150\"></polygon>\n          <line class=\"ln\" x1=\"465\" y1=\"138\" x2=\"465\" y2=\"152\" stroke-width=\"2\"></line>\n          <polygon class=\"ah\" points=\"465,158 460,150 470,150\"></polygon>\n          <rect class=\"fb-ok\" x=\"15\" y=\"160\" width=\"160\" height=\"66\" rx=\"6\"></rect>\n          <text class=\"tx-ok\" x=\"95\" y=\"197\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\"><span>Surveillance</span> simple</text>\n          <rect class=\"fb-amber\" x=\"200\" y=\"160\" width=\"160\" height=\"66\" rx=\"6\"></rect>\n          <text class=\"tx-amber\" x=\"280\" y=\"184\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\">DPNI</text>\n          <text class=\"tx-amber\" x=\"280\" y=\"200\" text-anchor=\"middle\" font-size=\"10.5\">ADN fœtal libre</text>\n          <text class=\"tx-amber\" x=\"280\" y=\"214\" text-anchor=\"middle\" font-size=\"10.5\">(remboursé 2018)</text>\n          <rect class=\"fb-red\" x=\"385\" y=\"160\" width=\"160\" height=\"66\" rx=\"6\"></rect>\n          <text class=\"tx-red\" x=\"465\" y=\"181\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\">Caryotype fœtal</text>\n          <text class=\"tx-red\" x=\"465\" y=\"196\" text-anchor=\"middle\" font-size=\"10.5\"><span>biopsie</span> troph. / amnio</text>\n          <text class=\"tx-red\" x=\"465\" y=\"210\" text-anchor=\"middle\" font-size=\"10.5\">→ orientation CPDPN</text>\n        </svg>\n        <figcaption>Le dépistage combiné T1 estime un <strong>risque</strong>, pas un diagnostic. Version statique ; un arbre interactif Quiz/Explorer pourra être généré via l'onglet Stratégie &amp; CAT.</figcaption>\n      </figure>\n\n      <h4>Information à délivrer à la patiente</h4>\n\n      <ul>\n        <li>Le <span>dépistage</span> est <strong>non obligatoire</strong> et <strong>non remboursé à<span> 100 %</span></strong> si non couplé à l’<span><span class=\"nc-blue nc-bold\">échographie</span></span> obligatoire.</li>\n        <li>Il calcule un <em>risque</em>, pas un diagnostic — un résultat positif ne signifie pas que l’enfant est porteur de T21.</li>\n        <li>En cas de risque élevé → consultation spécialisée pour discuter d’un <strong>diagnostic prénatal</strong> (cf obj suivant).</li>\n      </ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_2899354/fr/le-depistage-de-la-trisomie-21\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage de la trisomie 21</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li></ul></details>","frequence":0},{"id":"23-9","rang":"B","rubrique":"Prise en charge","titre":"Conduite à tenir en cas de dépistage de T21 positif","contenu":"<div class=\"notion-course\"><ul><li>Un résultat de dépistage de trisomie 21 exprime une probabilité : ce n’est pas un diagnostic. Expliquer les options et respecter le choix de la femme, y compris le refus de dépistage ou de prélèvement.</li><li>Après dépistage combiné : risque inférieur à 1/1 000, suivi habituel ; entre 1/1 000 et 1/51, proposer l’analyse de l’ADN libre circulant (DPNI) ; risque ≥ 1/50, proposer un prélèvement diagnostique, avec possibilité de DPNI après information.</li><li>Une <span class=\"nc-red_bg\">clarté nucale</span> ≥ 3,5 mm ou une anomalie échographique justifie un avis spécialisé/CPDPN et la discussion d’un prélèvement diagnostique, indépendamment du risque sérique.</li><li>Un DPNI positif doit être confirmé par un prélèvement invasif et une analyse cytogénétique avant toute décision irréversible. Un DPNI non interprétable ne doit pas être assimilé à un résultat négatif.</li><li>Biopsie de trophoblaste ou amniocentèse selon le terme et la question : information sur les limites, le risque du geste et consentement. Une éventuelle IMG relève d’un parcours spécifique ; elle n’est jamais automatique.</li></ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_2899354/fr/le-depistage-de-la-trisomie-21\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage de la trisomie 21</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li></ul></details>","frequence":0},{"id":"23-10","rang":"A","rubrique":"Prise en charge","titre":"Savoir surveiller cliniquement une femme enceinte sans complication","contenu":"<div class=\"notion-course\"><p>La <span>grossesse</span> normale est suivie par <strong>8 consultations prénatales</strong> prises en charge à<span> 100 %</span> : 2 consultations recommandées lors des 3 premiers mois (&lt; 15 SA), puis <strong>1×/mois jusqu’à la naissance</strong>.</p>\n\n      <h4>Acteurs du <span>suivi</span> (selon le terme)</h4>\n\n      <ul>\n        <li><strong><span class=\"nc-pink nc-bold\">Jusqu’au 6</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\"> mois</span></strong> : <span class=\"nc-green_bg\">médecin généraliste</span>, <span class=\"nc-green_bg\">sage-femme</span>, <span class=\"nc-green_bg\">obstétricien</span></li>\n        <li><strong><span class=\"nc-pink nc-bold\">Aux 7</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\">, 8</span><sup><span class=\"nc-pink nc-bold\">e</span></sup>, <span class=\"nc-pink nc-bold\">9</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\"> mois</span></strong> : équipe qui assurera la naissance (<span class=\"nc-blue_bg\">sage-femme ou obstétricien</span>) de préférence</li>\n      </ul>\n\n      <h4>Trame de chaque consultation au 2<sup>nd</sup> trimestre</h4>\n\n      <table>\n        <thead><tr><th>Étape</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Interrogatoire</strong></td>\n            <td>Recherche : hémorragies, signes fonctionnels urinaires, leucorrhées prurigineuses ou malodorantes, <span class=\"nc-green_bg\">contractions utérines</span> (physiologiques = <em>Braxton-Hicks</em>).</td>\n          </tr>\n          <tr>\n            <td><strong>Examen clinique obstétrical</strong></td>\n            <td>\n              <ul>\n                <li>PA, poids</li>\n                <li><strong>HU</strong> à partir du <strong>4<sup>e</sup> mois</strong></li>\n                <li>BDC (Bruits du cœur fœtal)</li>\n                <li>Demander à la femme si elle ressent les <strong>MAF</strong> (perçus <span class=\"nc-pink nc-bold\">autour de la </span><strong><span class=\"nc-pink nc-bold\">fin du 4</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\"> mois</span></strong>, plus tôt chez la multipare)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Toucher vaginal</strong></td>\n            <td><strong>Non systématique</strong> ❌ — uniquement si signes cliniques (contractions). Intérêt très limité pour dépister un <span class=\"nc-red nc-bold\">accouchement prématuré</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Hauteur utérine — repères normaux</h4>\n\n      <table>\n        <thead><tr><th>Période</th><th>Formule</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>HU normale entre 20-32 SA</strong></td>\n            <td>HU (cm) = <strong><span class=\"nc-pink nc-bold\">nombre de SA − 4</span></strong> (ex.<span> 24 cm</span> à 28 SA,<span> 28 cm</span> à 32 SA).</td>\n          </tr>\n          <tr>\n            <td><strong>HU normale après 32 SA</strong></td>\n            <td>HU <strong>augmente de <span>1 cm</span> toutes les 2 SA</strong> (<span>29 cm</span> à 34 SA,<span> 30 cm</span> à 36 SA…).</td>\n          </tr>\n          <tr>\n            <td><strong>Méthode alternative</strong></td>\n            <td>\n              <ul>\n                <li>Entre <span><span class=\"nc-pink nc-bold\">4-7 mois</span></span> : HU = nombre de mois × 4</li>\n                <li><span class=\"nc-pink nc-bold\">8-9</span><sup><span class=\"nc-pink nc-bold\">e</span></sup> mois : HU = nombre de mois × 4 − 2</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>CAT si anormale</strong></td>\n            <td>HU inférieure → <strong><span class=\"nc-blue nc-bold\">contrôle échographique</span></strong>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Recommandations hygiéno-diététiques (rappel à chaque consultation)</h4>\n\n      <table>\n        <thead><tr><th>Domaine</th><th>Conseil</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Activité physique</strong></td><td>Possible sauf <em><span class=\"nc-red nc-bold\">sports violents ou très fatigants</span></em>.</td></tr>\n          <tr><td><strong>Activité professionnelle</strong></td><td>Plupart des activités <strong>ne sont pas un FdR d’<span class=\"nc-red nc-bold\">accouchement prématuré</span></strong>.</td></tr>\n          <tr><td><strong>Voyages</strong></td><td>Autorisés si <span>grossesse</span> normale. <strong>Ceinture de sécurité obligatoire</strong> quel que soit le terme.</td></tr>\n          <tr><td><strong>Toxiques</strong></td><td>Arrêt <span><span class=\"nc-orange_bg\">alcool</span> (<span class=\"nc-red nc-bold\">tolérance zéro</span>)</span>, <span><span class=\"nc-orange_bg\">tabac</span></span>, <span>cannabis</span> (1 joint = 7 cigarettes), <span><span class=\"nc-pink_bg\">opiacés</span></span>.</td></tr>\n          <tr><td><strong>Vaccinations</strong></td><td>Anti-grippale à tout <span>stade</span> · <strong>Anti-COVID-19 dès le 2<sup>nd</sup> trim</strong>.</td></tr>\n          <tr><td><strong>Prévention infectieuse</strong></td><td>Règles toxoplasmose (si séronégative) + listériose · prévention <span>CMV</span> (éviter sécrétions d’enfants en bas-âge).</td></tr>\n          <tr><td><strong>Supplémentations</strong></td><td>Voir bloc dédié ci-dessous ⬇</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Supplémentations systématiques — posologies à connaître ⭐</h4>\n\n      <table>\n        <thead><tr><th>Molécule</th><th>Posologie</th><th>Timing</th><th>Pourquoi ?</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"nc-pink_bg\">Acide folique</span> (B9)</strong></td>\n            <td><span>0,4 mg/j</span> per os</td>\n            <td>Dès <span><span class=\"nc-pink nc-bold\">≥ 1 mois</span></span> avant la conception, jusqu’à <span>10-12 SA</span></td>\n            <td>Prévention des <strong>anomalies de fermeture du tube neural (AFTN)</strong> ⭐⭐⭐⭐⭐</td>\n          </tr>\n          <tr>\n            <td><strong>Vitamine D</strong></td>\n            <td><span>100 000 UI</span> dose unique per os</td>\n            <td><span class=\"nc-pink nc-bold\">Début du </span><span><span class=\"nc-pink nc-bold\">7</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\"> ou 8</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\"> mois</span></span>, en toute saison</td>\n            <td><span class=\"nc-green_bg\">Prévention des </span><strong><span class=\"nc-green_bg\">hypocalcémies néonatales</span></strong> (état de carence en fin de <span>grossesse</span> en France)</td>\n          </tr>\n          <tr>\n            <td><strong>Fer</strong></td>\n            <td>Si carence martiale (<span>ferritine &lt; 12 μg/L</span>) ou anémie</td>\n            <td>Selon bilan</td>\n            <td>Pas systématique — guidé par <span>NFS</span> du 6<sup>e</sup> mois (cf obj-6, obj-14)</td>\n          </tr>\n          <tr>\n            <td><strong>B9 + B12</strong></td>\n            <td>À doser si ATCD <span>chirurgie</span> bariatrique, végétariennes/végétaliennes</td>\n            <td>Dès la déclaration</td>\n            <td>Carences à dépister activement</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"nc-yellow_bg\">Effet Poseiro</span> — décubitus latéral gauche au T3 📌</h4>\n\n      <p><span class=\"nc-yellow_bg\">En décubitus dorsal</span> au 3<sup>e</sup> trimestre, l’utérus gravide comprime la <strong>veine cave inférieure</strong> :</p>\n\n      <ul>\n        <li>↓ retour veineux au cœur droit</li>\n        <li><span>Ralentissement du rythme cardiaque fœtal</span></li>\n        <li><span><span class=\"nc-red nc-bold\">Malaise maternel</span></span> (hypoTA)</li>\n      </ul>\n\n      <p>👉 <strong>Préférer le décubitus latéral gauche</strong> à partir du T3 (auscultation BDC, repos, accouchement).</p>\n\n      <h4><span>Dépistage</span> du <span>diabète gestationnel</span> — <span class=\"nc-blue_bg\">HGPO </span><span><span class=\"nc-blue_bg\">75 g</span></span></h4>\n\n      <ul>\n        <li><strong>Indication</strong> : <span>GAJ <span class=\"nc-pink nc-bold\">&lt; 0,92 g/L</span> (5,1 mmol/L)</span> au T1 chez femme avec <strong>FdR</strong> (ou GAJ non réalisée)</li>\n        <li><strong>Quand ?</strong> Au <span>6<sup>e</sup> mois (24-28 SA)</span></li>\n        <li><strong>Détails</strong> : voir <em>obj-6 — Examens biologiques</em> et item lié 255</li>\n      </ul>\n\n      <h4>Consultation du 9<sup>e</sup> mois (37-42 SA) — particularités</h4>\n\n      <ul>\n        <li>Examen clinique : HU, BDC, poids, PA, <strong>toucher vaginal avec pelvimétrie clinique</strong></li>\n        <li>Explication du moment où venir à la maternité, convocation le jour du terme présumé</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 27 — Prévention risques fœtaux · 28 — <span>Infection urinaire</span> lors de la <span>grossesse</span> · 255 — <span>Diabète gestationnel</span></em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_2899354/fr/le-depistage-de-la-trisomie-21\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage de la trisomie 21</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li></ul></details>","frequence":0},{"id":"23-11","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les professionnels de santé impliqués dans le suivi de la femme enceinte","contenu":"<div class=\"notion-course\"><p>La plupart des grossesses étant physiologiques ou normales, leur prise en charge peut être <span>assurée indifféremment par plusieurs professionnels</span>.</p>\n\n      <h4>Acteurs selon le terme</h4>\n\n      <table>\n        <thead><tr><th>Période</th><th>Professionnels</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"nc-pink nc-bold\">Jusqu’au </span><span><span class=\"nc-pink nc-bold\">6</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\"> mois</span></span></strong></td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-green_bg\">Médecin généraliste</span></span></li>\n                <li><span><span class=\"nc-green_bg\">Sage-femme</span></span></li>\n                <li><span><span class=\"nc-green_bg\">Obstétricien</span></span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-pink nc-bold\">Aux </span><span><span class=\"nc-pink nc-bold\">7</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\">, 8</span><sup><span class=\"nc-pink nc-bold\">e</span></sup>, <span class=\"nc-pink nc-bold\">9</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\"> mois</span></span></strong></td>\n            <td>Équipe qui assurera la naissance de préférence (<span><span class=\"nc-blue_bg\">sage-femme ou obstétricien</span></span>).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Acteurs selon le niveau de risque</h4>\n\n      <table>\n        <thead><tr><th><span>Suivi</span></th><th>Professionnel</th></tr></thead>\n        <tbody>\n          <tr><td><strong>A</strong></td><td><span><span class=\"nc-green_bg\">Sage-femme</span></span> ou <span class=\"nc-green_bg\">médecin</span> (généraliste, gynéco médical, gynéco-<span class=\"nc-green_bg\">obstétricien</span>) au choix de la femme.</td></tr>\n          <tr><td><strong>A1</strong></td><td>Avis d’un <span>gynéco-obstétricien</span> et/ou autre spécialiste <em><span class=\"nc-orange_bg\">conseillé</span></em>.</td></tr>\n          <tr><td><strong>A2</strong></td><td>Avis d’un <span>gynéco-obstétricien <span class=\"nc-yellow_bg nc-bold\">nécessaire</span></span> (± autre spécialiste).</td></tr>\n          <tr><td><strong>B</strong></td><td><span>Suivi</span> régulier par un <span>gynécologue obstétricien</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Acteurs spécifiques selon le moment du parcours</h4>\n\n      <ul>\n        <li><strong><span>EPP</span> du <span>4<sup>e</sup> mois</span></strong> : <span><span class=\"nc-green_bg\">sage-femme</span> +++</span>, ou autre professionnel de la périnatalité, plus rarement <span class=\"nc-green_bg\">médecin</span> formé. Durée <span>45 min</span>.</li>\n        <li><strong>Bilan <span class=\"nc-yellow_bg\">prénatal</span> de prévention</strong> (alimentation, <span>tabac</span>, <span><span class=\"nc-orange_bg\">alcool</span></span>) avant <span>24 SA</span> : <span><span class=\"nc-green_bg\">sage-femme</span> libérale ou de PMI</span>.</li>\n        <li><strong>Bilan bucco-dentaire</strong> au <span>4<sup>e</sup> mois</span> : remboursé à<span> 100 %</span> par la CPAM.</li>\n        <li><strong>Échographies</strong> : opérateurs en imagerie obstétricale (gynéco-obstétriciens, échographistes, <span><span class=\"nc-green_bg\">sages-femmes</span> échographistes</span>).</li>\n        <li><strong>Anesthésiste</strong> : consultation à conseiller au <span>8<sup>e</sup> mois</span>.</li>\n        <li><strong>Examen <span class=\"nc-yellow_bg\">postnatal</span></strong> (<span>6-8 semaines</span> post-accouchement) : <span class=\"nc-green_bg\">médecin</span> ou <span><span class=\"nc-green_bg\">sage-femme</span></span> si <span>grossesse</span> normale et accouchement eutocique.</li>\n      </ul>\n\n      <h4>Préparation à la naissance et à la parentalité</h4>\n\n      <ul>\n        <li><span><span class=\"nc-pink nc-bold\">8 séances</span></span> au total — la 1<sup>ère</sup> étant l’<span>EPP</span> du 4<sup>e</sup> mois.</li>\n        <li>Réalisées en individuel ou en couple.</li>\n        <li>Possibles avant ou après l’accouchement.</li>\n      </ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_2899354/fr/le-depistage-de-la-trisomie-21\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage de la trisomie 21</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li></ul></details>","frequence":0},{"id":"23-12","rang":"A","rubrique":"Prise en charge","titre":"Echographies obstétricales","contenu":"<div class=\"notion-course\"><p>Les <strong>3 échographies de la <span>grossesse</span></strong> ne sont pas obligatoires mais sont <strong>remboursées à<span> 100 %</span></strong>.</p>\n\n      <div class=\"gn-echo\" role=\"img\" aria-label=\"Frise des 3 échographies obstétricales sur l&#x27;axe de la grossesse : échographie de datation au 1er trimestre entre 11 et 13 SA + 6 jours, échographie morphologique au 2e trimestre à 22 SA, échographie de croissance au 3e trimestre à 32 SA.\">\n        <div class=\"gn-echo-step\">\n          <span class=\"gn-echo-sa\">11 → 13 SA+6 · T1</span>\n          <strong>1 · Datation</strong>\n          <ul>\n            <li>Localisation + vitalité</li>\n            <li>Terme par <span class=\"nc-blue_bg\">LCC</span> (précision 3–5 j)</li>\n            <li>Grossesses multiples + chorionicité ★</li>\n            <li><span class=\"nc-red_bg\">Clarté nucale</span> (&lt;<span> 3 mm</span>) → risque T21</li>\n          </ul>\n        </div>\n        <div class=\"gn-echo-step\">\n          <span class=\"gn-echo-sa\">22 SA · T2</span>\n          <strong>2 · Morphologique</strong>\n          <ul>\n            <li><span><span class=\"nc-red nc-bold\">Dépistage</span></span><span class=\"nc-red nc-bold\"> des malformations ++</span></li>\n            <li>Biométrie (BIP, PA, LF)</li>\n            <li><span class=\"nc-green nc-bold\">Liquide amniotique</span></li>\n            <li>Localisation <span class=\"nc-yellow_bg\">placenta</span> + cordon</li>\n          </ul>\n        </div>\n        <div class=\"gn-echo-step\">\n          <span class=\"gn-echo-sa\">32 SA · T3</span>\n          <strong>3 · Croissance</strong>\n          <ul>\n            <li>Vitalité (Manning, Doppler ombilical)</li>\n            <li>Biométrie → RCIU / macrosomie</li>\n            <li>Localisation placentaire + liquide</li>\n            <li>Type de présentation ★</li>\n          </ul>\n        </div>\n      </div>\n\n      <table>\n        <thead>\n          <tr><th><span>Échographie</span></th><th>Quand ?</th><th>Objectifs</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1 — <span><span class=\"nc-blue nc-bold\">Échographie</span></span> de datation<br>(1<sup>er</sup> trimestre)</strong></td>\n            <td><span>11 SA</span> à <span>13 SA + 6 j</span></td>\n            <td>\n              <ul>\n                <li>Confirme la <strong>localisation</strong> et la <strong><span class=\"nc-green_bg\">vitalité fœtale</span></strong></li>\n                <li><span class=\"nc-yellow_bg\">Détermine le terme</span> par <span class=\"nc-blue_bg\">LCC</span> + <span class=\"nc-blue_bg\">BIP</span> — <strong>précision <span>3–5 j</span></strong></li>\n                <li><span class=\"nc-yellow_bg\">Diagnostic des </span><strong><span class=\"nc-yellow_bg\">grossesses multiples</span></strong> et établit la <strong>chorionicité</strong> ⭐</li>\n                <li>Dépiste <span class=\"nc-red_bg\">certaines malformations</span> majeures (<span class=\"nc-red\">agénésie de</span> <span class=\"nc-red\">membre</span>, <span class=\"nc-red\">anencéphalie</span>…)</li>\n                <li>Mesure de la <strong><span class=\"nc-red_bg\">clarté nucale</span></strong> (normale <span>&lt; 3 mm</span>) pour estimation du risque T21</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>2 — <span><span class=\"nc-blue nc-bold\">Échographie</span></span> morphologique<br>(2<sup>e</sup> trimestre)</strong></td>\n            <td><span>22 SA</span></td>\n            <td>\n              <strong><span>Dépistage</span> des malformations ++</strong> :\n              <ul>\n                <li>Viabilité fœtale (MAF, activité cardiaque)</li>\n                <li>Biométrie : BIP, PA (périmètre abdo), LF (longueur fémorale)</li>\n                <li><span class=\"nc-yellow_bg\">Quantité de liquide amniotique</span></li>\n                <li>Localisation placentaire + cordon ombilical</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>3 — <span>Échographie</span> de croissance<br>(3<sup>e</sup> trimestre)</strong></td>\n            <td><span>32 SA</span></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-green_bg\">Vitalité fœtale</span> (<span>score</span> de <strong>Manning</strong>, amnios, <span>Doppler</span> ombilical)</li>\n                <li>Croissance : biométrie (BIP, PA, LF, PC = périmètre crânien) → recherche RCIU / macrosomie</li>\n                <li>Confirme la localisation placentaire</li>\n                <li>Évalue la <span class=\"nc-yellow_bg\">quantité de liquide amniotique</span></li>\n                <li><strong>Type de présentation</strong> ⭐</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Premiers signes échographiques (rappel T1)</h4>\n\n      <ul>\n        <li><strong>Sac gestationnel</strong> : visible <span class=\"nc-pink nc-bold\">dès </span><span><span class=\"nc-pink nc-bold\">5 SA</span></span> par voie vaginale (hCG &gt; 1 <span>500 UI/L</span>)</li>\n        <li><strong>Activité cardiaque</strong> : visible <span class=\"nc-pink nc-bold\">dès </span><span><span class=\"nc-pink nc-bold\">5 SA</span> + 3 j</span> (LCC <span>≈ 4 mm</span>)</li>\n      </ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_2899354/fr/le-depistage-de-la-trisomie-21\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage de la trisomie 21</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li></ul></details>","frequence":0},{"id":"23-13","rang":"A","rubrique":"Prise en charge","titre":"Connaître les motifs de consultation les plus fréquents concernant les petits maux des femmes dans le cadre d’une grossesse","contenu":"<div class=\"notion-course\"><p>Les <span>petits maux de la grossesse</span> sont des symptômes physiologiques fréquents, à reconnaître pour les distinguer d’une vraie complication et pouvoir rassurer la patiente.</p>\n\n      <h4>1<sup>er</sup> trimestre</h4>\n\n      <ul>\n        <li><strong><span>Nausées</span></strong>, <strong><span>vomissements</span></strong></li>\n        <li><strong>Ptyalisme</strong> (= <span class=\"nc-blue_bg\">hypersalivation</span>), <strong><span>constipation</span></strong></li>\n        <li><span><span class=\"nc-orange_bg\">Anorexie</span></span>, <span><span class=\"nc-orange_bg\">boulimie</span></span>, <strong><span class=\"nc-orange_bg\">hypersomnie</span></strong></li>\n        <li><strong>Tension mammaire</strong></li>\n        <li>Douleurs ligamentaires</li>\n      </ul>\n\n      <h4>2<sup>nd</sup> trimestre</h4>\n\n      <ul>\n        <li><strong><span class=\"nc-blue_bg\">Chloasma</span></strong> (<span class=\"nc-blue_bg\">masque de </span><span><span class=\"nc-blue_bg\">grossesse</span></span>), <span class=\"nc-blue_bg\">vergetures</span>, <span class=\"nc-blue_bg\">varices</span></li>\n        <li><span class=\"nc-orange_bg\">Hémorroïdes</span>, <span class=\"nc-orange_bg\">varices vulvaires</span>, <span><span class=\"nc-orange_bg\">constipation</span></span></li>\n        <li><span><span class=\"nc-blue_bg\">Œdèmes des membres inférieurs</span></span>, <span class=\"nc-blue_bg\">crampes</span></li>\n        <li>Douleurs pelviennes : <span><span class=\"nc-purple_bg\">cystite</span></span>, <span class=\"nc-purple_bg\">candidose</span></li>\n        <li><strong><span class=\"nc-red nc-bold\">Anémie</span></strong></li>\n        <li>Congestion nasale, saignements de nez, saignements gingivaux</li>\n      </ul>\n\n      <h4>3<sup>e</sup> trimestre</h4>\n\n      <ul>\n        <li><span>Œdèmes</span> et <span class=\"nc-blue_bg\">crampes des membres inférieurs</span></li>\n        <li><strong><span class=\"nc-orange_bg\">Lombalgies</span></strong>, <span class=\"nc-orange_bg\">sciatalgie</span>, <strong><span class=\"nc-orange_bg\">compression du nerf médian</span></strong></li>\n        <li><span class=\"nc-green_bg\">Contractions utérines</span> (Braxton-Hicks), <span class=\"nc-green_bg\">sécrétion lactée</span></li>\n        <li><strong><span class=\"nc-orange_bg\">Pyrosis</span> et RGO</strong>, <span class=\"nc-orange_bg\">insomnies</span> nocturnes, <span><span class=\"nc-blue_bg\">prurit</span></span></li>\n        <li><span><span class=\"nc-blue_bg\">Palpitations</span></span>, <span><span class=\"nc-blue_bg\">dyspnée</span></span></li>\n        <li>Impériosités mictionnelles (compression vésicale par l’utérus), <span class=\"nc-orange_bg\">hémorroïdes</span>, <span class=\"nc-blue_bg\">varices</span></li>\n      </ul>\n\n      <p>📌 Tout symptôme dépassant le cadre du « petit mal » (hémorragie, <span>fièvre</span>, contractions précoces, <span>céphalée</span> + <span>HTA</span> + <span>protéinurie</span>, ↓ MAF…) doit faire <strong>réorienter en <span>urgence</span> vers la maternité</strong> (cf obj-14).</p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_2899354/fr/le-depistage-de-la-trisomie-21\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage de la trisomie 21</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li></ul></details>","frequence":0},{"id":"23-14","rang":"A","rubrique":"Prise en charge","titre":"Connaître les mesures médicamenteuses et non médicamenteuses concernant les petits maux de la grossesse","contenu":"<div class=\"notion-course\"><p>Le focus principal de la fiche source concerne les <strong><span>vomissements</span> et <span>nausées</span></strong> — symptôme le plus fréquent du 1<sup>er</sup> trimestre.</p>\n\n      <h4><span>Vomissements</span> physiologiques (≈<span> 50 %</span> des grossesses)</h4>\n\n      <ul>\n        <li><strong>Quand ?</strong> <span class=\"nc-red nc-bold\">Au 1</span><sup><span class=\"nc-red nc-bold\">er</span></sup><span class=\"nc-red nc-bold\"> trimestre</span>, s’atténuent à la fin du T1</li>\n        <li><strong>Cause</strong> : effet de l’<strong>hCG</strong> et des <strong>œstrogènes</strong></li>\n        <li><strong>Manifestations</strong> : <span>vomissements</span> sans retentissement sur l’état général, dégoût pour certains aliments</li>\n      </ul>\n\n      <h4>Orientation et soutien</h4>\n\n      <table>\n        <thead><tr><th>Volet</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Hospitalisation</span></strong></td>\n            <td>Si <strong><span>perte de poids</span> importante</strong> ou <strong><span>intolérance</span> alimentaire totale</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Soutien psychologique</strong></td>\n            <td>\n              Soutien moral voire aide psychologique car altération de la qualité de vie. <strong>Pas une pathologie psychiatrique</strong> : il ne s’agit pas d’un rejet de la <span>grossesse</span>, c’est une pathologie hormonale.\n              <br>⚠️ À <strong>bannir</strong> : isolement du cercle familial, mise dans le noir, confiscation du téléphone portable.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Mesures non médicamenteuses — conseils hygiéno-diététiques</h4>\n\n      <table>\n        <thead><tr><th>À éviter</th><th>À préférer</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <ul>\n                <li><span class=\"nc-red_bg\">Aliments aux </span><strong><span class=\"nc-red_bg\">odeurs trop fortes</span></strong></li>\n                <li><span class=\"nc-red_bg\">Casser le </span><strong><span class=\"nc-red_bg\">cercle vicieux du jeûne</span></strong> (le jeûne aggrave les <span>nausées</span>)</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span class=\"nc-green_bg\">Aliments qui </span><strong><span class=\"nc-green_bg\">donnent envie</span></strong></li>\n                <li><span class=\"nc-green_bg\">Aliments qui passent plus facilement : </span><strong><span class=\"nc-green_bg\">soupes, féculents</span></strong></li>\n                <li><strong><span class=\"nc-green_bg\">Gingembre</span></strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Comment manger</h4>\n\n      <ul>\n        <li><strong><span class=\"nc-green_bg\">Fractionner les repas</span></strong> : petites quantités plus souvent</li>\n        <li><span class=\"nc-green_bg\">Manger lentement, bien mâcher</span></li>\n        <li><strong><span class=\"nc-red_bg\">Éviter de se coucher trop vite</span></strong><span class=\"nc-red_bg\"> après le repas</span></li>\n      </ul>\n\n      <h4>Mesures médicamenteuses (formes sévères)</h4>\n\n      <table>\n        <thead><tr><th>Catégorie</th><th>Molécules</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Médicaments <span>à éviter</span></strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"nc-red nc-bold\">Antiémétiques</span> classiques</strong> (<span><span class=\"nc-red nc-bold\">métoclopramide</span></span>, <span>métopimazine</span>, <span>dompéridone</span>) — <em>généralement peu efficaces</em></li>\n                <li><span><span class=\"nc-red nc-bold\">Métoclopramide</span> : CONTRE-INDIQUÉ chez la femme enceinte ❌</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Médicaments préférés</strong></td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-pink_bg\">Pyridoxine (vitamine B6)</span></span>, seule ou associée à <span><span class=\"nc-pink_bg\">doxylamine</span></span></li>\n                <li><span class=\"nc-pink_bg\">Antagonistes des récepteurs </span><span><span class=\"nc-pink_bg\">H1</span></span> : <span>hydroxyzine</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p>📌 <em>Exceptionnellement, les <span>vomissements</span> peuvent entraîner une <span>carence en vitamine B1 → Gayet-Wernicke</span>.</em></p>\n\n      <h4>Hyperemesis gravidarum — focus</h4>\n\n      <ul>\n        <li>Forme sévère du T1, résistante au traitement symptomatique</li>\n        <li>Fréquence : <span>0,35 %</span> des grossesses</li>\n        <li>Origine inconnue (psychogène suspectée)</li>\n        <li>Manifestations : <span><span class=\"nc-orange_bg\">déshydratation</span></span>, <span><span class=\"nc-orange_bg\">dénutrition</span></span>, <span><span class=\"nc-blue_bg\">pertes ioniques</span></span>, <span><span class=\"nc-blue_bg\">cétonurie</span></span>, <span><span class=\"nc-blue_bg\">cytolyse</span></span>, <span>cholestase ± ictère</span></li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 27 — Prévention risques fœtaux</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_2899354/fr/le-depistage-de-la-trisomie-21\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage de la trisomie 21</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li></ul></details>","frequence":0},{"id":"23-15","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir reconnaitre les principales complications de la grossesse et savoir orienter les femmes vers le recours adapté","contenu":"<div class=\"notion-course\"><p>Plusieurs complications doivent être <span>reconnues précocement</span> au cours du <span>suivi</span> pour orienter vers le recours adapté (<span>hospitalisation</span>, maternité de niveau adéquat, <span>urgence</span> obstétricale).</p>\n\n      <h4>Complications pouvant être prévenues par un bon <span>suivi</span></h4>\n\n      <ul>\n        <li><strong>Anémie</strong> · <strong><span>HTA</span> gravidique / <span class=\"nc-red nc-bold\">pré-éclampsie</span></strong> · Immunisation Rh</li>\n        <li><span>Infection urinaire</span> (<span>BU</span> systématique tout au long du <span>suivi</span>) · IST</li>\n        <li><strong><span class=\"nc-red nc-bold\">Macrosomie</span></strong> et prise en charge du <strong><span>diabète gestationnel</span></strong></li>\n        <li>Présentation en <strong>siège</strong></li>\n        <li><strong>Travail prématuré</strong> · <strong>RCIU</strong></li>\n        <li><strong>Hypoxie / MFIU</strong> en cas de terme dépassé</li>\n      </ul>\n\n      <h4>Causes d’une hauteur utérine anormale (à dépister cliniquement)</h4>\n\n      <table>\n        <thead><tr><th>HU insuffisante</th><th>HU excessive</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <ul>\n                <li><span class=\"nc-green\">Erreur de terme</span></li>\n                <li><strong><span class=\"nc-red nc-bold\">Oligoamnios isolé</span></strong> ou associé à un <strong><span class=\"nc-red nc-bold\">RCIU</span></strong></li>\n                <li><span class=\"nc-green\">Enfant petit pour l’âge gestationnel</span></li>\n                <li><span class=\"nc-green\">Faux positif</span> de l’examen clinique</li>\n                <li><strong><span class=\"nc-red nc-bold\">Arrêt de la </span><span><span class=\"nc-red nc-bold\">grossesse</span></span> (MFIU)</strong></li>\n                <li>RPM</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span class=\"nc-green\">Erreur de terme</span></li>\n                <li><span><span class=\"nc-green\">Grossesse</span></span><span class=\"nc-green\"> multiple</span></li>\n                <li><strong>Macrosomie fœtale</strong></li>\n                <li><strong><span class=\"nc-red nc-bold\">Hydramnios</span></strong></li>\n                <li><strong><span class=\"nc-red nc-bold\">Utérus fibromateux</span></strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>CAT</strong> : toute HU anormale impose un <strong><span class=\"nc-blue nc-bold\">contrôle échographique</span></strong>.</p>\n\n      <h4><span>Vomissements</span> au 3<sup>e</sup> trimestre — deux <span class=\"nc-yellow_bg\">urgences thérapeutiques</span></h4>\n\n      <ul>\n        <li><strong><span class=\"nc-red nc-bold\">Stéatose aiguë gravidique</span></strong> (<span>0,01 %</span> des grossesses)</li>\n        <li><strong><span class=\"nc-red nc-bold\">Pré-éclampsie</span></strong></li>\n      </ul>\n\n      <h4>Hyperemesis gravidarum — forme sévère du 1<sup>er</sup> trimestre</h4>\n\n      <ul>\n        <li>Fréquence : <span>0,35 %</span> des grossesses</li>\n        <li>Résistant aux traitements symptomatiques</li>\n        <li>Manifestations : <span><span class=\"nc-orange_bg\">déshydratation</span></span>, <span><span class=\"nc-orange_bg\">dénutrition</span></span>, <span><span class=\"nc-blue_bg\">pertes ioniques</span></span>, <span><span class=\"nc-blue_bg\">cétonurie</span></span>, <span><span class=\"nc-blue_bg\">cytolyse</span></span>, <span><span class=\"nc-blue_bg\">cholestase ± ictérique</span></span></li>\n        <li><span>Hospitalisation</span> si <span>perte de poids</span> importante ou <span>intolérance</span> alimentaire totale</li>\n        <li>📌 <span>Vomissements</span> sévères → risque de carence en B1 → <strong>Gayet-Wernicke</strong></li>\n      </ul>\n\n      <h4><span class=\"nc-red nc-bold\">Anémie</span> de la <span>grossesse</span> — seuils diagnostiques</h4>\n\n      <table>\n        <thead><tr><th>Période</th><th>Seuil Hb</th></tr></thead>\n        <tbody>\n          <tr><td>Anémie 1<sup>er</sup> trimestre</td><td><span>&lt; 11 g/dL</span></td></tr>\n          <tr><td><strong>Anémie 2<sup>e</sup> trimestre</strong></td><td><span>&lt; 10,5 g/dL</span></td></tr>\n          <tr><td>Anémie 3<sup>e</sup> trimestre</td><td><span>&lt; 11 g/dL</span></td></tr>\n          <tr><td><strong>Carence martiale</strong></td><td><span>Ferritine</span> <span>&lt; 12 μg/L</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Signaux d’alerte (orientation urgente)</h4>\n\n      <ul>\n        <li><span>Métrorragies du 1<sup>er</sup> trim</span> → suspicion <em>GEU / FCS / môle</em> (cf items 25, 26)</li>\n        <li><span>Métrorragies du 3<sup>e</sup> trim</span> → suspicion <em>placenta prævia / HRP</em></li>\n        <li><span>HTA, protéinurie, œdème</span> → suspicion <em>pré-éclampsie</em></li>\n        <li><span><span class=\"nc-green_bg\">Contractions utérines</span> avant terme</span> → <span>menace</span> d’<span class=\"nc-red nc-bold\">accouchement prématuré</span></li>\n        <li><span>Diminution des MAF ou HU stagnante</span> → MFIU / RCIU à éliminer</li>\n        <li><span>BU</span> <strong><span>nitrites</span> / <span>leucocytes</span> +</strong> → <span>ECBU</span> et traitement ciblé (<span>pyélonéphrite gravidique = urgence</span>)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 24 — Complications de la <span>grossesse</span> · 25 — Grossesse extra-utérine · 26 — Douleur abdo aiguë chez femme enceinte · 30 — Prématurité, <span class=\"nc-red nc-bold\">RCIU</span> · 255 — <span>Diabète gestationnel</span></em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_2899354/fr/le-depistage-de-la-trisomie-21\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage de la trisomie 21</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li></ul></details>","frequence":1},{"id":"23-16","rang":"B","rubrique":"Prise en charge","titre":"Le projet de naissance","contenu":"<div class=\"notion-course\"><p>Historiquement, la préparation à la naissance était centrée sur la <strong>prise en charge de la douleur</strong>. Elle s’oriente <strong>actuellement</strong> vers un <span>accompagnement global</span> de la femme et du couple en favorisant leur participation active dans le projet de naissance.</p>\n\n      <h4>Définition</h4>\n\n      <p>Le <span>projet de naissance</span> = <strong>conjonction entre les aspirations de la femme/couple et l’offre de soins locale</strong>.</p>\n\n      <h4>Contenu du projet</h4>\n\n      <ul>\n        <li><strong>Organisation des soins</strong> : <span>suivi</span> médical et préparation à la naissance et à la parentalité</li>\n        <li><strong>Modalités d’accouchement</strong></li>\n        <li><strong>Possibilités de <span>suivi</span> postnatal</strong>, y compris conditions d’un <strong>retour précoce à domicile</strong></li>\n        <li><strong>Recours en cas de difficultés</strong></li>\n      </ul>\n\n      <h4>Formalisation</h4>\n\n      <ul>\n        <li>Peut être <strong>formalisé par un document écrit</strong> rédigé par les parents.</li>\n        <li>S’élabore au fil des consultations (<span>EPP</span> du 4<sup>e</sup> mois +++, <span class=\"nc-pink nc-bold\">8 séances</span> de PNP).</li>\n        <li>Doit pouvoir être <strong>discuté et adapté</strong> en fonction du niveau de risque évolutif et du choix de la maternité.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 31 — Accouchement - suites de couche normales · 33 — <span>Allaitement</span> maternel</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_2899354/fr/le-depistage-de-la-trisomie-21\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage de la trisomie 21</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li></ul></details>","frequence":0},{"id":"23-17","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Intégrer la dimension psychosociale au suivi de la femme enceinte et du couple","contenu":"<div class=\"notion-course\"><p>Le <span>suivi</span> de <span>grossesse</span> ne se limite pas aux gestes médicaux : il intègre une <span>approche psychosociale globale</span> dont l’<span>EPP</span> du 4<sup>e</sup> mois constitue le pivot.</p>\n\n      <h4><span class=\"nc-blue_bg\">Entretien prénatal précoce</span> (<span>EPP</span>)</h4>\n\n      <table>\n        <thead><tr><th>Item</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Définition</strong></td><td>1<sup>ère</sup> séance de la <strong>préparation à la naissance et à la parentalité (PNP)</strong> — <span class=\"nc-pink nc-bold\">8 séances</span> au total.</td></tr>\n          <tr><td><strong>Pour qui ?</strong></td><td>Individuel <strong>ou en couple</strong>.</td></tr>\n          <tr><td><strong>Quand ?</strong></td><td>Proposé systématiquement <strong>autour du 4<sup>e</sup> mois</strong>, plus tôt ou plus tard selon le besoin.</td></tr>\n          <tr><td><strong>Si refus ?</strong></td><td>Le refus de l’<span>EPP</span> <strong>ne doit pas empêcher</strong> la participation aux 7 autres séances de PNP.</td></tr>\n          <tr><td><strong>Par qui ?</strong></td><td>Professionnel de la périnatalité (essentiellement <strong><span class=\"nc-green_bg\">sages-femmes</span></strong>), parfois <span class=\"nc-green_bg\">médecin</span> formé.</td></tr>\n          <tr><td><strong>Durée</strong></td><td><span>45 minutes</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Contenu de l’<span>EPP</span></h4>\n\n      <ul>\n        <li><strong>Répondre aux questions, rassurer</strong>, permettre l’expression libre</li>\n        <li>Message : <em>« la <span>grossesse</span> n’est pas une maladie »</em> — travail, activité physique, trajets, sexualité possibles</li>\n        <li><strong><span class=\"nc-green_bg\">Recommandations alimentaires</span></strong> (toxoplasmose si séronégative, listériose)</li>\n        <li><strong><span><span class=\"nc-orange_bg\">Tabac</span></span> +++</strong> : arrêt / <span>sevrage</span> par substituts nicotiniques · <strong>Cannabis</strong> (<span>1 joint = 7 cigarettes</span>)</li>\n        <li><strong><span><span class=\"nc-orange_bg\">Alcool</span></span> +++</strong> : <span class=\"nc-red nc-bold\">tolérance zéro</span> (pas de seuil fœtotoxique déterminé)</li>\n        <li><span class=\"nc-pink_bg\">Opiacés</span>, <span class=\"nc-pink_bg\">psychotropes</span> (automédication d’anxiolytiques)</li>\n        <li><span class=\"nc-red_bg\">Dépister les</span> <strong><span class=\"nc-pink nc-bold\">perturbateurs endocriniens</span></strong></li>\n        <li>Carences (ATCD <span>chirurgie</span> bariatrique, végétariennes / végétaliennes) → supplémenter <strong>B9, B12</strong> si besoin</li>\n      </ul>\n\n      <h4>Examen postnatal de la femme</h4>\n\n      <table>\n        <thead><tr><th>Item</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Quand ?</strong></td><td><strong>&lt;<span> 6 à 8 semaines</span></strong> après l’accouchement.</td></tr>\n          <tr><td><strong>Caractère</strong></td><td><strong>Obligatoire</strong>.</td></tr>\n          <tr><td><strong>Qui ?</strong></td><td><span class=\"nc-green_bg\">Médecin</span> (généraliste ou spécialiste) <strong>ou <span class=\"nc-green_bg\">sage-femme</span></strong> (si <span>grossesse</span> et accouchement normaux).</td></tr>\n          <tr>\n            <td><strong>Éléments évoqués</strong></td>\n            <td>\n              <ul>\n                <li>Vécu de l’accouchement et suites, retour à domicile, relations mère / enfant / famille, reprise de la sexualité</li>\n                <li><strong>Recherche d’une <span><span class=\"nc-orange_bg\">dépression</span></span><span class=\"nc-orange_bg\"> du post-partum</span></strong></li>\n                <li>Examen gynécologique proposé (non systématique), <span>dépistage</span> du cancer du col si besoin</li>\n                <li><strong>Rééducation périnéale</strong> recommandée pour traiter :\n                  <ul>\n                    <li><strong><span class=\"nc-red nc-bold\">Incontinence urinaire</span></strong><span class=\"nc-red nc-bold\"> persistant à </span><span><span class=\"nc-red nc-bold\">3 mois</span></span> du post-partum</li>\n                    <li><strong><span class=\"nc-red nc-bold\">Incontinence anale</span></strong><span class=\"nc-red nc-bold\"> du post-partum</span></li>\n                  </ul>\n                </li>\n                <li>Discussion du <strong>souhait de contraception</strong></li>\n                <li>Congé pathologique supplémentaire <span class=\"nc-yellow_bg\">postnatal</span> de <strong><span>4 semaines</span></strong> si pathologie maternelle</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_2899354/fr/le-depistage-de-la-trisomie-21\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage de la trisomie 21</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li></ul></details>","frequence":0},{"id":"23-18","rang":"A","rubrique":"Prise en charge","titre":"Savoir informer la patiente de sa couverture sociale pendant la grossesse","contenu":"<div class=\"notion-course\"><p>Connaître les modalités de prise en charge à<span> 100 %</span> et le cadre légal du <strong><span class=\"nc-green_bg\">congé maternité</span></strong> est essentiel pour informer la patiente.</p>\n\n      <h4>Prise en charge à<span> 100 %</span> par l’assurance maladie</h4>\n\n      <ul>\n        <li><strong>8 consultations prénatales</strong> (examens obligatoires) jusqu’au 6<sup>e</sup> mois</li>\n        <li>Couverture médicale à <strong><span>100 %</span> à partir de 24 SA</strong></li>\n        <li><strong>Bilan <span class=\"nc-yellow_bg\">prénatal</span> de prévention</strong> (alimentation, <span>tabac</span>, <span><span class=\"nc-orange_bg\">alcool</span></span>) à réaliser avant 24 SA — <span class=\"nc-green_bg\">sage-femme</span> libérale ou de PMI</li>\n        <li><strong>Bilan bucco-dentaire</strong> au 4<sup>e</sup> mois</li>\n        <li><strong>Examen de santé pour le futur père</strong> si besoin</li>\n        <li><strong>Consultation postnatale obligatoire</strong></li>\n        <li><strong>3 échographies obstétricales</strong> (non obligatoires mais remboursées à<span> 100 %</span>)</li>\n      </ul>\n\n      <h4><span class=\"nc-green_bg\">Congé maternité</span> — principe</h4>\n\n      <p>Toute salariée en état de <span>grossesse</span> médicalement constatée a le droit de <strong>suspendre son contrat de travail</strong> pendant une durée déterminée, avant et après son accouchement, sans que cela ne constitue ni une cause de <span>rupture</span> ni une modification du contrat de travail.</p>\n\n      <h4>Conditions</h4>\n\n      <ul>\n        <li>Immatriculation <strong><span>≥ 10 mois</span></strong> à la date prévue d’accouchement.</li>\n      </ul>\n\n      <h4>Durée légale</h4>\n\n      <ul>\n        <li><strong><span>16 semaines</span> minimum</strong>, composées de :\n          <ul>\n            <li>Congé <strong><span class=\"nc-yellow_bg\">prénatal</span></strong> (débute à <span>35 SA</span>) : <span><span class=\"nc-pink nc-bold\">6 semaines</span></span><span class=\"nc-pink nc-bold\"> </span><strong><span class=\"nc-pink nc-bold\">avant</span></strong> l’accouchement</li>\n            <li>Congé <strong><span class=\"nc-yellow_bg\">postnatal</span></strong> : <span><span class=\"nc-pink nc-bold\">10 semaines</span></span><span class=\"nc-pink nc-bold\"> </span><strong><span class=\"nc-pink nc-bold\">après</span></strong> l’accouchement</li>\n          </ul>\n        </li>\n      </ul>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewbox=\"0 0 560 154\" role=\"img\" aria-label=\"Frise du congé maternité, cas standard pour un 1er ou 2e enfant : congé prénatal de 6 semaines débutant à 35 SA, accouchement à la date présumée, puis congé postnatal de 10 semaines, soit 16 semaines au total. La future mère peut reporter jusqu&#x27;à 3 semaines du congé prénatal vers le congé postnatal, avec l&#x27;accord du médecin ou de la sage-femme.\" style=\"height:auto;display:block;border-radius:8px\">\n          <text class=\"tx-title\" x=\"280\" y=\"15\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\">Congé maternité — cas standard (1er/2e enfant)</text>\n          <text class=\"tx-red\" x=\"220\" y=\"40\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"700\">Accouchement (DPA)</text>\n          <rect class=\"fb-blue\" x=\"40\" y=\"52\" width=\"180\" height=\"44\" rx=\"6\"></rect>\n          <text class=\"tx-blue\" x=\"130\" y=\"72\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"600\">Congé prénatal</text>\n          <text class=\"tx-blue\" x=\"130\" y=\"88\" text-anchor=\"middle\" font-size=\"8\"><span>6 semaines</span> · dès 35 SA</text>\n          <rect class=\"fb-teal\" x=\"220\" y=\"52\" width=\"300\" height=\"44\" rx=\"6\"></rect>\n          <text class=\"tx-teal\" x=\"370\" y=\"72\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"600\">Congé postnatal</text>\n          <text class=\"tx-teal\" x=\"370\" y=\"88\" text-anchor=\"middle\" font-size=\"9\"><span>10 semaines</span></text>\n          <rect class=\"fb-red\" x=\"216\" y=\"46\" width=\"8\" height=\"56\" rx=\"2\"></rect>\n          <text class=\"tx-muted\" x=\"280\" y=\"116\" text-anchor=\"middle\" font-size=\"9\">Total :<span> 16 semaines</span> (minimum légal indemnisé)</text>\n          <rect class=\"fb-amber\" x=\"40\" y=\"124\" width=\"480\" height=\"26\" rx=\"6\"></rect>\n          <text class=\"tx-amber\" x=\"280\" y=\"140\" text-anchor=\"middle\" font-size=\"8\">Modulation : report possible de 3 sem. max du prénatal vers le postnatal (accord médecin / sage-femme)</text>\n        </svg>\n        <figcaption>Cas standard 1er/2e enfant :<span> 6 semaines</span> de congé prénatal (début 35 SA) +<span> 10 semaines</span> postnatal =<span> 16 semaines</span> ; report de <span>3 semaines</span> max du prénatal vers le postnatal possible.</figcaption>\n      </figure>\n\n      <h4>Durée variable selon enfants</h4>\n\n      <table>\n        <thead>\n          <tr><th>Enfants à naître</th><th>Enfants déjà à charge</th><th>Prénatal</th><th>Postnatal</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>1</strong></td><td>0 ou 1</td><td><strong><span>6 semaines</span></strong></td><td><strong><span>10 semaines</span></strong></td></tr>\n          <tr><td><strong>1</strong></td><td>2 ou plus</td><td><strong><span>8 semaines</span></strong></td><td><strong><span>18 semaines</span></strong></td></tr>\n          <tr><td><strong>2</strong></td><td>—</td><td><strong><span>12 semaines</span></strong></td><td><strong><span>22 semaines</span></strong></td></tr>\n          <tr><td><strong>3 ou plus</strong></td><td>—</td><td><strong><span>24 semaines</span></strong></td><td><strong><span>22 semaines</span></strong></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Modulations</h4>\n\n      <table>\n        <thead><tr><th>Situation</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Salaire</strong></td>\n            <td>\n              <ul>\n                <li>L’employeur n’est pas tenu en théorie de maintenir le salaire — en pratique, c’est presque toujours le cas</li>\n                <li>Indemnités = <span class=\"nc-green_bg\">salaire moyen des 3 derniers mois</span> ou salaire journalier de base, dans la <strong>limite d’un plafond</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Durée raccourcie</strong></td>\n            <td>La future mère peut, à sa demande et après accord du <span class=\"nc-green_bg\">médecin</span> ou de la <span class=\"nc-green_bg\">sage-femme</span>, <strong>réduire de <span>3 semaines</span></strong> le congé <span class=\"nc-yellow_bg\">prénatal</span> — le <span class=\"nc-yellow_bg\">postnatal</span> est augmenté d’autant.</td>\n          </tr>\n          <tr>\n            <td><strong>Durée allongée</strong></td>\n            <td>\n              <ul>\n                <li><strong><span><span class=\"nc-red nc-bold\">Grossesse</span></span><span class=\"nc-red nc-bold\"> pathologique</span></strong> : congé <span class=\"nc-yellow_bg\">prénatal</span> supplémentaire jusqu’à <strong><span><span class=\"nc-pink nc-bold\">2 semaines</span></span></strong></li>\n                <li><span class=\"nc-red_bg\">Caractère pathologique de l’accouchement ou du post-partum</span></li>\n                <li>Selon le nombre d’enfants à charge et attendus</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Congé paternité</strong></td>\n            <td><span>25 jours</span> (payés par la sécurité sociale).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 31 — Accouchement - suites de couche normales · 36 — Contraception</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_2899354/fr/le-depistage-de-la-trisomie-21\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage de la trisomie 21</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li></ul></details>","frequence":0},{"id":"23-19","rang":"A","rubrique":"Définition","titre":"Connaître l’existence des violences obstétricales","contenu":"<div class=\"notion-course\"><p><span>Violences obstétricales et gynécologiques</span> = <span class=\"nc-red_bg\">comportements, actes, paroles ou omissions commis par un professionnel de santé</span>, <strong>non justifiés médicalement</strong> ou <span class=\"nc-red_bg\">accomplis </span><strong><span class=\"nc-red_bg\">sans le consentement libre et éclairé de la femme</span></strong>.</p>\n\n      <h4>Qui et quand ?</h4>\n\n      <ul>\n        <li><strong>Responsables</strong> : tout intervenant de santé quel que soit son statut, son genre ou son âge.</li>\n        <li><strong>Périodes à risque</strong> : <span>suivi</span> gynécologique, parcours PMA, suivi de <span>grossesse</span>, accouchement, post-partum — <em>période périnatale particulièrement à risque</em> (gestes nombreux, sphère intime).</li>\n      </ul>\n\n      <h4>Les 7 dimensions des violences</h4>\n\n      <ul>\n        <li>Violence <strong><span class=\"nc-red\">physique</span></strong></li>\n        <li>Violence <strong><span class=\"nc-red\">sexuelle</span></strong></li>\n        <li>Violence <strong><span class=\"nc-red\">verbale</span></strong></li>\n        <li><strong><span class=\"nc-green_bg\">Stigmatisation et discrimination</span></strong> (racisme, homophobie…)</li>\n        <li><strong><span class=\"nc-orange_bg\">Absence de respect des règles de bonne pratique</span></strong>, soins inappropriés</li>\n        <li><strong><span class=\"nc-orange_bg\">Mauvais rapport</span></strong> entre la femme et un (des) soignant(s)</li>\n        <li><strong><span class=\"nc-orange_bg\">Violence institutionnelle</span></strong> (mauvaises conditions et contraintes dues au système de santé)</li>\n      </ul>\n\n      <h4>Fréquence</h4>\n\n      <ul>\n        <li>Mal connue : <span>13 à 100 %</span> selon les études.</li>\n        <li>Enquête française (réseau de Bourgogne) : <span>69 %</span> des femmes estimaient <em>ne pas</em> avoir subi de violence.</li>\n      </ul>\n\n      <h4>Standards OMS 2017</h4>\n\n      <p>L’OMS a publié <strong>8 normes de qualité</strong> des soins maternels et néonatals (31 chartes de qualité) pour évaluer dans quelle mesure les services améliorent les résultats de santé et sont <em>sûrs, efficaces, opportuns, équitables et centrés sur les personnes</em>.</p>\n\n      <table>\n        <thead>\n          <tr><th>Standard</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>1</strong></td><td>Soins basés sur les données factuelles (travail, accouchement, post-partum, complications) selon recommandations OMS.</td></tr>\n          <tr><td><strong>2</strong></td><td>Système d’information sanitaire permettant une décision rapide et appropriée.</td></tr>\n          <tr><td><strong>3</strong></td><td>Transfert des femmes / nouveau-nés vers établissements adaptés si pathologie hors ressources locales.</td></tr>\n          <tr><td><strong>4</strong></td><td>Communication efficace, respectant les besoins et préférences.</td></tr>\n          <tr><td><strong>5</strong></td><td>Soins dispensés avec respect et maintien de la dignité.</td></tr>\n          <tr><td><strong>6</strong></td><td>Soutien psychosocial aux femmes et à leur famille.</td></tr>\n          <tr><td><strong>7</strong></td><td>Personnel compétent et motivé disponible à tout moment.</td></tr>\n          <tr><td><strong>8</strong></td><td>Environnement adéquat (énergie, eau, médicaments, matériel) pour soins courants et complications.</td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>Règle absolue</strong> : le <span>consentement</span> doit être <strong>systématiquement recueilli avant tout soin</strong>.</p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://www.has-sante.fr/jcms/c_2899354/fr/le-depistage-de-la-trisomie-21\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage de la trisomie 21</a></li><li><a href=\"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi\" target=\"_blank\" rel=\"noopener noreferrer\">HAS · Dépistage du CMV et prise en charge, 2026</a></li></ul></details>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://manuel4.cuen.fr/spip.php?rubrique23","label":"CUEN — Néphrologie & grossesse (rubrique 23)"},{"href":"https://cego-obgyn.fr/deuxieme-cycle/","label":"Collège CNGOF–CEGO · Référentiel, 6e édition 2024"},{"href":"https://www.has-sante.fr/jcms/c_2899354/fr/le-depistage-de-la-trisomie-21","label":"HAS · Dépistage de la trisomie 21"},{"href":"https://www.has-sante.fr/jcms/p_3748990/fr/depistage-du-cytomegalovirus-au-1er-trimestre-de-la-grossesse-prise-en-charge-et-suivi","label":"HAS · Dépistage du CMV et prise en charge, 2026"}],"cards":[{"i":"1dc316df6ab5","n":23,"o":"23-1","u":"Physiopathologie","t":"Connaître les modifications physiologiques au cours de la grossesse","q":"Que retenir concernant les modifications physiologiques au cours de la grossesse ?","a":"<div class=\"notion-course\"><p>La <span>grossesse</span> entraîne des modifications anatomiques et physiologiques chez la mère, induites par les <strong>sécrétions hormonales</strong>. Tous les systèmes sont atteints mais les modifications les plus importantes sont <span>métaboliques, respiratoires et cardiovasculaires</span>.</p>\n\n      <h4>Modifications respiratoires</h4>\n\n      <table>\n        <thead><tr><th>Système</th><th>Modifications</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Anatomie pulmonaire</strong><br>(croissance utérine)</td>\n            <td>\n              <ul>\n                <li>Élargissement de la <span class=\"nc-blue_bg\">cage thoracique</span></li>\n                <li><strong><span class=\"nc-pink nc-bold\">Élévation</span> du <span class=\"nc-pink nc-bold\">diaphragme</span></strong></li>\n                <li>Augmentation du <span><span class=\"nc-blue_bg\">diamètre</span></span><span class=\"nc-blue_bg\"> transversal des poumons</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Volumes respiratoires</strong></td>\n            <td>\n              <ul>\n                <li>↑ <span class=\"nc-yellow_bg\">ventilation</span> (effet <em>progestérone</em>)</li>\n                <li>↑ consommation en O<sub>2</sub></li>\n                <li>↑ <span>capacité vitale</span> (<span>CV</span>) et volume courant (Vt)</li>\n                <li>↓ réserve expiratoire</li>\n                <li>→ ↑ capacité inspiratoire + ↓ volume résiduel (Vr)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Gaz du sang</span></strong></td>\n            <td>\n              <ul>\n                <li><strong><span><span class=\"nc-green_bg\">pH</span></span><span class=\"nc-green_bg\"> peu modifié</span></strong> (baisse équivalente de PaCO<sub>2</sub> et HCO<sub>3</sub><sup>−</sup>)</li>\n                <li>↓ PaCO<sub>2</sub> (<span>dyspnée</span> / etouffement, ↓ <span>bicarbonates</span>)</li>\n                <li>↑ PaO<sub>2</sub></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Modifications cardio-circulatoires</h4>\n\n      <p>Modifications hormonales : <strong>Œstrogènes</strong> (↑ FC et débits), <strong>Progestérone</strong> (<span class=\"nc-green_bg\">relâchement veineux</span>, <span class=\"nc-green_bg\">rétention hydrique</span>), <strong>SRAA</strong> (↑ <span class=\"nc-pink nc-bold\">rénine</span> rein + <span class=\"nc-yellow_bg\">placenta</span>, <span class=\"nc-pink nc-bold\">prorénine</span> fœtale, <span class=\"nc-pink nc-bold\">aldostérone plasmatique</span>).</p>\n\n      <table>\n        <thead><tr><th>Paramètre</th><th><span>Évolution</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Débit cardiaque<br>+ débit rénal</strong></td>\n            <td>↑ débit sanguin rénal (<span>+ 40 %</span>), ↑ filtration glomérulaire et ↑ débit cardiaque (en particulier à l’<em><span class=\"nc-yellow_bg\">accouchement</span></em>).</td>\n          </tr>\n          <tr>\n            <td><strong>Pressions artérielles</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"nc-red nc-bold\">Chute</span></strong> au 1<sup>er</sup> trimestre (−<span> 5–10 mmHg</span>)</li>\n                <li><strong><span class=\"nc-red nc-bold\">Stable</span></strong> au 2<sup>nd</sup> trimestre</li>\n                <li><strong><span class=\"nc-green nc-bold\">Normalisation</span></strong> au 3<sup>e</sup> trimestre</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Pressions veineuses</strong><br>(<span class=\"nc-yellow_bg\">effet Poseiro</span>)</td>\n            <td>\n              <ul>\n                <li>Pressions oreillette droite <strong>non modifiées</strong></li>\n                <li>Compression utérine de la VCI (décubitus dorsal) gène le retour veineux → ↑ pressions veineuses <strong><span class=\"nc-red nc-bold\">membres inférieurs</span></strong></li>\n                <li>→ <span>ralentissement du rythme cardiaque fœtal</span> + <span><span class=\"nc-red nc-bold\">malaise maternel</span></span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Volémie</strong></td>\n            <td><strong><span class=\"nc-yellow_bg\">Hypervolémie</span></strong> physiologique pour <em><span class=\"nc-green nc-bold\">limiter les conséquences de l’hémorragie lors de l’accouchement</span></em>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      \n\n      <h4>Hémostase et <span>NFS</span> — la <span>grossesse</span> est <span class=\"nc-red nc-bold\">procoagulante</span></h4>\n\n      <table>\n        <thead><tr><th><span>NFS</span></th><th>Hémostase (procoagulante)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <ul>\n                <li>GR : <span>3,8–4 M/mL</span></li>\n                <li><span>Leucocytes</span> normaux : <span>&lt; 15 000/mL</span></li>\n                <li>PNN très augmentés (<span class=\"nc-brown nc-bold\">myélocytes</span> et <span class=\"nc-brown nc-bold\">métamyélocytes</span> à <span>3 %</span>)</li>\n                <li><span class=\"nc-yellow_bg\">Hb : </span><span><span class=\"nc-yellow_bg\">11–12 g/dL</span></span>, <span>VGM</span> et <span>CCMH</span> inchangés</li>\n                <li><span>Plaquettes</span> quasi constantes, ↓ en fin de <span>grossesse</span></li>\n                <li><span>VS</span> ↑ (<em>aucun intérêt pendant la <span>grossesse</span></em>)</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span>Fibrinogène</span> ↑ (<span>5–6 g/L</span>)</li>\n                <li>Facteurs <span class=\"nc-blue_bg\">VII</span> et <span class=\"nc-blue_bg\">VIII</span> très ↑ (<span class=\"nc-blue_bg\">VII</span> =<span> 200 %</span>)</li>\n                <li>Facteurs IX, X, XII ↑ (X =<span> 150 %</span>)</li>\n                <li>Facteur II ↑ (<span>128 %</span>)</li>\n                <li>Facteur V inchangé ou légèrement ↑</li>\n                <li>Facteurs <strong>XI et XIII</strong> ↓ (<span>50–60 %</span>)</li>\n                <li><strong>ATIII</strong> ↓ (<span>10 %</span>) et <strong>protéine S</strong> ↓</li>\n                <li>Activité fibrinolytique ↓</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Endocrinien et métabolisme</h4>\n\n      <table>\n        <thead><tr><th>Système</th><th>Modifications</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Hypophyse +++</strong></td><td><span class=\"nc-green_bg\">Hypervascularisation</span> + <span class=\"nc-green_bg\">hyperplasie</span> · <strong><span class=\"nc-pink nc-bold\">Ocytocine</span></strong></td></tr>\n          <tr><td><strong>Corticotrope</strong></td><td><span class=\"nc-orange_bg\">Hypercorticisme</span> physiologique et adaptatif</td></tr>\n          <tr><td><strong>Thyroïde</strong></td><td>↑ fonctionnement : <em><span class=\"nc-green_bg\">hypertrophie</span> <span class=\"nc-green_bg\">/ goitre</span></em> (↓ iode organique plasmatique) · <span>TSH</span> légèrement ↓ (surtout 1<sup>er</sup> trim) · T3-T4 normales</td></tr>\n          <tr><td><strong>Parathyroïdes</strong></td><td>Globalement : ↓ <span>calcémie</span></td></tr>\n          <tr><td><strong>Métabolisme basal</strong></td><td>↑ <span><span class=\"nc-pink nc-bold\">+15 à 30 %</span></span> · accumulation de <span class=\"nc-green nc-bold\">réserves</span> au T1/T2, mobilisation au profit du <span class=\"nc-green nc-bold\">fœtus</span> au T3</td></tr>\n          <tr>\n            <td><strong>Métabolisme glucidique</strong></td>\n            <td>\n              <ul>\n                <li>1<sup>er</sup> trim : ↑ sensibilité à l’<span>insuline</span> (<span>glycémie</span> plutôt basse)</li>\n                <li>2<sup>nd</sup> trim : <strong><span class=\"nc-orange_bg\">insulinorésistance</span></strong> (effet <span class=\"nc-pink nc-bold\">hormone lactogène placentaire</span> +++ et <span class=\"nc-pink nc-bold\">prolactine</span>), compensée par hyperinsulinisme — sinon <em><span>diabète gestationnel</span></em></li>\n              </ul>\n            </td>\n          </tr>\n          <tr><td><strong>Température</strong></td><td>Plateau thermique <span>≥ 37 °C</span> au 1<sup>er</sup> trim (progestérone) · tendance à l’<span>hypothermie</span> en fin de <span>grossesse</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Prise de poids gestationnelle</h4>\n\n      <ul>\n        <li><strong>Causes</strong> : accumulation de <span class=\"nc-green nc-bold\">liquide interstitiel</span> + <span class=\"nc-green nc-bold\">eau extracellulaire</span> + <span class=\"nc-green nc-bold\">réserves</span> <span class=\"nc-green nc-bold\">graisseuses</span> + <span class=\"nc-green nc-bold\">fœtus</span> / <span class=\"nc-green nc-bold\">placenta</span> / <span class=\"nc-green nc-bold\">liquide amniotique</span>.</li>\n        <li><strong>Moyenne</strong> : <span>≈ 13 kg</span>.</li>\n        <li><strong>Cinétique</strong> : faible au T1, plus marquée au T2/T3 (≈ <span>+1 kg/mois</span> T1-T2, <span>+500 g/mois</span> T3).</li>\n        <li><strong>Risques</strong> :\n          <ul>\n            <li>Excessive → <span><span class=\"nc-red nc-bold\">HTA</span></span><span class=\"nc-red nc-bold\"> gravidique</span>, <span class=\"nc-red nc-bold\">macrosomie</span>, <span class=\"nc-red nc-bold\">césarienne</span></li>\n            <li>Insuffisante → <span class=\"nc-red nc-bold\">faible poids de naissance</span>, <span class=\"nc-red nc-bold\">accouchement prématuré</span></li>\n          </ul>\n        </li>\n      </ul>\n\n      <table>\n        <thead>\n          <tr><th>IMC préconceptionnel (kg/m²)</th><th>Gain total recommandé</th><th>Taux moyen T2-T3 (kg/sem)</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>&lt; 18,5</strong> (insuffisance pondérale)</td><td><span>12,5 – 18 kg</span></td><td><span>0,5</span></td></tr>\n          <tr><td><strong>18,5 ≤ IMC <span>≤ 24,9</span></strong> (poids normal)</td><td><span>11,5 – 16 kg</span></td><td><span>0,4</span></td></tr>\n          <tr><td><strong>25,0 ≤ IMC <span>≤ 29,9</span></strong> (<span>surpoids</span>)</td><td><span>7 – 11,5 kg</span></td><td><span>0,3</span></td></tr>\n          <tr><td><strong><span>≥ 30</span></strong> (<span>obésité</span>)</td><td><span>5 – 9 kg</span></td><td><span>0,2</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Autres systèmes (synthèse)</h4>\n\n      <table>\n        <thead><tr><th>Système</th><th>Modifications</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Œsophage</strong></td><td>↓ tonus sphincter œsophagien inférieur → <em>pyrosis</em></td></tr>\n          <tr><td><strong>Estomac</strong></td><td>↓ tonicité et péristaltisme, ↑ pression gastrique, ouverture de l’angle de His, sécrétion de gastrine placentaire</td></tr>\n          <tr><td><strong>Foie</strong></td><td>↑ synthèse protéique (<span>albumine</span> +++) · TG (3 N) et <span><span class=\"nc-orange_bg\">cholestérol</span></span> (2 N) ↑ · <strong><span>PAL</span> ↑</strong> (origine placentaire)</td></tr>\n          <tr><td><strong><span>Vésicule</span> biliaire</strong></td><td>Atone, <span class=\"nc-red nc-bold\">vidange ralentie</span></td></tr>\n          <tr><td><strong>Grêle / Côlon</strong></td><td>↓ mobilité grêle · ↑ réabsorption eau + Na côlon</td></tr>\n          <tr><td><strong>Vasculaire</strong></td><td><span>Œdèmes</span> visage / extrémités, <span class=\"nc-blue_bg\">angiomes stellaires</span>, <span class=\"nc-brown_bg\">érythrose palmaire</span>, varices (hyperpression Poseiro)</td></tr>\n          <tr><td><strong>SNC</strong></td><td>↑ <span class=\"nc-pink nc-bold\">endorphines</span> / <span class=\"nc-pink nc-bold\">enképhalines</span> · ↓ <span class=\"nc-orange_bg\">attention</span>, <span class=\"nc-orange_bg\">insomnie</span>, post-partum blues</td></tr>\n          <tr><td><strong>Musculo-squelettique</strong></td><td>↑ mobilité articulations du bassin, <span class=\"nc-orange\">lordose</span></td></tr>\n          <tr>\n            <td><strong>Urinaire / rénal</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-blue_bg\">Dilatation urétérale</span> possible dès <span><span class=\"nc-pink nc-bold\">6 SA</span></span>, <strong><span class=\"nc-red nc-bold\">prédominante à</span> <span class=\"nc-red nc-bold\">droite</span></strong>, physiologique</li>\n                <li>↑ flux plasmatique et filtration glomérulaire (+<span> 40 %</span>) → ↑ taille/poids des reins, ↓ <span>urée</span> et <span>créatinine</span></li>\n                <li><span class=\"nc-yellow_bg\">Glycosurie</span> + acidurie aminée, ↑ modérée de <span>protéinurie</span> (<span>&lt; 300 mg/24 h</span>)</li>\n                <li><span class=\"nc-blue_bg\">Bilan sodé positif</span> (<span>+ 500-900 mmoles</span>), <span class=\"nc-blue_bg\">bilan hydrique positif</span> (<span>+ 6–8 L</span>) en fin de <span>grossesse</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr><td><strong>Peau</strong></td><td><span class=\"nc-blue_bg\">Vergetures</span>, <span class=\"nc-blue_bg\">ligne brune</span>, <span class=\"nc-blue_bg\">masque de </span><span><span class=\"nc-blue_bg\">grossesse</span></span> (<em>mélasma</em> — éviter le soleil), <span class=\"nc-brown_bg\">hyperpigmentation</span></td></tr>\n          <tr><td><strong>Seins</strong></td><td>↑ volume, modification aréoles / mamelons</td></tr>\n          <tr><td><strong>Yeux</strong></td><td>↑ pression intra-oculaire, <span>œdème</span> cornéen</td></tr>\n          <tr><td><strong>Génital</strong></td><td>Congestion vulvaire, ↑ épaisseur muqueuse vaginale, ↑ leucorrhées, ↓ <span>pH</span> vaginal</td></tr>\n        </tbody>\n      </table></div>"},{"i":"48658c3b764b","n":23,"o":"23-2","u":"Diagnostic positif","t":"Diagnostic de grossesse","q":"Que retenir concernant diagnostic de grossesse ?","a":"<div class=\"notion-course\"><p>📌 Le <span>diagnostic de grossesse <span class=\"nc-red nc-bold\">repose sur la clinique</span></span>, et si besoin, sur les examens complémentaires (test urinaire ou plasmatique hCG, <span><span class=\"nc-blue nc-bold\">échographie</span></span> pelvienne).</p>\n\n      <h4>Examen clinique</h4>\n\n      <table>\n        <thead><tr><th>Domaine</th><th>Signes</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Signes fonctionnels</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-yellow_bg\">Retard de règles</span></li>\n                <li>Signes « sympathiques » : <span><span class=\"nc-blue nc-bold\">tension mammaire</span></span>, <span><span class=\"nc-blue nc-bold\">somnolence</span></span>, <span><span class=\"nc-blue nc-bold\">fatigue</span></span>, <span><span class=\"nc-blue nc-bold\">pollakiurie</span></span>, <span>nausées / <span class=\"nc-blue nc-bold\">vomissements</span></span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Spéculum</strong> <em>(non systématique)</em></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-blue_bg\">Col violacé</span></li>\n                <li><span class=\"nc-blue_bg\">Glaire cervicale coagulée voire absente</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Toucher vaginal</strong> <em>(non systématique)</em></td>\n            <td>\n              <ul>\n                <li>Ramollissement utérin commence à la <span>8<sup>e</sup> SA</span></li>\n                <li><span class=\"nc-green_bg\">Augmentation du volume</span> utérin : épaississement avant/arrière, <span class=\"nc-blue_bg\">forme sphérique</span></li>\n                <li><strong><span class=\"nc-yellow_bg\">Signe de Noble</span></strong> (doigt dans les <span class=\"nc-purple nc-bold\">culs-de-sac latéraux</span> bute contre le contour évasé de l’utérus)</li>\n                <li>Comparaisons : <strong><span class=\"nc-pink nc-bold\">Mandarine</span></strong> (7<sup>e</sup> SA), <strong><span class=\"nc-pink nc-bold\">Orange</span></strong> (10-12<sup>e</sup> SA), <strong><span class=\"nc-pink nc-bold\">Pamplemousse</span></strong> (14<sup>e</sup> SA)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Doppler</span> fœtal</strong></td>\n            <td>\n              <ul>\n                <li>BDC perçus à la fin du 3<sup>e</sup> mois, parfois dès <span><span class=\"nc-pink nc-bold\">9 SA</span></span></li>\n                <li>Valeurs : <span><span class=\"nc-pink_bg\">190–200 bpm</span></span> à <span>9 SA</span>, <span><span class=\"nc-pink_bg\">130–150 bpm</span></span> à <span>14 SA</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Anthropométrie</strong></td>\n            <td>Prise du poids, PA, taille → calcul de l’IMC</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Tests de <span>grossesse</span> (en cas de doute diagnostique)</h4>\n\n      <p>Tous basés sur la détection de <strong>l’hCG</strong>. Tests urinaires <span class=\"nc-red nc-bold\">vendus en pharmacie </span><em><span class=\"nc-red nc-bold\">sans ordonnance</span> et <span class=\"nc-red nc-bold\">non remboursés</span></em>. Test de référence : <strong>dosage plasmatique de l’hCG</strong>.</p>\n\n      <table>\n        <thead><tr><th>Test</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Test urinaire</strong></td>\n            <td>\n              <ul>\n                <li>Colorimétrique qualitatif, anticorps monoclonaux — très fiable mais non Se / Sp à<span> 100 %</span></li>\n                <li><strong>FP</strong> : <span>protéinurie</span>, <span>hématurie</span>, certains médicaments (BZD, neuroleptiques), &lt; 15 j après injection d’hCG (AMP)</li>\n                <li><strong>FN</strong> : forte densité urinaire (↑ <span>pH</span>, urates, restriction hydrique)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>β-hCG plasmatique</strong></td>\n            <td>\n              <ul>\n                <li>Test immunologique très fiable pour le <strong>diagnostic</strong> ✅</li>\n                <li><strong>Pas pour la datation</strong> ❌</li>\n                <li>Qualitatif (positif/négatif) ou quantitatif (UI/L)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span>Échographie</span> pelvienne</strong></td>\n            <td>\n              <ul>\n                <li>Sac gestationnel visible <strong><span class=\"nc-pink nc-bold\">dès 5 SA</span></strong> (voie vaginale, hCG &gt; 1 <span>500 UI/L</span>)</li>\n                <li>Activité cardiaque visible <strong><span class=\"nc-pink nc-bold\">dès 5 SA</span> + ½</strong> (<span>échographie</span> vaginale)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Rappel — physiologie de l’hCG</h4>\n\n      <ul>\n        <li>Sécrétée par les cellules trophoblastiques puis par le placenta.</li>\n        <li>Détectable dès le <span>9<sup>e</sup> jour</span> post-fécondation (= 2 j post-implantation).</li>\n        <li><strong><span class=\"nc-pink nc-bold\">Double toutes les </span><span><span class=\"nc-pink nc-bold\">48 h</span></span></strong> au 1<sup>er</sup> trimestre.</li>\n        <li><span class=\"nc-red nc-bold\">Chute</span> au 2<sup>e</sup> trimestre, plateau à ~5 <span>000 UI</span> jusqu’à fin de <span>grossesse</span>.</li>\n        <li>Disparaît dans les 5 j post-accouchement.</li>\n        <li><strong>Rôle</strong> : stimuler le corps jaune (maintien de la <span>grossesse</span> au T1, jusqu’au relais placentaire au T2).</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 25 — <span>Grossesse</span> extra-utérine</em></p></div>"},{"i":"83d3b943a8fa","n":23,"o":"23-3","u":"Prise en charge","t":"Détermination du terme","q":"Que retenir concernant détermination du terme ?","a":"<div class=\"notion-course\"><p>Il faut fixer une <strong>date de début de <span>grossesse</span></strong> pour la déclaration et calculer le terme. Avoir un âge gestationnel exact est primordial sur le plan <span>légal</span> (déclaration, congé <span class=\"nc-yellow_bg\">prénatal</span>) et <span>médical</span> (prématurité, <span class=\"nc-red nc-bold\">RCIU</span>, <span class=\"nc-red nc-bold\">macrosomie</span>, dépassement de terme).</p>\n\n      <h4>Définitions et durée</h4>\n\n      <table>\n        <thead><tr><th>Notion</th><th>Définition / valeur</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>SA</strong></td>\n            <td>Semaines depuis le <strong>1<sup>er</sup> jour des dernières règles</strong>. Le début de <span>grossesse</span> correspond au jour de l’ovulation = <strong>J14 du cycle</strong> (sachant que <span>J1</span> du cycle = 1<sup>er</sup> jour des règles).</td>\n          </tr>\n          <tr>\n            <td><strong>Durée moyenne</strong></td>\n            <td><span>285 jours</span> = <span><span class=\"nc-pink nc-bold\">40,5 SA</span></span> (varie 280-290 j, soit 40 à 41 SA + 3 j).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Calcul du terme</h4>\n\n      <ul>\n        <li>Date début de <span>grossesse</span> + <strong><span>9 mois</span></strong></li>\n        <li>Date du 1<sup>er</sup> jour des dernières règles + <strong><span>14 jours</span> +<span> 9 mois</span></strong></li>\n        <li>En cas de <strong>FIV</strong> : date de début de <span>grossesse</span> = date de <span>ponction</span> (= jour de fécondation)</li>\n      </ul>\n\n      <h4>Méthodes de datation</h4>\n\n      <table>\n        <thead><tr><th>Méthode</th><th>Performance</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Datation selon dernières règles</strong></td>\n            <td><em>Imprécis</em> dans <span>10–30 %</span> des cas (mauvais reflet de l’âge gestationnel).</td>\n          </tr>\n          <tr>\n            <td><strong>Datation échographique</strong> ✅</td>\n            <td>\n              <ul>\n                <li>Mesure : <strong>longueur cranio-caudale (<span class=\"nc-blue_bg\">LCC</span>)</strong></li>\n                <li>Quand : entre <strong>11 SA et 13 SA + 6 j</strong></li>\n                <li><strong>Précision :<span> 4 jours</span></strong> (moyen le plus fiable)</li>\n                <li>Valeurs indicatives : <span>45 mm</span> (11 SA), <span>56 mm</span> (12 SA), <span>72 mm</span> (13 SA), <span>85 mm</span> (14 SA)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Repère trimestriel</h4>\n\n      <table>\n        <thead>\n          <tr><th></th><th>1<sup>er</sup> trimestre</th><th>2<sup>e</sup> trimestre</th><th>3<sup>e</sup> trimestre</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Semaines de <span>grossesse</span></strong></td><td>&lt; 14</td><td>14 – 26</td><td>&gt; 26</td></tr>\n          <tr><td><strong>Semaines d’aménorrhée (SA)</strong></td><td>&lt; <strong>16</strong></td><td>16 – <strong>28</strong></td><td>&gt; 28</td></tr>\n        </tbody>\n      </table></div>"},{"i":"082c836e1d24","n":23,"o":"23-4","u":"Epidémiologie","t":"Évaluation des facteurs de risque (médicaux et psycho-sociaux dont professionnels)","q":"Que retenir concernant évaluation des facteurs de risque (médicaux et psycho-sociaux dont professionnels) ?","a":"<div class=\"notion-course\"><p>L’évaluation des FdR est <span>indispensable lors de la consultation du 1<sup>er</sup> trimestre</span> car la <strong>découverte d’un FdR modifie le type de <span>suivi</span> obstétrical (A, A1, A2, B)</strong>.</p>\n\n      <h4>Répartition épidémiologique de la gravité</h4>\n\n      <ul>\n        <li>Grossesses normales : <span>60 %</span></li>\n        <li>Grossesses difficiles : <span>40 %</span></li>\n        <li>Grossesses à risque : <span>10 %</span></li>\n      </ul>\n\n      <h4>Complications pouvant être prévenues par un bon <span>suivi</span></h4>\n\n      <ul>\n        <li>Anémie · <span>HTA</span> · Immunisation Rh</li>\n        <li><span>Infection urinaire</span> · Maladie sexuellement transmissible</li>\n        <li><span class=\"nc-red nc-bold\">Macrosomie</span> et prise en charge du <span>diabète</span></li>\n        <li>Siège</li>\n        <li>Travail prématuré · RCIU</li>\n        <li>Hypoxie et mort in utero en cas de terme dépassé</li>\n      </ul>\n\n      <h4><span>Facteurs de risque</span> à rechercher à l’interrogatoire</h4>\n\n      <table>\n        <thead><tr><th>Catégorie</th><th>Éléments</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Âge</strong></td><td><span>&lt; 15 ans</span> et <span>&gt; 35 ans</span></td></tr>\n          <tr>\n            <td><strong>ATCD familiaux</strong></td>\n            <td>\n              <ul>\n                <li>Maladie <span>héréditaire</span> (mucoviscidose, retard mental, myopathie, anomalie chromosomique, hémophilie)</li>\n                <li><span>HTA</span>, <span>diabète</span>, maladie thrombo-<span>embolique</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>ATCD personnels — médicaux</strong></td>\n            <td>\n              <ul>\n                <li><strong>IMC &gt;<span> 25 kg/m²</span></strong></li>\n                <li><span>Tabac</span>, <span><span class=\"nc-orange_bg\">alcool</span></span>, toxicomanie</li>\n                <li>Affection nécessitant médicaments potentiellement tératogènes</li>\n                <li><strong><span class=\"nc-pink nc-bold\">Perturbateurs endocriniens</span></strong></li>\n                <li><span>HTA</span>, infections urinaires, comitialité</li>\n                <li><span>VIH</span>, <span>hépatite</span> B ou C, <span>allergie</span>, immunisation rhésus</li>\n                <li>Maladie endocrinienne, thrombophilie, néphropathie, <span>diabète</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>ATCD personnels — chirurgicaux</strong></td>\n            <td><span class=\"nc-orange_bg\">Fracture du bassin</span>, <strong><span><span class=\"nc-pink nc-bold\">chirurgie</span></span><span class=\"nc-pink nc-bold\"> utérine</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong>ATCD gynécologiques</strong></td>\n            <td><span class=\"nc-orange_bg\">Fibrome</span>, <span class=\"nc-orange_bg\">herpès génital</span>, malformation utérine</td>\n          </tr>\n          <tr>\n            <td><strong>ATCD obstétricaux<br>(pathologie pouvant récidiver)</strong></td>\n            <td>\n              <ul>\n                <li>GEU, FCS</li>\n                <li><span>HTA</span>, pré-éclampsie</li>\n                <li>Malformation fœtale, <span class=\"nc-red nc-bold\">accouchement prématuré</span></li>\n                <li>Cholestase gravidique, <span>diabète gestationnel</span></li>\n                <li><span class=\"nc-red nc-bold\">Césarienne</span>, poids des précédents enfants, devenir néonatal</li>\n                <li>HRP, incompatibilité fœto-maternelle, cancer du sein</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>ATCD <span>infectieux</span></strong></td>\n            <td><span class=\"nc-purple_bg\">Toxoplasmose</span>, rubéole, herpès buccal, syphilis · séjour en zone d’endémie <em>Zika</em></td>\n          </tr>\n          <tr>\n            <td><strong>Socio-économiques</strong></td>\n            <td><span class=\"nc-green_bg\">Précarité</span>, <span class=\"nc-green_bg\">chômage</span>, mère <span class=\"nc-green_bg\">célibataire</span>, <span class=\"nc-green_bg\">migrante</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Mode de <span>surveillance</span> obstétricale en fonction du risque</h4>\n\n      <table>\n        <thead><tr><th><span>Suivi</span></th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><strong>A</strong></td><td>Pas de situation à risque ou faible niveau de risque → <span>suivi</span> par <span class=\"nc-green_bg\">sage-femme</span> ou <span class=\"nc-green_bg\">médecin</span> (généraliste, gynéco médical, gynéco-<span class=\"nc-green_bg\">obstétricien</span> au choix de la femme).</td></tr>\n          <tr><td><strong>A1</strong></td><td>Avis d’un gynécologue obstétricien et/ou d’un autre spécialiste <strong><span class=\"nc-orange_bg\">conseillé</span></strong>.</td></tr>\n          <tr><td><strong>A2</strong></td><td>Avis d’un gynécologue obstétricien <strong><span class=\"nc-yellow_bg nc-bold\">nécessaire</span></strong> (± avis d’un autre spécialiste).</td></tr>\n          <tr><td><strong>B</strong></td><td>Niveau de risque élevé → <span>suivi</span> régulier <strong>par un gynécologue obstétricien</strong>.</td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 29 — Risques professionnels et maternité</em></p></div>"},{"i":"274958d22ce2","n":23,"o":"23-5","u":"Prise en charge","t":"Savoir adapter le choix de la maternité","q":"Que retenir concernant adapter le choix de la maternité ?","a":"<div class=\"notion-course\"><p>Les futurs parents s’orientent vers les maternités <strong><span class=\"nc-green_bg\">selon leurs désirs</span></strong> (préférences, lieu d’habitation) et <strong><span class=\"nc-orange_bg\">selon le niveau de risque de la </span><span><span class=\"nc-orange_bg\">grossesse</span></span></strong> mis en évidence par le <span>suivi</span>.</p>\n\n      <p>👉 Le <span>lieu d’accouchement est constamment réévalué</span> lors des consultations de <span>suivi</span> prénatal.</p>\n\n      <h4><span>Classification</span> des maternités selon le plateau technique pédiatrique</h4>\n\n      <table>\n        <thead><tr><th>Type</th><th>%</th><th>Plateau technique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Type 1</strong></td>\n            <td><span>50 %</span></td>\n            <td>Très grande majorité — prise en charge des <strong><span class=\"nc-green_bg\">grossesses à bas risque</span></strong>, <em>pas d’<span class=\"nc-yellow_bg\">unité de néonatalogie</span></em>.</td>\n          </tr>\n          <tr>\n            <td><strong>Type 2a</strong></td>\n            <td><span>23 %</span></td>\n            <td><span class=\"nc-yellow_bg\">Unité de </span><strong><span class=\"nc-yellow_bg\">néonatalogie</span></strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Type 2b</strong></td>\n            <td><span>16 %</span></td>\n            <td><span class=\"nc-orange_bg\">Unité de </span><strong><span><span class=\"nc-orange_bg\">soins intensifs</span></span><span class=\"nc-orange_bg\"> de néonatalogie</span></strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Type 3</strong></td>\n            <td><span>12 %</span></td>\n            <td><span class=\"nc-red_bg\">Unité de </span><strong><span><span class=\"nc-red_bg\">réanimation</span></span><span class=\"nc-red_bg\"> néonatale</span></strong>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Autres lieux d’accouchement (faible pourcentage, faible niveau de risque)</h4>\n\n      <ul>\n        <li><strong>Espaces dits « physiologiques »</strong> (internes à une maternité)</li>\n        <li><strong>Maisons de naissance</strong> : lieu d’accueil sous la responsabilité exclusive des <span class=\"nc-green_bg\">sages-femmes</span>, pour des grossesses se présentant a priori comme normales</li>\n      </ul></div>"},{"i":"ce7d8bc67a40","n":23,"o":"23-6","u":"Prise en charge","t":"Déclaration de la grossesse","q":"Que retenir concernant déclaration de la grossesse ?","a":"<div class=\"notion-course\"><p>La <span>déclaration de grossesse</span> est une formalité administrative obligatoire qui permet la <span>prise en charge à 100 % par l’assurance maladie</span>.</p>\n\n      <h4>Modalités</h4>\n\n      <table>\n        <thead><tr><th>Item</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Support</strong></td>\n            <td><span class=\"nc-yellow_bg\">Formulaire réglementaire</span> (aujourd’hui <strong><span class=\"nc-red nc-bold\">possible en ligne</span></strong>).</td>\n          </tr>\n          <tr>\n            <td><strong>Quand ?</strong></td>\n            <td>Théoriquement avant <span>14 semaines de grossesse</span> · selon HAS : <span><span class=\"nc-pink nc-bold\">16 SA</span></span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-green_bg\">Médecin</span></strong></td>\n            <td>Indique la date de consultation, la <span>date de début de grossesse</span> ⭐, et certifie qu’il a prescrit les examens obligatoires.</td>\n          </tr>\n          <tr>\n            <td><strong>Gestante</strong></td>\n            <td>\n              Complète le formulaire et adresse :\n              <ul>\n                <li><span><span class=\"nc-green_bg\">2 exemplaires</span> à la <span class=\"nc-green nc-bold\">caisse d’allocations familiales</span></span></li>\n                <li><span>1 exemplaire à sa <span class=\"nc-green nc-bold\">caisse d’assurance maladie</span></span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Utilité</strong></td>\n            <td>Prise en charge des <strong>8 consultations prénatales</strong> à<span> 100 %</span> (examens obligatoires <span class=\"nc-pink nc-bold\">jusqu’au </span><span><span class=\"nc-pink nc-bold\">6</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\"> mois</span></span>) puis <span class=\"nc-green_bg\">couverture médicale à</span><span><span class=\"nc-green_bg\"> 100 %</span></span><span class=\"nc-green_bg\"> à partir de </span><span><span class=\"nc-green_bg\">24 SA</span></span>.</td>\n          </tr>\n        </tbody>\n      </table></div>"},{"i":"3ff839962d2a","n":23,"o":"23-7","u":"Prise en charge","t":"Examens biologiques","q":"Que retenir concernant examens biologiques ?","a":"<div class=\"notion-course\"><p>⭐⭐⭐⭐⭐ Item le plus interrogé en QCM EDN du <span>suivi</span> de <span>grossesse</span>. Connaître <strong>par cœur</strong> la cinétique des examens obligatoires <span>vs</span> proposés systématiquement <span>vs</span> proposés sur <span>facteur de risque</span>.</p>\n\n      <h4>Calendrier de <span>suivi</span> — vue d'ensemble</h4>\n\n      <div class=\"gn-cal\">\n        <div class=\"gn-cal-legend\">\n          <span class=\"gn-lg oblig\">Obligatoire</span>\n          <span class=\"gn-lg syst\">Proposé systématiquement</span>\n          <span class=\"gn-lg fdr\">Sur <span>facteur de risque</span></span>\n          <span class=\"gn-lg key\">★ item-clé QCM</span>\n        </div>\n        <ol class=\"gn-cal-track\">\n          <li class=\"gn-stop is-key\">\n            <span class=\"gn-sa\">&lt; 15 SA</span>\n            <div class=\"gn-stop-title\">1ᵉʳ examen prénatal</div>\n            <div class=\"gn-cats\">\n              <div class=\"gn-cat oblig\"><b>Obligatoire</b><ul><li>Groupe ABO + Rh complet + Kell</li><li><span class=\"nc-blue nc-bold\">RAI</span> · Syphilis (TPHA)</li><li>Rubéole · <span class=\"nc-purple_bg\">Toxoplasmose</span> · Ag HBs</li><li>Albuminurie (<span>BU</span>)</li></ul></div>\n              <div class=\"gn-cat syst\"><b>Proposé syst.</b><ul><li><span>VIH</span></li><li><span>Dépistage</span> cancer du col</li><li><span>Dépistage</span> combiné T21 (écho + <span class=\"nc-pink nc-bold\">β-hCG</span> + <span class=\"nc-pink nc-bold\">PAPP-A</span>)</li></ul></div>\n              <div class=\"gn-cat fdr\"><b>Sur FdR</b><ul><li><span>VHC</span> · GAJ · <span>NFS</span> · <span>TSH</span> · EPS Hb</li><li><span>ECBU</span> · PV si <span class=\"nc-red nc-bold\">pertes</span></li><li>Génotype Rh fœtal dès 11 SA (si mère Rh−)</li></ul></div>\n            </div>\n          </li>\n          <li class=\"gn-stop\">\n            <span class=\"gn-sa\">16–20 SA</span>\n            <div class=\"gn-stop-title\">4ᵉ mois</div>\n            <div class=\"gn-cats\">\n              <div class=\"gn-cat oblig\"><b>Obligatoire</b><ul><li><span class=\"nc-purple_bg\">Rubéole</span> (si négatif, <span class=\"nc-pink nc-bold\">jusqu'à 18 SA</span>)</li><li><span class=\"nc-purple_bg\">Toxoplasmose</span> (si négatif)</li><li>Albuminurie (<span>BU</span>)</li></ul></div>\n              <div class=\"gn-cat syst\"><b>Proposé syst.</b><ul><li>Marqueurs <span class=\"nc-yellow_bg nc-bold\">T21</span> (14–17 SA) si non fait au T1</li><li>Bilan bucco-dentaire</li><li>Prescription écho du 5ᵉ mois</li></ul></div>\n              <div class=\"gn-cat fdr\"><b>Sur FdR</b><ul><li><span>ECBU</span> (si ATCD uro ou <span>BU</span>+)</li></ul></div>\n            </div>\n          </li>\n          <li class=\"gn-stop\">\n            <span class=\"gn-sa\">20–24 SA</span>\n            <div class=\"gn-stop-title\">5ᵉ mois</div>\n            <div class=\"gn-cats\">\n              <div class=\"gn-cat oblig\"><b>Obligatoire</b><ul><li>Rubéole · <span class=\"nc-purple_bg\">Toxoplasmose</span> (si négatif)</li><li>Albuminurie (<span>BU</span>)</li></ul></div>\n              <div class=\"gn-cat syst\"><b>Proposé syst.</b><ul><li><span>Échographie</span> morphologique de 22 SA</li></ul></div>\n              <div class=\"gn-cat fdr\"><b>Sur FdR</b><ul><li><span>ECBU</span> (si ATCD uro ou <span>BU</span>+)</li></ul></div>\n            </div>\n          </li>\n          <li class=\"gn-stop is-key\">\n            <span class=\"gn-sa\">24–28 SA</span>\n            <div class=\"gn-stop-title\">6ᵉ mois</div>\n            <div class=\"gn-cats\">\n              <div class=\"gn-cat oblig\"><b>Obligatoire</b><ul><li><strong><span><span class=\"nc-blue_bg\">NFS</span></span> ★</strong> (<span>dépistage</span> <span class=\"nc-red nc-bold\">anémie</span>)</li><li>Toxoplasmose · Albuminurie (<span>BU</span>)</li><li>RAI si Rh− ou Rh+ à ATCD transfu/obstétr.</li></ul></div>\n              <div class=\"gn-cat none\"><b>Proposé syst.</b><ul><li>—</li></ul></div>\n              <div class=\"gn-cat fdr\"><b>Sur FdR</b><ul><li><strong>HGPO <span>75 g</span> ★</strong> si FdR (GAJ T1 <span class=\"nc-pink nc-bold\">&lt;</span><span><span class=\"nc-pink nc-bold\"> 0,92 g/L</span></span> ou non faite)</li><li><span>ECBU</span></li></ul></div>\n            </div>\n          </li>\n          <li class=\"gn-stop\">\n            <span class=\"gn-sa\">28–32 SA</span>\n            <div class=\"gn-stop-title\">7ᵉ mois</div>\n            <div class=\"gn-cats\">\n              <div class=\"gn-cat oblig\"><b>Obligatoire</b><ul><li>Toxoplasmose · Albuminurie (<span>BU</span>)</li></ul></div>\n              <div class=\"gn-cat syst\"><b>Proposé syst.</b><ul><li>RAI (si Rh− / Rh+ à ATCD)</li><li>Vitamine D 100 <span>000 UI</span> dose unique</li></ul></div>\n              <div class=\"gn-cat fdr\"><b>Sur FdR</b><ul><li><span>ECBU</span> (si ATCD uro ou <span>BU</span>+)</li></ul></div>\n            </div>\n          </li>\n          <li class=\"gn-stop is-key\">\n            <span class=\"gn-sa\">32–37 SA</span>\n            <div class=\"gn-stop-title\">8ᵉ mois</div>\n            <div class=\"gn-cats\">\n              <div class=\"gn-cat oblig\"><b>Obligatoire</b><ul><li>Toxoplasmose · Albuminurie (<span>BU</span>)</li><li><span class=\"nc-blue_bg\">RAI</span> (sauf si Rhophylac® déjà injecté)</li></ul></div>\n              <div class=\"gn-cat syst\"><b>Proposé syst.</b><ul><li><strong>PV ★</strong> — <span>dépistage</span> SGB (<span class=\"nc-pink nc-bold\">34–38 SA</span>)</li><li><span>Échographie</span> de croissance de 32 SA</li><li>Discuter du <span class=\"nc-green_bg\">congé maternité</span></li></ul></div>\n              <div class=\"gn-cat fdr\"><b>Sur FdR</b><ul><li><span>ECBU</span> (si ATCD uro ou <span>BU</span>+)</li></ul></div>\n            </div>\n          </li>\n          <li class=\"gn-stop\">\n            <span class=\"gn-sa\">37–42 SA</span>\n            <div class=\"gn-stop-title\">9ᵉ mois</div>\n            <div class=\"gn-cats\">\n              <div class=\"gn-cat oblig\"><b>Obligatoire</b><ul><li>Toxoplasmose · Albuminurie (<span>BU</span>)</li><li><span class=\"nc-blue_bg\">RAI</span> (sauf si Rhophylac®)</li></ul></div>\n              <div class=\"gn-cat syst\"><b>Proposé syst.</b><ul><li><span>BU</span> · <span class=\"nc-pink_bg\">Bilan pré-anesthésie</span></li></ul></div>\n              <div class=\"gn-cat fdr\"><b>Sur FdR</b><ul><li><span>ECBU</span> (si ATCD uro ou <span>BU</span>+)</li></ul></div>\n            </div>\n          </li>\n        </ol>\n      </div>\n\n      <h4>Synthèse de la <span>surveillance</span> <span>biologique</span></h4>\n\n      <table>\n        <thead>\n          <tr><th>Examen</th><th>Obligatoire</th><th>Proposé systématiquement</th><th>Proposé sur FR</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1<sup>er</sup> examen<br>(<span>&lt; 15 SA</span>)</strong></td>\n            <td>\n              <ul>\n                <li><span>Groupe ABO + phénotype Rh complet + Kell</span></li>\n                <li><span>RAI</span></li>\n                <li><span>Syphilis (TPHA en 1<sup>er</sup>)</span>, <span>Rubéole</span>, <span>Ag HBs</span>, <span><span class=\"nc-purple_bg\">Toxoplasmose</span></span></li>\n                <li><span><span class=\"nc-green_bg\">Albumine urinaire (BU)</span></span></li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span>VIH</span></li>\n                <li><span>Dépistage</span> <strong>cancer du col</strong></li>\n                <li><span>Dépistage</span> combiné T21 (écho + <span><span class=\"nc-pink nc-bold\">β-hCG</span></span> + <span><span class=\"nc-pink nc-bold\">PAPP-A</span></span>)</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span>VHC</span>, <span>GAJ</span>, <span>NFS</span>, <span>TSH</span>, Électrophorèse Hb</li>\n                <li><span>ECBU</span>, <span>PV</span> si <span class=\"nc-red nc-bold\">pertes</span></li>\n                <li><strong>Génotype Rh fœtal</strong> dès <span><span class=\"nc-pink nc-bold\">11 SA</span></span> (si mère Rh−) → si <span>fœtus Rh−, pas d’Ig anti-D à 28 SA</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>4<sup>e</sup> mois<br>(<span>16-<span class=\"nc-pink\">20 SA</span></span>)</strong></td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-purple_bg\">Rubéole</span></span> (si négatif, <strong><span class=\"nc-pink nc-bold\">jusqu’à 18 SA</span></strong>)</li>\n                <li><span><span class=\"nc-purple_bg\">Toxoplasmose</span></span> (si négatif)</li>\n                <li><span><span class=\"nc-green_bg\">Albumine urinaire (BU)</span></span></li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span class=\"nc-yellow_bg\">Marqueurs sériques</span> <strong><span class=\"nc-yellow_bg nc-bold\">T21</span></strong> (<span>14-17 SA</span>) si non fait au T1 (<span>α-FP</span>, <span><span class=\"nc-pink nc-bold\">β-hCG</span></span> ou <span class=\"nc-pink nc-bold\">hCG totales</span>, ± <span>Œstradiol non conjugué</span>)</li>\n                <li>Bilan bucco-dentaire (remboursé CPAM)</li>\n                <li>Prescription de l’écho du 5<sup>e</sup> mois</li>\n              </ul>\n            </td>\n            <td><span><span class=\"nc-blue_bg\">ECBU</span></span> (si ATCD uro ou <span>BU</span>+)</td>\n          </tr>\n          <tr>\n            <td><strong>5<sup>e</sup> mois<br>(20-24 SA)</strong></td>\n            <td>\n              <ul>\n                <li>Rubéole (si négatif)</li>\n                <li><span class=\"nc-purple_bg\">Toxoplasmose</span> (si négatif)</li>\n                <li><span><span class=\"nc-green_bg\">Albumine</span></span><span class=\"nc-green_bg\"> urinaire (</span><span><span class=\"nc-green_bg\">BU</span></span><span class=\"nc-green_bg\">)</span></li>\n              </ul>\n            </td>\n            <td><span>Échographie</span> morphologique de 22 SA</td>\n            <td><span><span class=\"nc-blue_bg\">ECBU</span></span> (si ATCD uro ou <span>BU</span>+)</td>\n          </tr>\n          <tr>\n            <td><strong>6<sup>e</sup> mois<br>(<span>24-28 SA</span>)</strong></td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-blue_bg\">NFS</span></span> ⭐ (<span>dépistage</span> <span class=\"nc-red nc-bold\">anémie</span>)</li>\n                <li><span><span class=\"nc-purple_bg\">Toxoplasmose</span></span> (si négatif)</li>\n                <li><span><span class=\"nc-green_bg\">Albumine urinaire (BU)</span></span></li>\n                <li><span>RAI</span> obligatoire dans 2 situations :\n                  <ul>\n                    <li><strong><span><span class=\"nc-red nc-bold\">RhD</span></span><span class=\"nc-red nc-bold\">−</span></strong> (sauf si génotypage Rh fait et fœtus négatif)</li>\n                    <li><strong><span><span class=\"nc-red nc-bold\">RhD</span></span><span class=\"nc-red nc-bold\">+ avec ATCD transfusionnels et/ou obstétricaux</span></strong></li>\n                  </ul>\n                </li>\n              </ul>\n            </td>\n            <td>—</td>\n            <td>\n              <ul>\n                <li><span>ECBU</span> si ATCD uro ou <span>BU</span>+</li>\n                <li><span><span class=\"nc-blue_bg\">HGPO 75 g</span></span> ⭐ si FdR et <span>GAJ <span class=\"nc-pink nc-bold\">&lt; 0,92 g/L</span></span> (<span>5,1 mmol/L</span>) au T1 (ou GAJ non réalisée)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>7<sup>e</sup> mois<br>(<span>28-32 SA</span>)</strong></td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-purple_bg\">Toxoplasmose</span></span> (si négatif)</li>\n                <li><span><span class=\"nc-green_bg\">Albumine urinaire (BU)</span></span></li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span>RAI</span> si Rh− ou Rh+ avec ATCD transfu / obstétricaux</li>\n                <li><span class=\"nc-pink_bg\">Supplémentation </span><span><span class=\"nc-pink_bg\">Vitamine D</span> 100 000 UI</span> dose unique (ou 8<sup>e</sup> mois)</li>\n              </ul>\n            </td>\n            <td><span><span class=\"nc-blue_bg\">ECBU</span></span> (si ATCD uro ou <span>BU</span>+)</td>\n          </tr>\n          <tr>\n            <td><strong>8<sup>e</sup> mois<br>(<span>32-37 SA</span>)</strong></td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-purple_bg\">Toxoplasmose</span></span> (si négatif)</li>\n                <li><span><span class=\"nc-blue_bg\">RAI</span></span> (sauf si injection de <span>Rhophylac®</span>)</li>\n                <li><span><span class=\"nc-green_bg\">Albumine urinaire (BU)</span></span></li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span>BU</span></li>\n                <li><span>PV</span> ⭐ (<span>dépistage</span> SGB à <span><span class=\"nc-pink nc-bold\">34-38 SA</span></span>) → si <strong>SGB+</strong> : <span>antibioprophylaxie amoxicilline IV</span> dès le début du travail</li>\n                <li><span>Échographie</span> de croissance de 32 SA</li>\n                <li>Discuter du <span class=\"nc-green_bg\">congé maternité</span></li>\n              </ul>\n            </td>\n            <td><span><span class=\"nc-blue_bg\">ECBU</span></span> (si ATCD uro ou <span>BU</span>+)</td>\n          </tr>\n          <tr>\n            <td><strong>9<sup>e</sup> mois<br>(<span>37-42 SA</span>)</strong></td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-purple_bg\">Toxoplasmose</span></span> (si négatif)</li>\n                <li><span><span class=\"nc-blue_bg\">RAI</span></span> (sauf si <span>Rhophylac®</span>)</li>\n                <li><span><span class=\"nc-green_bg\">Albumine urinaire (BU)</span></span></li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span>BU</span></li>\n                <li><span class=\"nc-pink_bg\">Bilan pré-anesthésie</span></li>\n              </ul>\n            </td>\n            <td><span><span class=\"nc-blue_bg\">ECBU</span></span> (si ATCD uro ou <span>BU</span>+)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>❌ Examens NON recommandés en systématique</h4>\n\n      <ul>\n        <li><span>Sérologie</span> <span>CMV</span></li>\n        <li><span>Bilan lipidique</span></li>\n        <li><span>VS</span></li>\n        <li><span>Phosphatases alcalines</span></li>\n        <li>Protéine S</li>\n      </ul>\n\n      <h4>Focus — détails des examens obligatoires du 1<sup>er</sup> trimestre</h4>\n\n      <table>\n        <thead><tr><th>Examen</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span>Groupe sanguin</span></td>\n            <td>Obligatoire en cas de 1<sup>ère</sup> <span>grossesse</span> : <span>ABO + phénotype Rh complet + Kell</span>, si pas de carte complète (2 déterminations).</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-blue_bg\">RAI</span></span></td>\n            <td>Hors AC dirigés contre A et B. Si positive → <strong>identification et titrage des AC obligatoires</strong>.</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-purple_bg\">Syphilis</span></span></td>\n            <td><span>TPHA</span> (ELISA/EIA/CMIA) → si positif, confirmé par <span>VDRL</span> quantitatif.</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-purple_bg\">Rubéole</span></span></td>\n            <td>Répétée <span><span class=\"nc-pink nc-bold\">jusqu’à 18 SA</span></span> si négative.</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-purple_bg\">Toxoplasmose</span></span></td>\n            <td>Répétée <strong>1×/mois</strong> dès le 2<sup>e</sup> examen prénatal si immunité non <span>acquise</span>.</td>\n          </tr>\n          <tr>\n            <td><span>Ag HBs</span></td>\n            <td>Obligatoire dès le 1<sup>er</sup> trimestre.</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-green_bg\">Albumine urinaire (BU)</span></span></td>\n            <td><strong>1×/mois</strong> pendant toute la <span>grossesse</span>. (<span class=\"nc-green_bg\">Glycosurie</span> encore obligatoire mais sans intérêt.)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span>NFS</span> du 6<sup>e</sup> mois — limites + recommandations HAS</h4>\n\n      <ul>\n        <li><span>NFS</span> donne seulement <span>Hb</span> et <span>Ht</span> ; <strong>ne précise pas les réserves</strong> (pas de <span>ferritine</span>).</li>\n        <li><span>Dépistage</span> tardif : risque périnatal existe déjà pour des carences plus précoces.</li>\n        <li>👉 <strong>HAS recommande</strong> : doser <span>ferritine + Hb à la déclaration</span> et conseils alimentaires à l’entretien T1.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 28 — <span>Infection urinaire</span> lors de la <span>grossesse</span> · 162 — IST · 169 — <span>VIH</span> · 255 — <span>Diabète gestationnel</span></em></p><div class=\"callout callout-info\"><b>Actualisation et précisions</b><ul><li><b>Actualisation HAS 2025–2026 :</b> le dépistage du CMV au premier trimestre est désormais recommandé ; il ne faut plus apprendre « aucun dépistage systématique ». Proposition après information, sérologie précoce puis, si négative, contrôle toutes les quatre semaines jusqu’à une dernière sérologie entre 13+0 et 14+0 SA. Voir l’objectif 27-12.</li></ul></div></div>"},{"i":"d3df5498d131","n":23,"o":"23-8","u":"Prise en charge","t":"Dépistage de la T21","q":"Que retenir concernant dépistage de la T21 ?","a":"<div class=\"notion-course\"><p>Le <span>dépistage</span> de la trisomie 21 est <strong>proposé systématiquement</strong> à toutes les femmes enceintes (non obligatoire). Le but est d’estimer un risque combiné — clinique + échographique + <span>biologique</span>.</p>\n\n      <h4><span>Dépistage</span> combiné du 1<sup>er</sup> trimestre (de référence)</h4>\n\n      <table>\n        <thead><tr><th>Composant</th><th>Caractéristique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span><span class=\"nc-blue nc-bold\">Échographie</span></span> de datation</strong></td>\n            <td>\n              <ul>\n                <li>Réalisée entre <span>11 SA et 13 SA + 6 j</span></li>\n                <li>Mesure de la <strong><span class=\"nc-red_bg\">clarté nucale</span></strong> prise en compte dans l’estimation du risque T21</li>\n                <li><span>Normale &lt; 3 mm</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-yellow_bg\">Marqueurs sériques</span> T1</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"nc-pink nc-bold\">PAPP-A</span></strong></li>\n                <li><strong>β-hCG libre</strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span>Dépistage</span> du 2<sup>e</sup> trimestre (en rattrapage)</h4>\n\n      <p>Si le <span>dépistage</span> combiné T1 n’a pas été réalisé, on propose les <strong><span class=\"nc-yellow_bg\">marqueurs sériques</span> entre 14 et 17 SA</strong> :</p>\n\n      <ul>\n        <li><strong><span class=\"nc-pink nc-bold\">α-fœtoprotéine</span></strong></li>\n        <li><strong>β-hCG</strong> ou hCG totales</li>\n        <li>± <strong>Œstradiol non conjugué</strong></li>\n      </ul>\n\n      <h4>Seuil de risque et conduite</h4>\n\n      <table>\n        <thead><tr><th>Résultat du <span>dépistage</span> combiné</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Risque faible</strong> : seuil <span>&lt; 1/1 000</span></td>\n            <td><span>Surveillance</span> simple, pas de geste complémentaire.</td>\n          </tr>\n          <tr>\n            <td><strong>Risque intermédiaire</strong> : <span>1/51</span> à <span>1/1 000</span></td>\n            <td>Proposition d’un <strong>DPNI</strong> (<span>dépistage</span> prénatal non invasif sur ADN fœtal libre — remboursé depuis 2018).</td>\n          </tr>\n          <tr>\n            <td><span>Risque élevé</span> : seuil <span>≥ 1/50</span> (ou seuil concours <span>≥ 1/250</span>)</td>\n            <td>Proposition d’un <strong>caryotype fœtal</strong> par geste invasif (<span>biopsie</span> de trophoblaste ou amniocentèse) — décision partagée (cf obj-8).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      \n\n      <h4>Information à délivrer à la patiente</h4>\n\n      <ul>\n        <li>Le <span>dépistage</span> est <strong>non obligatoire</strong> et <strong>non remboursé à<span> 100 %</span></strong> si non couplé à l’<span><span class=\"nc-blue nc-bold\">échographie</span></span> obligatoire.</li>\n        <li>Il calcule un <em>risque</em>, pas un diagnostic — un résultat positif ne signifie pas que l’enfant est porteur de T21.</li>\n        <li>En cas de risque élevé → consultation spécialisée pour discuter d’un <strong>diagnostic prénatal</strong> (cf obj suivant).</li>\n      </ul></div>"},{"i":"feecb20d84c1","n":23,"o":"23-9","u":"Prise en charge","t":"Conduite à tenir en cas de dépistage de T21 positif","q":"Que retenir concernant conduite à tenir en cas de dépistage de T21 positif ?","a":"<div class=\"notion-course\"><ul><li>Un résultat de dépistage de trisomie 21 exprime une probabilité : ce n’est pas un diagnostic. Expliquer les options et respecter le choix de la femme, y compris le refus de dépistage ou de prélèvement.</li><li>Après dépistage combiné : risque inférieur à 1/1 000, suivi habituel ; entre 1/1 000 et 1/51, proposer l’analyse de l’ADN libre circulant (DPNI) ; risque ≥ 1/50, proposer un prélèvement diagnostique, avec possibilité de DPNI après information.</li><li>Une <span class=\"nc-red_bg\">clarté nucale</span> ≥ 3,5 mm ou une anomalie échographique justifie un avis spécialisé/CPDPN et la discussion d’un prélèvement diagnostique, indépendamment du risque sérique.</li><li>Un DPNI positif doit être confirmé par un prélèvement invasif et une analyse cytogénétique avant toute décision irréversible. Un DPNI non interprétable ne doit pas être assimilé à un résultat négatif.</li><li>Biopsie de trophoblaste ou amniocentèse selon le terme et la question : information sur les limites, le risque du geste et consentement. Une éventuelle IMG relève d’un parcours spécifique ; elle n’est jamais automatique.</li></ul></div>"},{"i":"07ee36777be6","n":23,"o":"23-10","u":"Prise en charge","t":"Savoir surveiller cliniquement une femme enceinte sans complication","q":"Que retenir concernant surveiller cliniquement une femme enceinte sans complication ?","a":"<div class=\"notion-course\"><p>La <span>grossesse</span> normale est suivie par <strong>8 consultations prénatales</strong> prises en charge à<span> 100 %</span> : 2 consultations recommandées lors des 3 premiers mois (&lt; 15 SA), puis <strong>1×/mois jusqu’à la naissance</strong>.</p>\n\n      <h4>Acteurs du <span>suivi</span> (selon le terme)</h4>\n\n      <ul>\n        <li><strong><span class=\"nc-pink nc-bold\">Jusqu’au 6</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\"> mois</span></strong> : <span class=\"nc-green_bg\">médecin généraliste</span>, <span class=\"nc-green_bg\">sage-femme</span>, <span class=\"nc-green_bg\">obstétricien</span></li>\n        <li><strong><span class=\"nc-pink nc-bold\">Aux 7</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\">, 8</span><sup><span class=\"nc-pink nc-bold\">e</span></sup>, <span class=\"nc-pink nc-bold\">9</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\"> mois</span></strong> : équipe qui assurera la naissance (<span class=\"nc-blue_bg\">sage-femme ou obstétricien</span>) de préférence</li>\n      </ul>\n\n      <h4>Trame de chaque consultation au 2<sup>nd</sup> trimestre</h4>\n\n      <table>\n        <thead><tr><th>Étape</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Interrogatoire</strong></td>\n            <td>Recherche : hémorragies, signes fonctionnels urinaires, leucorrhées prurigineuses ou malodorantes, <span class=\"nc-green_bg\">contractions utérines</span> (physiologiques = <em>Braxton-Hicks</em>).</td>\n          </tr>\n          <tr>\n            <td><strong>Examen clinique obstétrical</strong></td>\n            <td>\n              <ul>\n                <li>PA, poids</li>\n                <li><strong>HU</strong> à partir du <strong>4<sup>e</sup> mois</strong></li>\n                <li>BDC (Bruits du cœur fœtal)</li>\n                <li>Demander à la femme si elle ressent les <strong>MAF</strong> (perçus <span class=\"nc-pink nc-bold\">autour de la </span><strong><span class=\"nc-pink nc-bold\">fin du 4</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\"> mois</span></strong>, plus tôt chez la multipare)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Toucher vaginal</strong></td>\n            <td><strong>Non systématique</strong> ❌ — uniquement si signes cliniques (contractions). Intérêt très limité pour dépister un <span class=\"nc-red nc-bold\">accouchement prématuré</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Hauteur utérine — repères normaux</h4>\n\n      <table>\n        <thead><tr><th>Période</th><th>Formule</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>HU normale entre 20-32 SA</strong></td>\n            <td>HU (cm) = <strong><span class=\"nc-pink nc-bold\">nombre de SA − 4</span></strong> (ex.<span> 24 cm</span> à 28 SA,<span> 28 cm</span> à 32 SA).</td>\n          </tr>\n          <tr>\n            <td><strong>HU normale après 32 SA</strong></td>\n            <td>HU <strong>augmente de <span>1 cm</span> toutes les 2 SA</strong> (<span>29 cm</span> à 34 SA,<span> 30 cm</span> à 36 SA…).</td>\n          </tr>\n          <tr>\n            <td><strong>Méthode alternative</strong></td>\n            <td>\n              <ul>\n                <li>Entre <span><span class=\"nc-pink nc-bold\">4-7 mois</span></span> : HU = nombre de mois × 4</li>\n                <li><span class=\"nc-pink nc-bold\">8-9</span><sup><span class=\"nc-pink nc-bold\">e</span></sup> mois : HU = nombre de mois × 4 − 2</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>CAT si anormale</strong></td>\n            <td>HU inférieure → <strong><span class=\"nc-blue nc-bold\">contrôle échographique</span></strong>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Recommandations hygiéno-diététiques (rappel à chaque consultation)</h4>\n\n      <table>\n        <thead><tr><th>Domaine</th><th>Conseil</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Activité physique</strong></td><td>Possible sauf <em><span class=\"nc-red nc-bold\">sports violents ou très fatigants</span></em>.</td></tr>\n          <tr><td><strong>Activité professionnelle</strong></td><td>Plupart des activités <strong>ne sont pas un FdR d’<span class=\"nc-red nc-bold\">accouchement prématuré</span></strong>.</td></tr>\n          <tr><td><strong>Voyages</strong></td><td>Autorisés si <span>grossesse</span> normale. <strong>Ceinture de sécurité obligatoire</strong> quel que soit le terme.</td></tr>\n          <tr><td><strong>Toxiques</strong></td><td>Arrêt <span><span class=\"nc-orange_bg\">alcool</span> (<span class=\"nc-red nc-bold\">tolérance zéro</span>)</span>, <span><span class=\"nc-orange_bg\">tabac</span></span>, <span>cannabis</span> (1 joint = 7 cigarettes), <span><span class=\"nc-pink_bg\">opiacés</span></span>.</td></tr>\n          <tr><td><strong>Vaccinations</strong></td><td>Anti-grippale à tout <span>stade</span> · <strong>Anti-COVID-19 dès le 2<sup>nd</sup> trim</strong>.</td></tr>\n          <tr><td><strong>Prévention infectieuse</strong></td><td>Règles toxoplasmose (si séronégative) + listériose · prévention <span>CMV</span> (éviter sécrétions d’enfants en bas-âge).</td></tr>\n          <tr><td><strong>Supplémentations</strong></td><td>Voir bloc dédié ci-dessous ⬇</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Supplémentations systématiques — posologies à connaître ⭐</h4>\n\n      <table>\n        <thead><tr><th>Molécule</th><th>Posologie</th><th>Timing</th><th>Pourquoi ?</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"nc-pink_bg\">Acide folique</span> (B9)</strong></td>\n            <td><span>0,4 mg/j</span> per os</td>\n            <td>Dès <span><span class=\"nc-pink nc-bold\">≥ 1 mois</span></span> avant la conception, jusqu’à <span>10-12 SA</span></td>\n            <td>Prévention des <strong>anomalies de fermeture du tube neural (AFTN)</strong> ⭐⭐⭐⭐⭐</td>\n          </tr>\n          <tr>\n            <td><strong>Vitamine D</strong></td>\n            <td><span>100 000 UI</span> dose unique per os</td>\n            <td><span class=\"nc-pink nc-bold\">Début du </span><span><span class=\"nc-pink nc-bold\">7</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\"> ou 8</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\"> mois</span></span>, en toute saison</td>\n            <td><span class=\"nc-green_bg\">Prévention des </span><strong><span class=\"nc-green_bg\">hypocalcémies néonatales</span></strong> (état de carence en fin de <span>grossesse</span> en France)</td>\n          </tr>\n          <tr>\n            <td><strong>Fer</strong></td>\n            <td>Si carence martiale (<span>ferritine &lt; 12 μg/L</span>) ou anémie</td>\n            <td>Selon bilan</td>\n            <td>Pas systématique — guidé par <span>NFS</span> du 6<sup>e</sup> mois (cf obj-6, obj-14)</td>\n          </tr>\n          <tr>\n            <td><strong>B9 + B12</strong></td>\n            <td>À doser si ATCD <span>chirurgie</span> bariatrique, végétariennes/végétaliennes</td>\n            <td>Dès la déclaration</td>\n            <td>Carences à dépister activement</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"nc-yellow_bg\">Effet Poseiro</span> — décubitus latéral gauche au T3 📌</h4>\n\n      <p><span class=\"nc-yellow_bg\">En décubitus dorsal</span> au 3<sup>e</sup> trimestre, l’utérus gravide comprime la <strong>veine cave inférieure</strong> :</p>\n\n      <ul>\n        <li>↓ retour veineux au cœur droit</li>\n        <li><span>Ralentissement du rythme cardiaque fœtal</span></li>\n        <li><span><span class=\"nc-red nc-bold\">Malaise maternel</span></span> (hypoTA)</li>\n      </ul>\n\n      <p>👉 <strong>Préférer le décubitus latéral gauche</strong> à partir du T3 (auscultation BDC, repos, accouchement).</p>\n\n      <h4><span>Dépistage</span> du <span>diabète gestationnel</span> — <span class=\"nc-blue_bg\">HGPO </span><span><span class=\"nc-blue_bg\">75 g</span></span></h4>\n\n      <ul>\n        <li><strong>Indication</strong> : <span>GAJ <span class=\"nc-pink nc-bold\">&lt; 0,92 g/L</span> (5,1 mmol/L)</span> au T1 chez femme avec <strong>FdR</strong> (ou GAJ non réalisée)</li>\n        <li><strong>Quand ?</strong> Au <span>6<sup>e</sup> mois (24-28 SA)</span></li>\n        <li><strong>Détails</strong> : voir <em>obj-6 — Examens biologiques</em> et item lié 255</li>\n      </ul>\n\n      <h4>Consultation du 9<sup>e</sup> mois (37-42 SA) — particularités</h4>\n\n      <ul>\n        <li>Examen clinique : HU, BDC, poids, PA, <strong>toucher vaginal avec pelvimétrie clinique</strong></li>\n        <li>Explication du moment où venir à la maternité, convocation le jour du terme présumé</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 27 — Prévention risques fœtaux · 28 — <span>Infection urinaire</span> lors de la <span>grossesse</span> · 255 — <span>Diabète gestationnel</span></em></p></div>"},{"i":"8e2cc9181086","n":23,"o":"23-11","u":"Suivi et/ou pronostic","t":"Connaître les professionnels de santé impliqués dans le suivi de la femme enceinte","q":"Que retenir concernant les professionnels de santé impliqués dans le suivi de la femme enceinte ?","a":"<div class=\"notion-course\"><p>La plupart des grossesses étant physiologiques ou normales, leur prise en charge peut être <span>assurée indifféremment par plusieurs professionnels</span>.</p>\n\n      <h4>Acteurs selon le terme</h4>\n\n      <table>\n        <thead><tr><th>Période</th><th>Professionnels</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"nc-pink nc-bold\">Jusqu’au </span><span><span class=\"nc-pink nc-bold\">6</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\"> mois</span></span></strong></td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-green_bg\">Médecin généraliste</span></span></li>\n                <li><span><span class=\"nc-green_bg\">Sage-femme</span></span></li>\n                <li><span><span class=\"nc-green_bg\">Obstétricien</span></span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-pink nc-bold\">Aux </span><span><span class=\"nc-pink nc-bold\">7</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\">, 8</span><sup><span class=\"nc-pink nc-bold\">e</span></sup>, <span class=\"nc-pink nc-bold\">9</span><sup><span class=\"nc-pink nc-bold\">e</span></sup><span class=\"nc-pink nc-bold\"> mois</span></span></strong></td>\n            <td>Équipe qui assurera la naissance de préférence (<span><span class=\"nc-blue_bg\">sage-femme ou obstétricien</span></span>).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Acteurs selon le niveau de risque</h4>\n\n      <table>\n        <thead><tr><th><span>Suivi</span></th><th>Professionnel</th></tr></thead>\n        <tbody>\n          <tr><td><strong>A</strong></td><td><span><span class=\"nc-green_bg\">Sage-femme</span></span> ou <span class=\"nc-green_bg\">médecin</span> (généraliste, gynéco médical, gynéco-<span class=\"nc-green_bg\">obstétricien</span>) au choix de la femme.</td></tr>\n          <tr><td><strong>A1</strong></td><td>Avis d’un <span>gynéco-obstétricien</span> et/ou autre spécialiste <em><span class=\"nc-orange_bg\">conseillé</span></em>.</td></tr>\n          <tr><td><strong>A2</strong></td><td>Avis d’un <span>gynéco-obstétricien <span class=\"nc-yellow_bg nc-bold\">nécessaire</span></span> (± autre spécialiste).</td></tr>\n          <tr><td><strong>B</strong></td><td><span>Suivi</span> régulier par un <span>gynécologue obstétricien</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Acteurs spécifiques selon le moment du parcours</h4>\n\n      <ul>\n        <li><strong><span>EPP</span> du <span>4<sup>e</sup> mois</span></strong> : <span><span class=\"nc-green_bg\">sage-femme</span> +++</span>, ou autre professionnel de la périnatalité, plus rarement <span class=\"nc-green_bg\">médecin</span> formé. Durée <span>45 min</span>.</li>\n        <li><strong>Bilan <span class=\"nc-yellow_bg\">prénatal</span> de prévention</strong> (alimentation, <span>tabac</span>, <span><span class=\"nc-orange_bg\">alcool</span></span>) avant <span>24 SA</span> : <span><span class=\"nc-green_bg\">sage-femme</span> libérale ou de PMI</span>.</li>\n        <li><strong>Bilan bucco-dentaire</strong> au <span>4<sup>e</sup> mois</span> : remboursé à<span> 100 %</span> par la CPAM.</li>\n        <li><strong>Échographies</strong> : opérateurs en imagerie obstétricale (gynéco-obstétriciens, échographistes, <span><span class=\"nc-green_bg\">sages-femmes</span> échographistes</span>).</li>\n        <li><strong>Anesthésiste</strong> : consultation à conseiller au <span>8<sup>e</sup> mois</span>.</li>\n        <li><strong>Examen <span class=\"nc-yellow_bg\">postnatal</span></strong> (<span>6-8 semaines</span> post-accouchement) : <span class=\"nc-green_bg\">médecin</span> ou <span><span class=\"nc-green_bg\">sage-femme</span></span> si <span>grossesse</span> normale et accouchement eutocique.</li>\n      </ul>\n\n      <h4>Préparation à la naissance et à la parentalité</h4>\n\n      <ul>\n        <li><span><span class=\"nc-pink nc-bold\">8 séances</span></span> au total — la 1<sup>ère</sup> étant l’<span>EPP</span> du 4<sup>e</sup> mois.</li>\n        <li>Réalisées en individuel ou en couple.</li>\n        <li>Possibles avant ou après l’accouchement.</li>\n      </ul></div>"},{"i":"a4f0dd9f677e","n":23,"o":"23-12","u":"Prise en charge","t":"Echographies obstétricales","q":"Que retenir concernant echographies obstétricales ?","a":"<div class=\"notion-course\"><p>Les <strong>3 échographies de la <span>grossesse</span></strong> ne sont pas obligatoires mais sont <strong>remboursées à<span> 100 %</span></strong>.</p>\n\n      <div class=\"gn-echo\" role=\"img\" aria-label=\"Frise des 3 échographies obstétricales sur l&#x27;axe de la grossesse : échographie de datation au 1er trimestre entre 11 et 13 SA + 6 jours, échographie morphologique au 2e trimestre à 22 SA, échographie de croissance au 3e trimestre à 32 SA.\">\n        <div class=\"gn-echo-step\">\n          <span class=\"gn-echo-sa\">11 → 13 SA+6 · T1</span>\n          <strong>1 · Datation</strong>\n          <ul>\n            <li>Localisation + vitalité</li>\n            <li>Terme par <span class=\"nc-blue_bg\">LCC</span> (précision 3–5 j)</li>\n            <li>Grossesses multiples + chorionicité ★</li>\n            <li><span class=\"nc-red_bg\">Clarté nucale</span> (&lt;<span> 3 mm</span>) → risque T21</li>\n          </ul>\n        </div>\n        <div class=\"gn-echo-step\">\n          <span class=\"gn-echo-sa\">22 SA · T2</span>\n          <strong>2 · Morphologique</strong>\n          <ul>\n            <li><span><span class=\"nc-red nc-bold\">Dépistage</span></span><span class=\"nc-red nc-bold\"> des malformations ++</span></li>\n            <li>Biométrie (BIP, PA, LF)</li>\n            <li><span class=\"nc-green nc-bold\">Liquide amniotique</span></li>\n            <li>Localisation <span class=\"nc-yellow_bg\">placenta</span> + cordon</li>\n          </ul>\n        </div>\n        <div class=\"gn-echo-step\">\n          <span class=\"gn-echo-sa\">32 SA · T3</span>\n          <strong>3 · Croissance</strong>\n          <ul>\n            <li>Vitalité (Manning, Doppler ombilical)</li>\n            <li>Biométrie → RCIU / macrosomie</li>\n            <li>Localisation placentaire + liquide</li>\n            <li>Type de présentation ★</li>\n          </ul>\n        </div>\n      </div>\n\n      <table>\n        <thead>\n          <tr><th><span>Échographie</span></th><th>Quand ?</th><th>Objectifs</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1 — <span><span class=\"nc-blue nc-bold\">Échographie</span></span> de datation<br>(1<sup>er</sup> trimestre)</strong></td>\n            <td><span>11 SA</span> à <span>13 SA + 6 j</span></td>\n            <td>\n              <ul>\n                <li>Confirme la <strong>localisation</strong> et la <strong><span class=\"nc-green_bg\">vitalité fœtale</span></strong></li>\n                <li><span class=\"nc-yellow_bg\">Détermine le terme</span> par <span class=\"nc-blue_bg\">LCC</span> + <span class=\"nc-blue_bg\">BIP</span> — <strong>précision <span>3–5 j</span></strong></li>\n                <li><span class=\"nc-yellow_bg\">Diagnostic des </span><strong><span class=\"nc-yellow_bg\">grossesses multiples</span></strong> et établit la <strong>chorionicité</strong> ⭐</li>\n                <li>Dépiste <span class=\"nc-red_bg\">certaines malformations</span> majeures (<span class=\"nc-red\">agénésie de</span> <span class=\"nc-red\">membre</span>, <span class=\"nc-red\">anencéphalie</span>…)</li>\n                <li>Mesure de la <strong><span class=\"nc-red_bg\">clarté nucale</span></strong> (normale <span>&lt; 3 mm</span>) pour estimation du risque T21</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>2 — <span><span class=\"nc-blue nc-bold\">Échographie</span></span> morphologique<br>(2<sup>e</sup> trimestre)</strong></td>\n            <td><span>22 SA</span></td>\n            <td>\n              <strong><span>Dépistage</span> des malformations ++</strong> :\n              <ul>\n                <li>Viabilité fœtale (MAF, activité cardiaque)</li>\n                <li>Biométrie : BIP, PA (périmètre abdo), LF (longueur fémorale)</li>\n                <li><span class=\"nc-yellow_bg\">Quantité de liquide amniotique</span></li>\n                <li>Localisation placentaire + cordon ombilical</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>3 — <span>Échographie</span> de croissance<br>(3<sup>e</sup> trimestre)</strong></td>\n            <td><span>32 SA</span></td>\n            <td>\n              <ul>\n                <li><span class=\"nc-green_bg\">Vitalité fœtale</span> (<span>score</span> de <strong>Manning</strong>, amnios, <span>Doppler</span> ombilical)</li>\n                <li>Croissance : biométrie (BIP, PA, LF, PC = périmètre crânien) → recherche RCIU / macrosomie</li>\n                <li>Confirme la localisation placentaire</li>\n                <li>Évalue la <span class=\"nc-yellow_bg\">quantité de liquide amniotique</span></li>\n                <li><strong>Type de présentation</strong> ⭐</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Premiers signes échographiques (rappel T1)</h4>\n\n      <ul>\n        <li><strong>Sac gestationnel</strong> : visible <span class=\"nc-pink nc-bold\">dès </span><span><span class=\"nc-pink nc-bold\">5 SA</span></span> par voie vaginale (hCG &gt; 1 <span>500 UI/L</span>)</li>\n        <li><strong>Activité cardiaque</strong> : visible <span class=\"nc-pink nc-bold\">dès </span><span><span class=\"nc-pink nc-bold\">5 SA</span> + 3 j</span> (LCC <span>≈ 4 mm</span>)</li>\n      </ul></div>"},{"i":"16a7bf5854e8","n":23,"o":"23-13","u":"Prise en charge","t":"Connaître les motifs de consultation les plus fréquents concernant les petits maux des femmes dans le cadre d’une grossesse","q":"Que retenir concernant les motifs de consultation les plus fréquents concernant les petits maux des femmes dans le cadre d’une grossesse ?","a":"<div class=\"notion-course\"><p>Les <span>petits maux de la grossesse</span> sont des symptômes physiologiques fréquents, à reconnaître pour les distinguer d’une vraie complication et pouvoir rassurer la patiente.</p>\n\n      <h4>1<sup>er</sup> trimestre</h4>\n\n      <ul>\n        <li><strong><span>Nausées</span></strong>, <strong><span>vomissements</span></strong></li>\n        <li><strong>Ptyalisme</strong> (= <span class=\"nc-blue_bg\">hypersalivation</span>), <strong><span>constipation</span></strong></li>\n        <li><span><span class=\"nc-orange_bg\">Anorexie</span></span>, <span><span class=\"nc-orange_bg\">boulimie</span></span>, <strong><span class=\"nc-orange_bg\">hypersomnie</span></strong></li>\n        <li><strong>Tension mammaire</strong></li>\n        <li>Douleurs ligamentaires</li>\n      </ul>\n\n      <h4>2<sup>nd</sup> trimestre</h4>\n\n      <ul>\n        <li><strong><span class=\"nc-blue_bg\">Chloasma</span></strong> (<span class=\"nc-blue_bg\">masque de </span><span><span class=\"nc-blue_bg\">grossesse</span></span>), <span class=\"nc-blue_bg\">vergetures</span>, <span class=\"nc-blue_bg\">varices</span></li>\n        <li><span class=\"nc-orange_bg\">Hémorroïdes</span>, <span class=\"nc-orange_bg\">varices vulvaires</span>, <span><span class=\"nc-orange_bg\">constipation</span></span></li>\n        <li><span><span class=\"nc-blue_bg\">Œdèmes des membres inférieurs</span></span>, <span class=\"nc-blue_bg\">crampes</span></li>\n        <li>Douleurs pelviennes : <span><span class=\"nc-purple_bg\">cystite</span></span>, <span class=\"nc-purple_bg\">candidose</span></li>\n        <li><strong><span class=\"nc-red nc-bold\">Anémie</span></strong></li>\n        <li>Congestion nasale, saignements de nez, saignements gingivaux</li>\n      </ul>\n\n      <h4>3<sup>e</sup> trimestre</h4>\n\n      <ul>\n        <li><span>Œdèmes</span> et <span class=\"nc-blue_bg\">crampes des membres inférieurs</span></li>\n        <li><strong><span class=\"nc-orange_bg\">Lombalgies</span></strong>, <span class=\"nc-orange_bg\">sciatalgie</span>, <strong><span class=\"nc-orange_bg\">compression du nerf médian</span></strong></li>\n        <li><span class=\"nc-green_bg\">Contractions utérines</span> (Braxton-Hicks), <span class=\"nc-green_bg\">sécrétion lactée</span></li>\n        <li><strong><span class=\"nc-orange_bg\">Pyrosis</span> et RGO</strong>, <span class=\"nc-orange_bg\">insomnies</span> nocturnes, <span><span class=\"nc-blue_bg\">prurit</span></span></li>\n        <li><span><span class=\"nc-blue_bg\">Palpitations</span></span>, <span><span class=\"nc-blue_bg\">dyspnée</span></span></li>\n        <li>Impériosités mictionnelles (compression vésicale par l’utérus), <span class=\"nc-orange_bg\">hémorroïdes</span>, <span class=\"nc-blue_bg\">varices</span></li>\n      </ul>\n\n      <p>📌 Tout symptôme dépassant le cadre du « petit mal » (hémorragie, <span>fièvre</span>, contractions précoces, <span>céphalée</span> + <span>HTA</span> + <span>protéinurie</span>, ↓ MAF…) doit faire <strong>réorienter en <span>urgence</span> vers la maternité</strong> (cf obj-14).</p></div>"},{"i":"ab8ad0817bfc","n":23,"o":"23-14","u":"Prise en charge","t":"Connaître les mesures médicamenteuses et non médicamenteuses concernant les petits maux de la grossesse","q":"Que retenir concernant les mesures médicamenteuses et non médicamenteuses concernant les petits maux de la grossesse ?","a":"<div class=\"notion-course\"><p>Le focus principal de la fiche source concerne les <strong><span>vomissements</span> et <span>nausées</span></strong> — symptôme le plus fréquent du 1<sup>er</sup> trimestre.</p>\n\n      <h4><span>Vomissements</span> physiologiques (≈<span> 50 %</span> des grossesses)</h4>\n\n      <ul>\n        <li><strong>Quand ?</strong> <span class=\"nc-red nc-bold\">Au 1</span><sup><span class=\"nc-red nc-bold\">er</span></sup><span class=\"nc-red nc-bold\"> trimestre</span>, s’atténuent à la fin du T1</li>\n        <li><strong>Cause</strong> : effet de l’<strong>hCG</strong> et des <strong>œstrogènes</strong></li>\n        <li><strong>Manifestations</strong> : <span>vomissements</span> sans retentissement sur l’état général, dégoût pour certains aliments</li>\n      </ul>\n\n      <h4>Orientation et soutien</h4>\n\n      <table>\n        <thead><tr><th>Volet</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Hospitalisation</span></strong></td>\n            <td>Si <strong><span>perte de poids</span> importante</strong> ou <strong><span>intolérance</span> alimentaire totale</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Soutien psychologique</strong></td>\n            <td>\n              Soutien moral voire aide psychologique car altération de la qualité de vie. <strong>Pas une pathologie psychiatrique</strong> : il ne s’agit pas d’un rejet de la <span>grossesse</span>, c’est une pathologie hormonale.\n              <br>⚠️ À <strong>bannir</strong> : isolement du cercle familial, mise dans le noir, confiscation du téléphone portable.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Mesures non médicamenteuses — conseils hygiéno-diététiques</h4>\n\n      <table>\n        <thead><tr><th>À éviter</th><th>À préférer</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <ul>\n                <li><span class=\"nc-red_bg\">Aliments aux </span><strong><span class=\"nc-red_bg\">odeurs trop fortes</span></strong></li>\n                <li><span class=\"nc-red_bg\">Casser le </span><strong><span class=\"nc-red_bg\">cercle vicieux du jeûne</span></strong> (le jeûne aggrave les <span>nausées</span>)</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span class=\"nc-green_bg\">Aliments qui </span><strong><span class=\"nc-green_bg\">donnent envie</span></strong></li>\n                <li><span class=\"nc-green_bg\">Aliments qui passent plus facilement : </span><strong><span class=\"nc-green_bg\">soupes, féculents</span></strong></li>\n                <li><strong><span class=\"nc-green_bg\">Gingembre</span></strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Comment manger</h4>\n\n      <ul>\n        <li><strong><span class=\"nc-green_bg\">Fractionner les repas</span></strong> : petites quantités plus souvent</li>\n        <li><span class=\"nc-green_bg\">Manger lentement, bien mâcher</span></li>\n        <li><strong><span class=\"nc-red_bg\">Éviter de se coucher trop vite</span></strong><span class=\"nc-red_bg\"> après le repas</span></li>\n      </ul>\n\n      <h4>Mesures médicamenteuses (formes sévères)</h4>\n\n      <table>\n        <thead><tr><th>Catégorie</th><th>Molécules</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Médicaments <span>à éviter</span></strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"nc-red nc-bold\">Antiémétiques</span> classiques</strong> (<span><span class=\"nc-red nc-bold\">métoclopramide</span></span>, <span>métopimazine</span>, <span>dompéridone</span>) — <em>généralement peu efficaces</em></li>\n                <li><span><span class=\"nc-red nc-bold\">Métoclopramide</span> : CONTRE-INDIQUÉ chez la femme enceinte ❌</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Médicaments préférés</strong></td>\n            <td>\n              <ul>\n                <li><span><span class=\"nc-pink_bg\">Pyridoxine (vitamine B6)</span></span>, seule ou associée à <span><span class=\"nc-pink_bg\">doxylamine</span></span></li>\n                <li><span class=\"nc-pink_bg\">Antagonistes des récepteurs </span><span><span class=\"nc-pink_bg\">H1</span></span> : <span>hydroxyzine</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p>📌 <em>Exceptionnellement, les <span>vomissements</span> peuvent entraîner une <span>carence en vitamine B1 → Gayet-Wernicke</span>.</em></p>\n\n      <h4>Hyperemesis gravidarum — focus</h4>\n\n      <ul>\n        <li>Forme sévère du T1, résistante au traitement symptomatique</li>\n        <li>Fréquence : <span>0,35 %</span> des grossesses</li>\n        <li>Origine inconnue (psychogène suspectée)</li>\n        <li>Manifestations : <span><span class=\"nc-orange_bg\">déshydratation</span></span>, <span><span class=\"nc-orange_bg\">dénutrition</span></span>, <span><span class=\"nc-blue_bg\">pertes ioniques</span></span>, <span><span class=\"nc-blue_bg\">cétonurie</span></span>, <span><span class=\"nc-blue_bg\">cytolyse</span></span>, <span>cholestase ± ictère</span></li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 27 — Prévention risques fœtaux</em></p></div>"},{"i":"6c6c917fa709","n":23,"o":"23-15","u":"Diagnostic positif","t":"Savoir reconnaitre les principales complications de la grossesse et savoir orienter les femmes vers le recours adapté","q":"Que retenir concernant reconnaitre les principales complications de la grossesse et savoir orienter les femmes vers le recours adapté ?","a":"<div class=\"notion-course\"><p>Plusieurs complications doivent être <span>reconnues précocement</span> au cours du <span>suivi</span> pour orienter vers le recours adapté (<span>hospitalisation</span>, maternité de niveau adéquat, <span>urgence</span> obstétricale).</p>\n\n      <h4>Complications pouvant être prévenues par un bon <span>suivi</span></h4>\n\n      <ul>\n        <li><strong>Anémie</strong> · <strong><span>HTA</span> gravidique / <span class=\"nc-red nc-bold\">pré-éclampsie</span></strong> · Immunisation Rh</li>\n        <li><span>Infection urinaire</span> (<span>BU</span> systématique tout au long du <span>suivi</span>) · IST</li>\n        <li><strong><span class=\"nc-red nc-bold\">Macrosomie</span></strong> et prise en charge du <strong><span>diabète gestationnel</span></strong></li>\n        <li>Présentation en <strong>siège</strong></li>\n        <li><strong>Travail prématuré</strong> · <strong>RCIU</strong></li>\n        <li><strong>Hypoxie / MFIU</strong> en cas de terme dépassé</li>\n      </ul>\n\n      <h4>Causes d’une hauteur utérine anormale (à dépister cliniquement)</h4>\n\n      <table>\n        <thead><tr><th>HU insuffisante</th><th>HU excessive</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <ul>\n                <li><span class=\"nc-green\">Erreur de terme</span></li>\n                <li><strong><span class=\"nc-red nc-bold\">Oligoamnios isolé</span></strong> ou associé à un <strong><span class=\"nc-red nc-bold\">RCIU</span></strong></li>\n                <li><span class=\"nc-green\">Enfant petit pour l’âge gestationnel</span></li>\n                <li><span class=\"nc-green\">Faux positif</span> de l’examen clinique</li>\n                <li><strong><span class=\"nc-red nc-bold\">Arrêt de la </span><span><span class=\"nc-red nc-bold\">grossesse</span></span> (MFIU)</strong></li>\n                <li>RPM</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li><span class=\"nc-green\">Erreur de terme</span></li>\n                <li><span><span class=\"nc-green\">Grossesse</span></span><span class=\"nc-green\"> multiple</span></li>\n                <li><strong>Macrosomie fœtale</strong></li>\n                <li><strong><span class=\"nc-red nc-bold\">Hydramnios</span></strong></li>\n                <li><strong><span class=\"nc-red nc-bold\">Utérus fibromateux</span></strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>CAT</strong> : toute HU anormale impose un <strong><span class=\"nc-blue nc-bold\">contrôle échographique</span></strong>.</p>\n\n      <h4><span>Vomissements</span> au 3<sup>e</sup> trimestre — deux <span class=\"nc-yellow_bg\">urgences thérapeutiques</span></h4>\n\n      <ul>\n        <li><strong><span class=\"nc-red nc-bold\">Stéatose aiguë gravidique</span></strong> (<span>0,01 %</span> des grossesses)</li>\n        <li><strong><span class=\"nc-red nc-bold\">Pré-éclampsie</span></strong></li>\n      </ul>\n\n      <h4>Hyperemesis gravidarum — forme sévère du 1<sup>er</sup> trimestre</h4>\n\n      <ul>\n        <li>Fréquence : <span>0,35 %</span> des grossesses</li>\n        <li>Résistant aux traitements symptomatiques</li>\n        <li>Manifestations : <span><span class=\"nc-orange_bg\">déshydratation</span></span>, <span><span class=\"nc-orange_bg\">dénutrition</span></span>, <span><span class=\"nc-blue_bg\">pertes ioniques</span></span>, <span><span class=\"nc-blue_bg\">cétonurie</span></span>, <span><span class=\"nc-blue_bg\">cytolyse</span></span>, <span><span class=\"nc-blue_bg\">cholestase ± ictérique</span></span></li>\n        <li><span>Hospitalisation</span> si <span>perte de poids</span> importante ou <span>intolérance</span> alimentaire totale</li>\n        <li>📌 <span>Vomissements</span> sévères → risque de carence en B1 → <strong>Gayet-Wernicke</strong></li>\n      </ul>\n\n      <h4><span class=\"nc-red nc-bold\">Anémie</span> de la <span>grossesse</span> — seuils diagnostiques</h4>\n\n      <table>\n        <thead><tr><th>Période</th><th>Seuil Hb</th></tr></thead>\n        <tbody>\n          <tr><td>Anémie 1<sup>er</sup> trimestre</td><td><span>&lt; 11 g/dL</span></td></tr>\n          <tr><td><strong>Anémie 2<sup>e</sup> trimestre</strong></td><td><span>&lt; 10,5 g/dL</span></td></tr>\n          <tr><td>Anémie 3<sup>e</sup> trimestre</td><td><span>&lt; 11 g/dL</span></td></tr>\n          <tr><td><strong>Carence martiale</strong></td><td><span>Ferritine</span> <span>&lt; 12 μg/L</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Signaux d’alerte (orientation urgente)</h4>\n\n      <ul>\n        <li><span>Métrorragies du 1<sup>er</sup> trim</span> → suspicion <em>GEU / FCS / môle</em> (cf items 25, 26)</li>\n        <li><span>Métrorragies du 3<sup>e</sup> trim</span> → suspicion <em>placenta prævia / HRP</em></li>\n        <li><span>HTA, protéinurie, œdème</span> → suspicion <em>pré-éclampsie</em></li>\n        <li><span><span class=\"nc-green_bg\">Contractions utérines</span> avant terme</span> → <span>menace</span> d’<span class=\"nc-red nc-bold\">accouchement prématuré</span></li>\n        <li><span>Diminution des MAF ou HU stagnante</span> → MFIU / RCIU à éliminer</li>\n        <li><span>BU</span> <strong><span>nitrites</span> / <span>leucocytes</span> +</strong> → <span>ECBU</span> et traitement ciblé (<span>pyélonéphrite gravidique = urgence</span>)</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 24 — Complications de la <span>grossesse</span> · 25 — Grossesse extra-utérine · 26 — Douleur abdo aiguë chez femme enceinte · 30 — Prématurité, <span class=\"nc-red nc-bold\">RCIU</span> · 255 — <span>Diabète gestationnel</span></em></p></div>"},{"i":"79df1774771a","n":23,"o":"23-16","u":"Prise en charge","t":"Le projet de naissance","q":"Que retenir concernant le projet de naissance ?","a":"<div class=\"notion-course\"><p>Historiquement, la préparation à la naissance était centrée sur la <strong>prise en charge de la douleur</strong>. Elle s’oriente <strong>actuellement</strong> vers un <span>accompagnement global</span> de la femme et du couple en favorisant leur participation active dans le projet de naissance.</p>\n\n      <h4>Définition</h4>\n\n      <p>Le <span>projet de naissance</span> = <strong>conjonction entre les aspirations de la femme/couple et l’offre de soins locale</strong>.</p>\n\n      <h4>Contenu du projet</h4>\n\n      <ul>\n        <li><strong>Organisation des soins</strong> : <span>suivi</span> médical et préparation à la naissance et à la parentalité</li>\n        <li><strong>Modalités d’accouchement</strong></li>\n        <li><strong>Possibilités de <span>suivi</span> postnatal</strong>, y compris conditions d’un <strong>retour précoce à domicile</strong></li>\n        <li><strong>Recours en cas de difficultés</strong></li>\n      </ul>\n\n      <h4>Formalisation</h4>\n\n      <ul>\n        <li>Peut être <strong>formalisé par un document écrit</strong> rédigé par les parents.</li>\n        <li>S’élabore au fil des consultations (<span>EPP</span> du 4<sup>e</sup> mois +++, <span class=\"nc-pink nc-bold\">8 séances</span> de PNP).</li>\n        <li>Doit pouvoir être <strong>discuté et adapté</strong> en fonction du niveau de risque évolutif et du choix de la maternité.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 31 — Accouchement - suites de couche normales · 33 — <span>Allaitement</span> maternel</em></p></div>"},{"i":"d78d5a984034","n":23,"o":"23-17","u":"Suivi et/ou pronostic","t":"Intégrer la dimension psychosociale au suivi de la femme enceinte et du couple","q":"Que retenir concernant intégrer la dimension psychosociale au suivi de la femme enceinte et du couple ?","a":"<div class=\"notion-course\"><p>Le <span>suivi</span> de <span>grossesse</span> ne se limite pas aux gestes médicaux : il intègre une <span>approche psychosociale globale</span> dont l’<span>EPP</span> du 4<sup>e</sup> mois constitue le pivot.</p>\n\n      <h4><span class=\"nc-blue_bg\">Entretien prénatal précoce</span> (<span>EPP</span>)</h4>\n\n      <table>\n        <thead><tr><th>Item</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Définition</strong></td><td>1<sup>ère</sup> séance de la <strong>préparation à la naissance et à la parentalité (PNP)</strong> — <span class=\"nc-pink nc-bold\">8 séances</span> au total.</td></tr>\n          <tr><td><strong>Pour qui ?</strong></td><td>Individuel <strong>ou en couple</strong>.</td></tr>\n          <tr><td><strong>Quand ?</strong></td><td>Proposé systématiquement <strong>autour du 4<sup>e</sup> mois</strong>, plus tôt ou plus tard selon le besoin.</td></tr>\n          <tr><td><strong>Si refus ?</strong></td><td>Le refus de l’<span>EPP</span> <strong>ne doit pas empêcher</strong> la participation aux 7 autres séances de PNP.</td></tr>\n          <tr><td><strong>Par qui ?</strong></td><td>Professionnel de la périnatalité (essentiellement <strong><span class=\"nc-green_bg\">sages-femmes</span></strong>), parfois <span class=\"nc-green_bg\">médecin</span> formé.</td></tr>\n          <tr><td><strong>Durée</strong></td><td><span>45 minutes</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Contenu de l’<span>EPP</span></h4>\n\n      <ul>\n        <li><strong>Répondre aux questions, rassurer</strong>, permettre l’expression libre</li>\n        <li>Message : <em>« la <span>grossesse</span> n’est pas une maladie »</em> — travail, activité physique, trajets, sexualité possibles</li>\n        <li><strong><span class=\"nc-green_bg\">Recommandations alimentaires</span></strong> (toxoplasmose si séronégative, listériose)</li>\n        <li><strong><span><span class=\"nc-orange_bg\">Tabac</span></span> +++</strong> : arrêt / <span>sevrage</span> par substituts nicotiniques · <strong>Cannabis</strong> (<span>1 joint = 7 cigarettes</span>)</li>\n        <li><strong><span><span class=\"nc-orange_bg\">Alcool</span></span> +++</strong> : <span class=\"nc-red nc-bold\">tolérance zéro</span> (pas de seuil fœtotoxique déterminé)</li>\n        <li><span class=\"nc-pink_bg\">Opiacés</span>, <span class=\"nc-pink_bg\">psychotropes</span> (automédication d’anxiolytiques)</li>\n        <li><span class=\"nc-red_bg\">Dépister les</span> <strong><span class=\"nc-pink nc-bold\">perturbateurs endocriniens</span></strong></li>\n        <li>Carences (ATCD <span>chirurgie</span> bariatrique, végétariennes / végétaliennes) → supplémenter <strong>B9, B12</strong> si besoin</li>\n      </ul>\n\n      <h4>Examen postnatal de la femme</h4>\n\n      <table>\n        <thead><tr><th>Item</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Quand ?</strong></td><td><strong>&lt;<span> 6 à 8 semaines</span></strong> après l’accouchement.</td></tr>\n          <tr><td><strong>Caractère</strong></td><td><strong>Obligatoire</strong>.</td></tr>\n          <tr><td><strong>Qui ?</strong></td><td><span class=\"nc-green_bg\">Médecin</span> (généraliste ou spécialiste) <strong>ou <span class=\"nc-green_bg\">sage-femme</span></strong> (si <span>grossesse</span> et accouchement normaux).</td></tr>\n          <tr>\n            <td><strong>Éléments évoqués</strong></td>\n            <td>\n              <ul>\n                <li>Vécu de l’accouchement et suites, retour à domicile, relations mère / enfant / famille, reprise de la sexualité</li>\n                <li><strong>Recherche d’une <span><span class=\"nc-orange_bg\">dépression</span></span><span class=\"nc-orange_bg\"> du post-partum</span></strong></li>\n                <li>Examen gynécologique proposé (non systématique), <span>dépistage</span> du cancer du col si besoin</li>\n                <li><strong>Rééducation périnéale</strong> recommandée pour traiter :\n                  <ul>\n                    <li><strong><span class=\"nc-red nc-bold\">Incontinence urinaire</span></strong><span class=\"nc-red nc-bold\"> persistant à </span><span><span class=\"nc-red nc-bold\">3 mois</span></span> du post-partum</li>\n                    <li><strong><span class=\"nc-red nc-bold\">Incontinence anale</span></strong><span class=\"nc-red nc-bold\"> du post-partum</span></li>\n                  </ul>\n                </li>\n                <li>Discussion du <strong>souhait de contraception</strong></li>\n                <li>Congé pathologique supplémentaire <span class=\"nc-yellow_bg\">postnatal</span> de <strong><span>4 semaines</span></strong> si pathologie maternelle</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table></div>"},{"i":"e1053bf38848","n":23,"o":"23-18","u":"Prise en charge","t":"Savoir informer la patiente de sa couverture sociale pendant la grossesse","q":"Que retenir concernant informer la patiente de sa couverture sociale pendant la grossesse ?","a":"<div class=\"notion-course\"><p>Connaître les modalités de prise en charge à<span> 100 %</span> et le cadre légal du <strong><span class=\"nc-green_bg\">congé maternité</span></strong> est essentiel pour informer la patiente.</p>\n\n      <h4>Prise en charge à<span> 100 %</span> par l’assurance maladie</h4>\n\n      <ul>\n        <li><strong>8 consultations prénatales</strong> (examens obligatoires) jusqu’au 6<sup>e</sup> mois</li>\n        <li>Couverture médicale à <strong><span>100 %</span> à partir de 24 SA</strong></li>\n        <li><strong>Bilan <span class=\"nc-yellow_bg\">prénatal</span> de prévention</strong> (alimentation, <span>tabac</span>, <span><span class=\"nc-orange_bg\">alcool</span></span>) à réaliser avant 24 SA — <span class=\"nc-green_bg\">sage-femme</span> libérale ou de PMI</li>\n        <li><strong>Bilan bucco-dentaire</strong> au 4<sup>e</sup> mois</li>\n        <li><strong>Examen de santé pour le futur père</strong> si besoin</li>\n        <li><strong>Consultation postnatale obligatoire</strong></li>\n        <li><strong>3 échographies obstétricales</strong> (non obligatoires mais remboursées à<span> 100 %</span>)</li>\n      </ul>\n\n      <h4><span class=\"nc-green_bg\">Congé maternité</span> — principe</h4>\n\n      <p>Toute salariée en état de <span>grossesse</span> médicalement constatée a le droit de <strong>suspendre son contrat de travail</strong> pendant une durée déterminée, avant et après son accouchement, sans que cela ne constitue ni une cause de <span>rupture</span> ni une modification du contrat de travail.</p>\n\n      <h4>Conditions</h4>\n\n      <ul>\n        <li>Immatriculation <strong><span>≥ 10 mois</span></strong> à la date prévue d’accouchement.</li>\n      </ul>\n\n      <h4>Durée légale</h4>\n\n      <ul>\n        <li><strong><span>16 semaines</span> minimum</strong>, composées de :\n          <ul>\n            <li>Congé <strong><span class=\"nc-yellow_bg\">prénatal</span></strong> (débute à <span>35 SA</span>) : <span><span class=\"nc-pink nc-bold\">6 semaines</span></span><span class=\"nc-pink nc-bold\"> </span><strong><span class=\"nc-pink nc-bold\">avant</span></strong> l’accouchement</li>\n            <li>Congé <strong><span class=\"nc-yellow_bg\">postnatal</span></strong> : <span><span class=\"nc-pink nc-bold\">10 semaines</span></span><span class=\"nc-pink nc-bold\"> </span><strong><span class=\"nc-pink nc-bold\">après</span></strong> l’accouchement</li>\n          </ul>\n        </li>\n      </ul>\n\n      \n\n      <h4>Durée variable selon enfants</h4>\n\n      <table>\n        <thead>\n          <tr><th>Enfants à naître</th><th>Enfants déjà à charge</th><th>Prénatal</th><th>Postnatal</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>1</strong></td><td>0 ou 1</td><td><strong><span>6 semaines</span></strong></td><td><strong><span>10 semaines</span></strong></td></tr>\n          <tr><td><strong>1</strong></td><td>2 ou plus</td><td><strong><span>8 semaines</span></strong></td><td><strong><span>18 semaines</span></strong></td></tr>\n          <tr><td><strong>2</strong></td><td>—</td><td><strong><span>12 semaines</span></strong></td><td><strong><span>22 semaines</span></strong></td></tr>\n          <tr><td><strong>3 ou plus</strong></td><td>—</td><td><strong><span>24 semaines</span></strong></td><td><strong><span>22 semaines</span></strong></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Modulations</h4>\n\n      <table>\n        <thead><tr><th>Situation</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Salaire</strong></td>\n            <td>\n              <ul>\n                <li>L’employeur n’est pas tenu en théorie de maintenir le salaire — en pratique, c’est presque toujours le cas</li>\n                <li>Indemnités = <span class=\"nc-green_bg\">salaire moyen des 3 derniers mois</span> ou salaire journalier de base, dans la <strong>limite d’un plafond</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Durée raccourcie</strong></td>\n            <td>La future mère peut, à sa demande et après accord du <span class=\"nc-green_bg\">médecin</span> ou de la <span class=\"nc-green_bg\">sage-femme</span>, <strong>réduire de <span>3 semaines</span></strong> le congé <span class=\"nc-yellow_bg\">prénatal</span> — le <span class=\"nc-yellow_bg\">postnatal</span> est augmenté d’autant.</td>\n          </tr>\n          <tr>\n            <td><strong>Durée allongée</strong></td>\n            <td>\n              <ul>\n                <li><strong><span><span class=\"nc-red nc-bold\">Grossesse</span></span><span class=\"nc-red nc-bold\"> pathologique</span></strong> : congé <span class=\"nc-yellow_bg\">prénatal</span> supplémentaire jusqu’à <strong><span><span class=\"nc-pink nc-bold\">2 semaines</span></span></strong></li>\n                <li><span class=\"nc-red_bg\">Caractère pathologique de l’accouchement ou du post-partum</span></li>\n                <li>Selon le nombre d’enfants à charge et attendus</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Congé paternité</strong></td>\n            <td><span>25 jours</span> (payés par la sécurité sociale).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 31 — Accouchement - suites de couche normales · 36 — Contraception</em></p></div>"},{"i":"345b56ee13bc","n":23,"o":"23-19","u":"Définition","t":"Connaître l’existence des violences obstétricales","q":"Que retenir concernant l’existence des violences obstétricales ?","a":"<div class=\"notion-course\"><p><span>Violences obstétricales et gynécologiques</span> = <span class=\"nc-red_bg\">comportements, actes, paroles ou omissions commis par un professionnel de santé</span>, <strong>non justifiés médicalement</strong> ou <span class=\"nc-red_bg\">accomplis </span><strong><span class=\"nc-red_bg\">sans le consentement libre et éclairé de la femme</span></strong>.</p>\n\n      <h4>Qui et quand ?</h4>\n\n      <ul>\n        <li><strong>Responsables</strong> : tout intervenant de santé quel que soit son statut, son genre ou son âge.</li>\n        <li><strong>Périodes à risque</strong> : <span>suivi</span> gynécologique, parcours PMA, suivi de <span>grossesse</span>, accouchement, post-partum — <em>période périnatale particulièrement à risque</em> (gestes nombreux, sphère intime).</li>\n      </ul>\n\n      <h4>Les 7 dimensions des violences</h4>\n\n      <ul>\n        <li>Violence <strong><span class=\"nc-red\">physique</span></strong></li>\n        <li>Violence <strong><span class=\"nc-red\">sexuelle</span></strong></li>\n        <li>Violence <strong><span class=\"nc-red\">verbale</span></strong></li>\n        <li><strong><span class=\"nc-green_bg\">Stigmatisation et discrimination</span></strong> (racisme, homophobie…)</li>\n        <li><strong><span class=\"nc-orange_bg\">Absence de respect des règles de bonne pratique</span></strong>, soins inappropriés</li>\n        <li><strong><span class=\"nc-orange_bg\">Mauvais rapport</span></strong> entre la femme et un (des) soignant(s)</li>\n        <li><strong><span class=\"nc-orange_bg\">Violence institutionnelle</span></strong> (mauvaises conditions et contraintes dues au système de santé)</li>\n      </ul>\n\n      <h4>Fréquence</h4>\n\n      <ul>\n        <li>Mal connue : <span>13 à 100 %</span> selon les études.</li>\n        <li>Enquête française (réseau de Bourgogne) : <span>69 %</span> des femmes estimaient <em>ne pas</em> avoir subi de violence.</li>\n      </ul>\n\n      <h4>Standards OMS 2017</h4>\n\n      <p>L’OMS a publié <strong>8 normes de qualité</strong> des soins maternels et néonatals (31 chartes de qualité) pour évaluer dans quelle mesure les services améliorent les résultats de santé et sont <em>sûrs, efficaces, opportuns, équitables et centrés sur les personnes</em>.</p>\n\n      <table>\n        <thead>\n          <tr><th>Standard</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>1</strong></td><td>Soins basés sur les données factuelles (travail, accouchement, post-partum, complications) selon recommandations OMS.</td></tr>\n          <tr><td><strong>2</strong></td><td>Système d’information sanitaire permettant une décision rapide et appropriée.</td></tr>\n          <tr><td><strong>3</strong></td><td>Transfert des femmes / nouveau-nés vers établissements adaptés si pathologie hors ressources locales.</td></tr>\n          <tr><td><strong>4</strong></td><td>Communication efficace, respectant les besoins et préférences.</td></tr>\n          <tr><td><strong>5</strong></td><td>Soins dispensés avec respect et maintien de la dignité.</td></tr>\n          <tr><td><strong>6</strong></td><td>Soutien psychosocial aux femmes et à leur famille.</td></tr>\n          <tr><td><strong>7</strong></td><td>Personnel compétent et motivé disponible à tout moment.</td></tr>\n          <tr><td><strong>8</strong></td><td>Environnement adéquat (énergie, eau, médicaments, matériel) pour soins courants et complications.</td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>Règle absolue</strong> : le <span>consentement</span> doit être <strong>systématiquement recueilli avant tout soin</strong>.</p></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d941810aa257ea761f7dfbc0?pvs=204","reviewedAt":"2026-10-15","note":"Cours personnel, couleurs des passages Notion correspondants, corrections et parcours interactifs sourcés. Les compléments sont distingués des figures d’origine."},"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Grossesse suspectée ou confirmée ?","detail":"<ul><li>Retard de règles, symptômes et test adapté.</li></ul>","branches":[{"label":"Douleur, saignement ou malaise","to":"urgent"},{"label":"Sans signe d’alarme","to":"dater"}]},{"id":"urgent","kind":"urgent","label":"Évaluation obstétricale rapide","detail":"<ul><li>Exclure GEU ou autre complication ; urgences si mauvaise tolérance.</li></ul>","branches":[]},{"id":"dater","kind":"decision","label":"Dater et évaluer les risques","detail":"<ul><li>DDR, échographie de datation, antécédents et risques psychosociaux/professionnels.</li></ul>","branches":[{"label":"Risque identifié","to":"orienter"},{"label":"Grossesse à bas risque","to":"planifier"}]},{"id":"orienter","kind":"decision","label":"Adapter professionnels et maternité","detail":"<ul><li>Suivi partagé/spécialisé selon pathologie et besoins néonataux.</li></ul>","branches":[{"label":"Construire le calendrier","to":"planifier"}]},{"id":"planifier","kind":"decision","label":"Déclaration, consultations et dépistages","detail":"<ul><li>Examens obligatoires/proposés, échographies, choix éclairé pour T21.</li></ul>","branches":[{"label":"Prévention et confort","to":"accompagner"}]},{"id":"accompagner","kind":"decision","label":"Accompagner les choix et petits maux","detail":"<ul><li>Projet de naissance, consentement, prévention et traitements compatibles.</li></ul>","branches":[{"label":"Surveillance jusqu’au post-partum","to":"suivre"}]},{"id":"suivre","kind":"finish","label":"Réévaluer à chaque consultation","detail":"<ul><li>Symptômes d’alarme, PA, croissance, vécu et besoins ; orienter si évolution.</li></ul>","branches":[]}]}};
